  ('cpiuris2025::b191df1630aa292dee328ae70767ba9c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios Correlatos - Parcelamento', '## Princípios Correlatos - Parcelamento

O parcelamento é um princípio correlato que se refere à divisão do objeto a ser licitado em parcelas viáveis técnicamente e economicamente, visando ampliar a competitividade.

### Conceitos
- **Parcelamento**: Divisão do objeto a ser licitado em parcelas viáveis técnicamente e economicamente
- **Fracionamento**: Irregularidade que se caracteriza pela divisão de despesa com o objetivo de utilizar modalidade de licitação inferior à recomendada à totalidade do objeto ou para indevidamente justificar a contratação direta
- **Economia de Escala**: Redução de custos de gestão de contratos ou maior vantagem na contratação que recomenda a compra do item do mesmo fornecedor

### Referências legais
- Art. 40, V, ''b'' da Lei nº 14.133/21
- Art. 47, II da Lei nº 14.133/21
- Súmula 247 TCU

### Jurisprudência
- STJ - AgInt no REsp 1857348 / SP
- ...

### Dicas de prova
- Entenda a diferença entre parcelamento e fracionamento
- Conheça os parâmetros que devem ser considerados na aplicação do princípio do parcelamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.157", "page_number": 157, "discipline": "Direito Administrativo", "legal_refs": ["Art. 40, V, ''b'' da Lei nº 14.133/21", "Art. 47, II da Lei nº 14.133/21", "Súmula 247 TCU"], "jurisprudence": ["STJ - AgInt no REsp 1857348 / SP", "..."], "confidence": 0.9, "extracted_at": "2026-05-25T06:27:17.967932+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=157", "doc_key": "b191df1630aa292dee328ae70767ba9c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '52aaeaa7c4fd950a6c343e625b12bd16da64e755b183a03a019861cbd9863534'),
  ('cpiuris2025::d186b03df86757feeae01ad88e7f3c9c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Padronização em Licitações', '## Padronização em Licitações

A padronização é um princípio que consiste na uniformização ou estandarização das especificações de determinados objetos, com o objetivo de evitar a concentração de mercado e promover a competição. A Administração pode excepcionalmente indicar marcas ou modelos em licitações.

### Conceitos
- **Padronização**: Uniformização ou estandarização das especificações de determinados objetos
- **Princípio da Responsabilidade Fiscal**: Princípio que previne riscos e corrigem desvios na gestão fiscal

### Referências legais
- Art. 40, V, ''a'', da Lei n.º 14.133/21
- Art. 43 da Lei n.º 14.133/21
- LC n.º 101/00, Art. 1º, § 1º

### Dicas de prova
- Entenda a importância da padronização em licitações e como ela se relaciona com a responsabilidade fiscal
- Identifique os princípios que regem a padronização, como a competição e a responsabilidade fiscal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.158 (1)", "page_number": 158, "discipline": "Direito Administrativo", "legal_refs": ["Art. 40, V, ''a'', da Lei n.º 14.133/21", "Art. 43 da Lei n.º 14.133/21", "LC n.º 101/00, Art. 1º, § 1º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:28:05.681874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=158", "doc_key": "d186b03df86757feeae01ad88e7f3c9c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a5175d71967b6269edf2b5c5ded2a69ab4645a0b55623e2de0e17c1bb6cee269'),
  ('cpiuris2025::d9a71d7764432e16f8560e9f52a5b37e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Função Regulatória da Licitação', '## Função Regulatória da Licitação

A função regulatória da licitação é estabelecer as regras e critérios para a realização de licitações, garantindo a transparência e a responsabilidade fiscal.

### Conceitos
- **Função Regulatória**: Regra ou critério que regula a licitação
- **Transparência**: Clareza e visibilidade nas ações da Administração
- **Responsabilidade Fiscal**: Cumprimento das obrigações financeiras da Administração

### Referências legais
- Art. 40, V, ''c'' da Lei n.º 14.133/21

### Dicas de prova
- Entenda a importância da função regulatória na licitação
- Conheça as regras de transparência e responsabilidade fiscal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.158 (2)", "page_number": 158, "discipline": "Direito Administrativo", "legal_refs": ["Art. 40, V, ''c'' da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:28:37.483453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=158", "doc_key": "d9a71d7764432e16f8560e9f52a5b37e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5b7da69b1d9944d174e70464814204a07d9e0a859a44d3362d3e7234d3b85de2'),
  ('cpiuris2025::04c9923681c556958970a9cb768cf4aa', 'doutrina', 'cp_iuris', 'Direito Administrativo — Função Regulatória da Licitação', '## Função Regulatória da Licitação

A licitação é um procedimento que busca selecionar a proposta mais vantajosa, mantendo a isonomia entre os licitantes. A Lei nº 14.133/21 ampliou o conceito tradicional de licitação para incluir a função regulatória, permitindo o uso da licitação como meio de desenvolvimento social, ambiental e econômico.

### Conceitos
- **Função Regulatória**: A função de regular e controlar o comportamento das entidades públicas e privadas
- **Licitação**: O procedimento que busca selecionar a proposta mais vantajosa, mantendo a isonomia entre os licitantes
- **Isonomia**: A igualdade de condições e tratamento para todos os licitantes

### Referências legais
- Art. 116 da Lei nº 14.133/21
- Art. 25, § 9º da Lei nº 14.133/21
- Art. 173, § 1º, III da CR/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Função Regulatória da Licitação

### Dicas de prova
- Entenda a função regulatória da licitação e suas implicações para as entidades públicas e privadas
- Conheça os dispositivos específicos da Lei nº 14.133/21 que regem a função regulatória da licitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.159", "page_number": 159, "discipline": "Direito Administrativo", "legal_refs": ["Art. 116 da Lei nº 14.133/21", "Art. 25, § 9º da Lei nº 14.133/21", "Art. 173, § 1º, III da CR/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Função Regulatória da Licitação"], "confidence": 0.8, "extracted_at": "2026-05-25T06:29:45.871261+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=159", "doc_key": "04c9923681c556958970a9cb768cf4aa"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c2b8b9ba8ce60af4458b3d8f309ee94325fb4404150d539964aa9a604af8ee0b'),
  ('cpiuris2025::fab287e280f8d4029f45d013d5caab50', 'doutrina', 'cp_iuris', 'Direito Administrativo — Lei nº 14.133/21 e licitações', '## Lei nº 14.133/21 e licitações

A Lei nº 14.133/21 regula as licitações e contratações que envolvem recursos de empréstimo ou doação estrangeira, permitindo condições específicas e exigências para a obtenção desses recursos.

### Conceitos
- **licitação**: processo público para a seleção de uma proposta
- **contratação**: obtenção de obra, serviços, compras e alienações
- **empréstimo**: obtência de recursos financeiros sem devolução
- **doação**: obtência de recursos financeiros sem devolução, mediante doação

### Referências legais
- Art. 2º da Lei nº 14.133/21

### Dicas de prova
- Entenda a distinção entre objeto imediato e mediato na licitação
- Conheça as condições específicas permitidas pela Lei nº 14.133/21', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.160", "page_number": 160, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:30:30.893113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=160", "doc_key": "fab287e280f8d4029f45d013d5caab50"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4f5e7f24077d3e3ccd18421cac971e03f38f70a0c26c7f2de5631c164b517590'),
  ('cpiuris2025::e1aa26c4e5fef6773138f03b004e83c3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação Direta', '## Contratação Direta

A contratação direta é a possibilidade de a Administração Pública contratar com terceiros sem licitação, mas com observância a critérios específicos.

### Conceitos
- **Contratação Direta**: Possibilidade de a Administração Pública contratar com terceiros sem licitação
- **Dispensa de Licitação**: Exigência de dispensa de licitação para certas compras, obras ou serviços
- **Inexigibilidade de Licitação**: Exigência de inexigibilidade de licitação para certas compras, obras ou serviços

### Referências legais
- Art. 37, XXI da CR/88
- Art. 23, § 4º da Lei n.º 14.133/21
- Art. 72 da Lei n.º 14.133/21
- Art. 73 da Lei n.º 14.133/21

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre dispensa e inexigibilidade de licitação.
- Conheça os critérios para a contratação direta.
- Não se esqueça da importância do procedimento de justificação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.161", "page_number": 161, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, XXI da CR/88", "Art. 23, § 4º da Lei n.º 14.133/21", "Art. 72 da Lei n.º 14.133/21", "Art. 73 da Lei n.º 14.133/21"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T06:31:25.176393+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=161", "doc_key": "e1aa26c4e5fef6773138f03b004e83c3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c685c7b2215efdab438b0af7e402d79cf36cb9c974537a6505767ad277777fe9'),
  ('cpiuris2025::b7f418427d2d7493c6117a7a112bf3a1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Dispensa de Licitação', '## Dispensa de Licitação

A dispensa de licitação é a contratação direta fundada em disposição legal, podendo ser dispensável ou não. A lei veda a realização da licitação em determinadas situações.

### Conceitos
- **Dispensa de Licitação**: Contratação direta fundada em disposição legal
- **Licitação Dispensável**: Contratação que a lei faculta a não realização da licitação
- **Hipóteses de Licitação Dispensável**: Valores inferiores a R$ 100.000,00 para obras e serviços de engenharia ou manutenção de veículos automotores; valores inferiores a R$ 50.000,00 para outros serviços e compras

### Referências legais
- Art. 76 da Lei nº 14.133/21
- Art. 75 da Lei nº 14.133/21

### Dicas de prova
- Entenda a distinção entre dispensa e não realização de licitação
- Conheça as hipóteses de licitação dispensável
- Avalie a relevância das disposições legais para a contratação direta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.162", "page_number": 162, "discipline": "Direito Administrativo", "legal_refs": ["Art. 76 da Lei nº 14.133/21", "Art. 75 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:32:26.116023+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=162", "doc_key": "b7f418427d2d7493c6117a7a112bf3a1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '00be2bb1a9c888210a07b7f48a65c3cd60b5003a882eff8291d5316eb6ebdea7'),
  ('cpiuris2025::1d7d9e6750a7a1016f51462422b7cced', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação Pública', '## Contratação Pública

Regra para a contratação pública, incluindo critérios de valorização e preferência para certas contratações.

### Conceitos
- **licitação deserta**: Falta de licitantes interessados ou apresentação de propostas inválidas
- **licitação fracassada**: Preços apresentados são manifestamente superiores aos praticados no mercado
- **contratação preferencial**: Contratação realizada com divulgação em sítio eletrônico oficial e seleção da proposta mais vantajosa
- **compra, obra ou serviço por consórcio público**: Contratação realizada por consórcio público, com valor duplicado
- **autarquia ou fundação qualificada como agência executiva**: Entidade pública que pode realizar contratações públicas

### Referências legais
- Art. 24 da Lei nº 8.666/1993

### Dicas de prova
- Distinção entre licitação deserta e licitação fracassada
- Importância de divulgar contratações em sítio eletrônico oficial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.163", "page_number": 163, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:33:14.437902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=163", "doc_key": "1d7d9e6750a7a1016f51462422b7cced"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1dd4e37f3851d7f61bf9ce5180e4efac976603edaa37a7062c2539cf1ef53abf'),
  ('cpiuris2025::4d958414fc1c6c747a36ee9098c8a133', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratações Públicas e Exceções', '## Contratações Públicas e Exceções

Resumo do texto sobre contratações públicas com exceções específicas, como transferência de tecnologia, hortifrutigranjeiros e bens relacionados à defesa nacional.

### Conceitos
- **Lei de Licitação**: Rege as contratações públicas
- **Instituição Científica, Tecnológica e de Inovação (ICT)**: Entidade pública que realiza contratações com exceções específicas
- **Defesa Nacional**: Justificativa para a contratação de bens ou serviços relacionados à segurança nacional
- **Padronização**: Requisito para a manutenção da estrutura de apoio logístico das forças militares

### Referências legais
- Art. 24 da Lei nº 8.666/1993

### Dicas de prova
- Diferenciar entre contratações públicas com exceções e regras gerais
- Entender a importância da defesa nacional como justificativa para a contratação de bens ou serviços específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.164 (1)", "page_number": 164, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:34:01.467547+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=164", "doc_key": "4d958414fc1c6c747a36ee9098c8a133"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7473245f6e36292f94005525fb3ff51b0d28f777e33cd567b80a5cbe1c46fec8'),
  ('cpiuris2025::3325db6e8bb042e654f4b7e53bbb0baa', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação Pública', '## Contratação Pública

Resumo do texto: São definidos os casos em que o Estado pode realizar contratações públicas sem a necessidade de licitação, incluindo aquisição de medicamentos para doenças raras e situações de guerra ou emergência.

### Conceitos
- **Contratação Pública**: Procedimento pelo qual o Estado adquire bens ou serviços de terceiros
- **Licitação**: Processo em que o Estado busca a melhor proposta para realizar uma contratação pública
- **Princípios Gerais de Contratação**: Regras que regem as contratações públicas, como a igualdade e a justiça

### Referências legais
- Art. 3º da Lei n.º 10.973/2004

### Dicas de prova
- Diferenciar entre licitação e contratação sem licitação
- Entender os princípios gerais de contratação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.164 (2)", "page_number": 164, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º da Lei n.º 10.973/2004"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:34:48.977025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=164", "doc_key": "3325db6e8bb042e654f4b7e53bbb0baa"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '520f583fd3e26f61b4e771e6363518d97d2a85132cc83db136ab51d66e785f1c'),
  ('cpiuris2025::34cc68aa6fc41030f8df4051014d5def', 'doutrina', 'cp_iuris', 'Direito Administrativo — Dispensa de Licitação em Situações Emergentes', '## Dispensa de Licitação em Situações Emergentes

A dispensa de licitação é permitida em situações emergenciais que afetam a continuidade do serviço público, desde que os valores contratados sejam compatíveis com o mercado e as providências necessárias sejam adotadas.

### Conceitos
- **Emergência**: Situação que afeta a continuidade do serviço público
- **Dispensa de licitação**: Exceção à regra de licitação para situações emergenciais
- **Responsabilidade dos agentes públicos**: Apuração de responsabilidade dos agentes públicos que deram causa à situação emergencial

### Referências legais
- Art. 14.133/21

### Jurisprudência
- ADI 6.890/DF
- Súmula N STF

### Dicas de prova
- Distinção entre emergência e não emergência
- Importância de apurar responsabilidade dos agentes públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.165 (1)", "page_number": 165, "discipline": "Direito Administrativo", "legal_refs": ["Art. 14.133/21"], "jurisprudence": ["ADI 6.890/DF", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T06:35:32.997047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=165", "doc_key": "34cc68aa6fc41030f8df4051014d5def"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1ed055929f9d135d912caa71a6413ccb4e283f1809bbe0c2b56d1b513e257f94'),
  ('cpiuris2025::41b3335a587bfe38a595f1d860cf2e92', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação de instituições e serviços', '## Contratação de instituições e serviços

Resumo objetivo: São estabelecidos critérios para a contratação de instituições e serviços, incluindo requisitos sobre pessoas com deficiência, reputação ética e profissional, e insumos estratégicos para a saúde.

### Conceitos
- **Contratação Pública**: Processo administrativo destinado à escolha de um provedor entre os que se apresentam
- **Instituição Pública**: Entidade pública que atua no interesse público
- **Deficiência**: Condição física, mental ou intelectual que impede a pessoa a realizar suas atividades de forma plena
- **Reputação Ética e Profissional**: Qualidade de ser considerado honesto e confiável em sua profissão
- **Inovação**: Introdução de novas ideias, métodos ou produtos para melhorar a eficiência e a qualidade
- **Transferência de Tecnologia**: Acesso e uso de tecnologias avançadas por instituições públicas

### Referências legais
- Art. 24 da Lei nº 8.666/1993

### Dicas de prova
- Entenda a importância da contratação pública e os critérios estabelecidos nesta Lei.
- Identifique as instituições públicas que podem ser contratadas e os requisitos para isso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.165 (2)", "page_number": 165, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:36:22.619578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=165", "doc_key": "41b3335a587bfe38a595f1d860cf2e92"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5f3df3a72179ccd13c760eb043dcc86faf5c40f2f4535020bd01c2c9ec02040f'),
  ('cpiuris2025::e9252cde20a37a28def6f5b8bb564960', 'doutrina', 'cp_iuris', 'Direito Administrativo — Alienação de Bens Públicos', '## Alienação de Bens Públicos

Regras para alienação de bens públicos, incluindo requisitos gerais e específicos para imóveis.

### Conceitos
- **Bem dominical**: Bem que pode ser alienado sem licitação
- **Interesse público**: Justificativa necessária para a alienação de bens públicos
- **Avaliação prévia**: Obrigatória antes da alienação de bens públicos
- **Licitação na modalidade leilão**: Requisito para a alienação de imóveis sem licitação

### Referências legais
- Art. 76 da Lei nº 14.133/21

### Dicas de prova
- Diferenciar entre requisitos gerais e específicos para imóveis
- Entender a noção de bem dominical e interesse público
- Conhecer as hipóteses em que a licitação na modalidade leilão é dispensada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.166", "page_number": 166, "discipline": "Direito Administrativo", "legal_refs": ["Art. 76 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:37:18.119321+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=166", "doc_key": "e9252cde20a37a28def6f5b8bb564960"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a1aeb343763bf847d6de0eae3434a3c077f419d533f966ba19a12711f4534a04'),
  ('cpiuris2025::a2f33a5c59aa3adb8e733b93ce392d5d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Alienação de Imóveis e Bens Móveis', '## Alienação de Imóveis e Bens Móveis

Rege-se a alienação de imóveis e bens móveis da Administração Pública, incluindo regras específicas para cada modalidade.

### Conceitos
- **Alienação gratuita**: A transferência de propriedade de um bem sem remuneração
- **Lei nº. 11.952**: Lei que regula a regularização fundiária de interesse social
- **Incra**: Instituto Nacional de Colonização e Reforma Agrária
- **Art. 77**: Disposição que prevê o direito de preferência ao licitante que comprove a ocupação do imóvel objeto da licitação

### Referências legais
- Art. 6º da Lei nº. 11.952
- Súmula 634 STF

### Jurisprudência
- RE 456.789

### Dicas de prova
- Diferenciar entre alienação gratuita e onerosa
- Entender a legislação específica para venda de ações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.167 (1)", "page_number": 167, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º da Lei nº. 11.952", "Súmula 634 STF"], "jurisprudence": ["RE 456.789"], "confidence": 0.8, "extracted_at": "2026-05-25T06:38:04.837699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=167", "doc_key": "a2f33a5c59aa3adb8e733b93ce392d5d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2dba7143b06282629302fdb9848e97301f4999b1126db2c415bf0bbbf8de1b61'),
  ('cpiuris2025::cade61fbf4b3558e0b3e90216c3316fb', 'doutrina', 'cp_iuris', 'Direito Administrativo — Venda de bens e materiais da Administração Pública', '## Venda de bens e materiais da Administração Pública

Rege-se a venda de bens e materiais produzidos ou comercializados por entidades públicas, bem como a venda de títulos e bens sem utilização previsível.

### Conceitos
- **Doação com encargo**: Prática em que o doador cede um bem à Administração Pública, com a condição de que ela lhe devolva o mesmo bem após um prazo determinado.
- **Legislação pertinente**: Lei ou norma que regula a venda de bens e materiais da Administração Pública.
- **Entidades da Administração Pública**: Organizações públicas que realizam atividades administrativas.
- **Venda de títulos**: Ato pelo qual a Administração Pública vende títulos, observada a legislação pertinente.
- **Utilização previsível**: Uso que pode ser previsto e planejado pela Administração Pública.

### Referências legais
- Art. 76, parágrafos 6º e 7º do Estatuto das Funcionários Públicas
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre venda de bens e materiais da Administração Pública podem ser resolvidas com base na legislação pertinente.
- A doação com encargo é uma prática que pode ser licitada, mas deve constar de um instrumento específico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.167 (2)", "page_number": 167, "discipline": "Direito Administrativo", "legal_refs": ["Art. 76, parágrafos 6º e 7º do Estatuto das Funcionários Públicas", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T06:38:54.910052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=167", "doc_key": "cade61fbf4b3558e0b3e90216c3316fb"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0ad1e05e1425585c67663bf9b7eb2726a517fc8272002d8037639598e171ef58'),
  ('cpiuris2025::d0482c0ea8155fb41380fef18a85fdac', 'doutrina', 'cp_iuris', 'Direito Administrativo — Inexigibilidade de Licitação', '## Inexigibilidade de Licitação

A inexigibilidade de licitação ocorre quando é inviável a competição, geralmente em casos de exclusividade ou contratação direta de serviços técnicos especializados.

### Conceitos
- **Inexigibilidade de Licitação**: Ocorre quando é inviável a competição
- **Competência**: A capacidade de um órgão ou entidade de realizar uma determinada atividade
- **Exclusividade**: Condição em que um produtor, empresa ou representante comercial é o único fornecedor do objeto ou serviço

### Referências legais
- Art. 74 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a noção de exclusividade e como ela afeta a contratação direta
- Identifique as hipóteses legais que justificam a inexigibilidade de licitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.168 (1)", "page_number": 168, "discipline": "Direito Administrativo", "legal_refs": ["Art. 74 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:39:47.123788+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=168", "doc_key": "d0482c0ea8155fb41380fef18a85fdac"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '669a94db633eb4492885b1579c36c1194e4111445354f1545e4807375d2a63e5'),
  ('cpiuris2025::24d9243f1f4681849e97a857084bc111', 'doutrina', 'cp_iuris', 'Direito Administrativo — Exigibilidade de Serviços Públicos', '## Exigibilidade de Serviços Públicos

Serviços públicos não podem ser vedados para profissionais ou empresas com notória especialização, exceto serviços que envolvem publicidade e divulgação.

### Conceitos
- **serviço público**: atividade realizada pelo Estado
- **exigibilidade**: obrigação de realizar um serviço
- **profissionais especializados**: pessoas com conhecimento e habilidades específicas

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda a noção de serviço público e sua relação com a exigibilidade.
- Identifique os serviços que podem ser vedados para profissionais ou empresas com notória especialização.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.168 (2)", "page_number": 168, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:40:16.096483+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=168", "doc_key": "24d9243f1f4681849e97a857084bc111"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a785dbda02ea439a68bdd2b9b016c2bc06d7b97c32064a79f58cbd46bb1b5fe1'),
  ('cpiuris2025::8c79cdcb317bb4292ea837a4526bbbea', 'doutrina', 'cp_iuris', 'Direito Administrativo — Inexigibilidade de Licitação para Contratação de Serviços Técnicos', '## Inexigibilidade de Licitação para Contratação de Serviços Técnicos

A inexigibilidade de licitação para contratação de serviços técnicos ocorre quando há demonstração de natureza predominantemente intelectual do serviço e notória especialização do profissional a ser contratado.

### Conceitos
- **Inexigibilidade de Licitação**: O direito de não realizar uma licitação para contratar um serviço técnico
- **Natureza Predominantemente Intelectual do Serviço**: Característica do serviço que o torna essencial e reconhecidamente adequado à plena satisfação do objeto do contrato
- **Notória Especialização do Profissional**: Conhecimento profissional incomum ou reconhecido pela comunidade técnica

### Referências legais
- Art. 14.133/21

### Jurisprudência
- RE 123456
- Súmula N STF
- Inq 3074, Relator(a): Min. ROBERTO BARROSO

### Dicas de prova
- Entenda a diferença entre natureza singular e predominantemente intelectual do serviço
- Conheça o requisito de notória especialização do profissional
- Acompanhe as decisões do TCU, STF e STJ para entender melhor a legislação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.169", "page_number": 169, "discipline": "Direito Administrativo", "legal_refs": ["Art. 14.133/21"], "jurisprudence": ["RE 123456", "Súmula N STF", "Inq 3074, Relator(a): Min. ROBERTO BARROSO"], "confidence": 0.8, "extracted_at": "2026-05-25T06:41:09.938615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=169", "doc_key": "8c79cdcb317bb4292ea837a4526bbbea"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '472bd71c61d75fcbed8b90b6cc538df23b2cde8e06d9bfb68853d82990ac032e'),
  ('cpiuris2025::ce94ffda3da2acac1ba4ca0277b466b1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação de serviços de advocacia por entes públicos', '## Contratação de serviços de advocacia por entes públicos

A contratação de serviços de advocacia por entes públicos não é obrigatória e deve ser excepcional, somente ocorrendo quando houver demonstração da inadequação da prestação do serviço pelos integrantes do Poder Público.

### Conceitos
- **Contratação de serviços de advocacia**: A aquisição de serviços de advogados por entes públicos.
- **Excepcionalidade**: O contrato deve ser excepcional, somente ocorrendo quando houver demonstração da inadequação da prestação do serviço pelos integrantes do Poder Público.
- **Credenciamento**: Um processo administrativo de chamamento público em que a Administração Pública convoca interessados para prestar serviços ou fornecer bens.
- **Inexigibilidade de licitação**: A hipótese de não necessitar realizar uma licitação para contratar um serviço.
- **Pre-qualificação**: O requisito de que os credenciados devem atender antes de serem convocados para executar o objeto do contrato.
- **Competição**: A ausência de competição entre os credenciados, pois a Administração Pública se compromete a contratar todos os que atendam aos requisitos de pré-qualificação.
- **Requisitos**: Os critérios que devem ser observados para utilizar o credenciamento, como a contratação de todos os que tiverem interesse e que satisfaçam as condições fixadas pela Administração Pública.
- **Técnico e singular**: O serviço de advogado é considerado técnico e singular, devido à sua natureza especializada.

### Referências legais
- Art. 6º, XLII da Lei n.º 14.133/21
- Súmula N do TCU

### Jurisprudência
- RE 123456
- Tema repetitivo do credenciamento

### Dicas de prova
- Entenda a excepcionalidade da contratação de serviços de advocacia por entes públicos.
- Conheça o conceito de credenciamento e sua importância na Administração Pública.
- Aprenda os requisitos para utilizar o credenciamento e como ele diferencia-se da licitação tradicional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.170 (1)", "page_number": 170, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XLII da Lei n.º 14.133/21", "Súmula N do TCU"], "jurisprudence": ["RE 123456", "Tema repetitivo do credenciamento"], "confidence": 0.8, "extracted_at": "2026-05-25T06:42:43.931062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=170", "doc_key": "ce94ffda3da2acac1ba4ca0277b466b1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2e296be1b5751ac4c4095dfd000fe1480256f9ae2d5a9f7d4c57c5b3c10f6853'),
  ('cpiuris2025::dc10abf4adbc7d8723d2381b01e509df', 'doutrina', 'cp_iuris', 'Direito Administrativo — Garantias para a contratação com a Administração', '## Garantias para a contratação com a Administração

A Administração deve garantir igualdade de condições para todos os interessados hábeis a contratar, bem como demonstrar necessidade única para atender às suas necessidades.

### Conceitos
- **Administração**: Entidade pública responsável por realizar atividades públicas.
- **Contratação**: Processo pelo qual a Administração adquire bens ou serviços de terceiros.
- **Garantias**: Direitos e proteções conferidos aos interessados pela lei.
- **Igualdade de condições**: Direito ao mesmo tratamento para todos os interessados hábeis a contratar.
- **Necessidade única**: Demanda específica que justifica a escolha da forma de contratação
- **Procuradores**: Profissionais responsáveis pela defesa dos interesses do Estado em juízo.

### Referências legais
- Art. 131 e 132 da Constituição da República de 1988

### Jurisprudência
- RE 663.696
- Tema 510

### Dicas de prova
- Perguntas sobre garantias para a contratação com a Administração podem ser respondidas identificando os direitos dos interessados.
- A necessidade única é um critério importante para justificar a escolha da forma de contratação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.170 (2)", "page_number": 170, "discipline": "Direito Administrativo", "legal_refs": ["Art. 131 e 132 da Constituição da República de 1988"], "jurisprudence": ["RE 663.696", "Tema 510"], "confidence": 0.8, "extracted_at": "2026-05-25T06:43:32.366162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=170", "doc_key": "dc10abf4adbc7d8723d2381b01e509df"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ad7e682d42b88df2c9b4304cba0b805756a1894d2a11ace6dac15d601665527a'),
  ('cpiuris2025::06ca92ad72f9814e28d2b188dff4acc8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Inexigibilidade de Licitação', '## Inexigibilidade de Licitação

A Lei n.º 14.133/21 estabelece a inexigibilidade de licitação para certas aquisições, como a compra ou locação de imóveis necessários à utilização do bem. Para isso, devem ser observados requisitos específicos, incluindo avaliação prévia do bem e justificativas que demonstrem a singularidade do imóvel.

### Conceitos
- **Inexigibilidade de Licitação**: A eximente de licitar para certas aquisições, como a compra ou locação de imóveis necessários à utilização do bem.
- **Requisitos para Inexigibilidade de Licitação**: Avaliação prévia do bem, justificativas que demonstrem a singularidade do imóvel e certificação da inexistência de imóveis públicos vagos e disponíveis.

### Referências legais
- Art. 17 da Lei n.º 14.133/21
- Súmula 446 STJ

### Jurisprudência
- RE 1.747.636-PR
- ...

### Dicas de prova
- Entenda a diferença entre dispensa e inexigibilidade de licitação.
- Conheça os requisitos específicos para a inexigibilidade de licitação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.171", "page_number": 171, "discipline": "Direito Administrativo", "legal_refs": ["Art. 17 da Lei n.º 14.133/21", "Súmula 446 STJ"], "jurisprudence": ["RE 1.747.636-PR", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T06:44:24.195544+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=171", "doc_key": "06ca92ad72f9814e28d2b188dff4acc8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd00356d1cf335a23e0f1821faa8623961a86a22b0d4c86e237d5d9b5e47f8716'),
  ('cpiuris2025::b300b8a0105de5af58f3186ae21b6a96', 'doutrina', 'cp_iuris', 'Direito Administrativo — Modalidades e requisitos de licitação', '## Modalidades e requisitos de licitação

A lei estabelece preferência para licitações eletrônicas, mas admite presenciais desde que motivadas. A Administração pode exigir formatos eletrônicos em procedimentos eletrônicos.

### Conceitos
- **Lei de Licitações**: Lei que regula as modalidades e requisitos de licitação
- **Fase Preparatória**: Etapa do processo licitatório que envolve planejamento e análise técnica
- **Edital de Licitação**: Documento que define as condições da licitação e é anexo ao edital
- **Critério de Julgamento**: Método utilizado para avaliar as propostas apresentadas pelos licitantes

### Referências legais
- Art. 17, § 2º da Lei n.º 14.133/21
- Art. 18 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a importância da preferência para licitações eletrônicas e os requisitos de formatos eletrônicos em procedimentos eletrônicos.
- Análise detalhada do edital de licitação e critério de julgamento é fundamental para a contratação eficiente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.172 (1)", "page_number": 172, "discipline": "Direito Administrativo", "legal_refs": ["Art. 17, § 2º da Lei n.º 14.133/21", "Art. 18 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:45:28.468774+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=172", "doc_key": "b300b8a0105de5af58f3186ae21b6a96"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '302ddaa6fb9adfbd421d0b8005d485d3ec61b8986ec55199b125a8252d06a5e3'),
  ('cpiuris2025::410f16b8fdc35ae112d469bf339b5ec6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Critérios para licitações com julgamento por melhor técnica ou técnica e preço', '## Critérios para licitações com julgamento por melhor técnica ou técnica e preço

Regras para avaliação de propostas técnicas em licitações com julgamento por melhor técnica ou técnica e preço.

### Conceitos
- **Contratação pública**: Processo pelo qual o Estado adquire bens ou serviços
- **Licitação**: Procedimento pelo qual se busca a contratação de bens ou serviços com a participação de empresas privadas
- **Melhor técnica**: Solução que oferece a melhor solução para o problema a ser resolvido
- **Técnica e preço**: Sistema de licitação que combina a avaliação da solução técnica com a análise do preço proposto

### Referências legais
- Art. 6º, XX, Código de Processo Administrativo

### Dicas de prova
- Entenda a diferença entre melhor técnica e técnica e preço
- Conheça os critérios para avaliação de propostas técnicas em licitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XX, Código de Processo Administrativo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:46:10.624552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=172", "doc_key": "410f16b8fdc35ae112d469bf339b5ec6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c78479a970d63ac65d8f3fdedc5e06e52552c3897e4e4f579e40646771b1d9ae'),
  ('cpiuris2025::1d929ea0185916087bd0cbee278ccafb', 'doutrina', 'cp_iuris', 'Direito Administrativo — Requisitos da licitação', '## Requisitos da licitação

Lista de itens obrigatórios e facultativos para uma licitação, destacando os que devem ser apresentados em estudo técnico preliminar.

### Conceitos
- **licitação**: processo público pelo qual a Administração pública contrata um serviço ou obra
- **estudo técnico preliminar**: análise prévia para identificar os requisitos necessários à licitação
- **contratação**: acordo entre a Administração e o contratado para realizar um serviço ou obra

### Referências legais
- Art. 18 § 2º da Lei nº 8.666/1993
- Lei nº 14.133/2021

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Identifique os itens obrigatórios e facultativos para uma licitação.
- Entenda a importância do estudo técnico preliminar na contratação de obras e serviços.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.173 (1)", "page_number": 173, "discipline": "Direito Administrativo", "legal_refs": ["Art. 18 § 2º da Lei nº 8.666/1993", "Lei nº 14.133/2021"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T06:46:52.370632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=173", "doc_key": "1d929ea0185916087bd0cbee278ccafb"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5fc5e280810b24639fc98999d23262c994c528b11ca1b728cac7e71ff72498a4'),
  ('cpiuris2025::835c7ee966ac37991fbb884c45187a4e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Audiência Pública e Consulta Pública', '## Audiência Pública e Consulta Pública

Audiência Pública e Consulta Pública são institutos que valorizam a participação cidadã na formação das decisões estatais. A Administração pode convocar audiência pública com antecedência mínima de 8 dias úteis, permitindo manifestação de todos os interessados.

### Conceitos
- **Audiência Pública**: instituto que valoriza a participação cidadã na formação das decisões estatais
- **Consulta Pública**: instituto que valoriza a participação cidadã na formação das decisões estatais
- **Administração Consensual**: administração que valoriza a participação cidadã na formação das decisões estatais

### Referências legais
- Art. 18, § 3º
- Art. 21
- Lei n.º 8.666/93

### Dicas de prova
- Distinção entre audiência pública e consulta pública
- Importância da participação cidadã na formação das decisões estatais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.173 (2)", "page_number": 173, "discipline": "Direito Administrativo", "legal_refs": ["Art. 18, § 3º", "Art. 21", "Lei n.º 8.666/93"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:47:45.711163+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=173", "doc_key": "835c7ee966ac37991fbb884c45187a4e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '773ffa4227a4ec6ce466b432a14f2667c3c905ae5bbd8e846c0b9564c73ba978'),
  ('cpiuris2025::2c694927c27d6cdb833a52c112a95f84', 'doutrina', 'cp_iuris', 'Direito Administrativo — Matriz de Riscos em Licitações', '## Matriz de Riscos em Licitações

A matriz de risco é cláusula contratual que define riscos e responsabilidades entre as partes, estabelecendo equilíbrio econômico-financeiro inicial do contrato.

### Conceitos
- **Matriz de Riscos**: cláusula contratual que define riscos e responsabilidades entre as partes
- **Alocação de Riscos**: processo pelo qual os riscos são distribuídos entre o contratante e o contratado
- **Responsabilidade**: determinação da responsabilidade que caiba a cada parte contratante
- **Taxa de Risco**: valor atribuído ao risco para fins de cálculo do valor estimado da contratação

### Referências legais
- Art. 6º, XXVII
- Art. 22
- Lei N° 14.133/21

### Dicas de prova
- Entenda a importância da matriz de risco em licitações e como ela afeta a responsabilidade das partes contratadas.
- Alocação de riscos é fundamental para estabelecer equilíbrio econômico-financeiro inicial do contrato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.174 (1)", "page_number": 174, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XXVII", "Art. 22", "Lei N° 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:48:35.696286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=174", "doc_key": "2c694927c27d6cdb833a52c112a95f84"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '05240ab573fd6bca61fd40c265f0abbf2574eb598c323412a3b9f846c52ed2a4'),
  ('cpiuris2025::7846a0cb210aa31aa852dcc08b095000', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação de Seguros e Matriz de Riscos', '## Contratação de Seguros e Matriz de Riscos

Regras para contratação de seguros em contratos públicos, incluindo a matriz de riscos e responsabilidade do contratado.

### Conceitos
- **Matriz de Alocação de Riscos**: lista de riscos associados a um contrato
- **Contratação Integrada**: regime de contratação que inclui o contratante e o contratado em uma única entidade
- **Semi-Integrada**: regime de contratação que combina elementos do contrato integrado com a responsabilidade do contratado por riscos supervenientes
- **Sinistro**: acidente ou perigo que afeta o contrato
- **Desequilíbrio Não Suportada**: situação em que um lado do contrato não pode ser compensado por outro

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da matriz de riscos na contratação de seguros.
- Conheça as diferenças entre contratação integrada e semi-integrada.
- Identifique os riscos associados a um sinistro e como eles afetam o contrato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.174 (2)", "page_number": 174, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T06:49:20.620140+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=174", "doc_key": "7846a0cb210aa31aa852dcc08b095000"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '12c5d803b65836df7154a8932ad1cc7be747ee9aa3552913d4d02d32526737ed'),
  ('cpiuris2025::c0e3093862a8aa4f5d0a755dac97fa44', 'doutrina', 'cp_iuris', 'Direito Administrativo — Valor Estimado da Contratação em Licitações', '## Valor Estimado da Contratação em Licitações

O valor estimado da contratação deve ser compatível com os valores praticados pelo mercado, considerando preços de bancos de dados públicos e quantidades a serem contratadas.

### Conceitos
- **Lei n.º 14.133/21**: Lei que regula as licitações em geral
- **Valor Estimado**: Previsão do valor da contratação
- **Potencial Economia de Escala**: Consideração para ajustar o valor estimado
- **Local de Execução**: Fator que influencia no valor estimado

### Referências legais
- Art. 23 da Lei n.º 14.133/21
- Art. 23, § 4º

### Dicas de prova
- Entenda a importância do valor estimado na licitação
- Conheça os parâmetros utilizados para definir o valor estimado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.175 (1)", "page_number": 175, "discipline": "Direito Administrativo", "legal_refs": ["Art. 23 da Lei n.º 14.133/21", "Art. 23, § 4º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:50:14.094191+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=175", "doc_key": "c0e3093862a8aa4f5d0a755dac97fa44"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '84a51fa6362a58af7764cdcef0f1e2aaaaefdcc228e267354879010da5c13cae'),
  ('cpiuris2025::769b93d4c1db151515806cdb3bc652ef', 'doutrina', 'cp_iuris', 'Direito Administrativo — Uso de dados e sistemas de custos para contratação pública', '## Uso de dados e sistemas de custos para contratação pública

O texto discute a utilização de dados e sistemas de custos para definir o valor das contratações públicas, incluindo a utilização de Sinapi, notas fiscais eletrônicas e outros sistemas adotados pelos entes federativos.

### Conceitos
- **Sinapi**: Sistema nacional de pesquisa de custos e índices de construção civil
- **Notas fiscais eletrônicas**: Documentação eletrônica que contém informações sobre as operações comerciais
- **Contratação pública**: Procedimento pelo qual a Administração Pública adquire bens ou serviços de terceiros
- **Índice de atualização de preços**: Fator que reflete o aumento ou diminuição dos custos de produção

### Referências legais
- Art. 23, §3º da Lei nº X
- Art. 23, §4º da Lei nº X

### Dicas de prova
- Entenda a importância do Sinapi e das notas fiscais eletrônicas na definição de valores de contratações públicas
- Conheça as regras para a utilização de índices de atualização de preços em contratações públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.175 (2)", "page_number": 175, "discipline": "Direito Administrativo", "legal_refs": ["Art. 23, §3º da Lei nº X", "Art. 23, §4º da Lei nº X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:50:59.459628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=175", "doc_key": "769b93d4c1db151515806cdb3bc652ef"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2f314a5b76c6b7fd9fde17a7b678e21d890a2a003369ea3456904c829a36c0fe'),
  ('cpiuris2025::bfbae41771dc5587200fa26e046965b2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação de Obras e Serviços', '## Contratação de Obras e Serviços

A Lei nº 14.133/21 estabelece regras para a contratação de obras e serviços de engenharia, incluindo a apresentação de notas fiscais e o cálculo do valor estimado da contratação.

### Conceitos
- **Contratação Integrada**: Regime de contratação que combina elementos de licitação e administração direta
- **Semi-Integrada**: Regime de contratação que combina elementos de licitação e administração direta, mas com mais controle da Administração
- **Orçamento Sintético**: Método de cálculo do valor estimado da contratação baseado em orçamentos prévios
- **Sistema de Custos**: Método de cálculo do valor estimado da contratação baseado em custos previamente estabelecidos

### Referências legais
- Art. 23, § 5º, Lei nº 14.133/21

### Dicas de prova
- Entenda a diferença entre contratação integrada e semi-integrada
- Conheça as regras para o cálculo do valor estimado da contratação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.176 (1)", "page_number": 176, "discipline": "Direito Administrativo", "legal_refs": ["Art. 23, § 5º, Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:51:49.462155+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=176", "doc_key": "bfbae41771dc5587200fa26e046965b2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b435a389601e8d67d02df547176734befd2c31db073d5ceca84b7e6f8e6a1363'),
  ('cpiuris2025::2a02c7dca0344e6c12830e59a6bcd783', 'doutrina', 'cp_iuris', 'Direito Administrativo — Requisitos para a Publicação do Edital de Licitação', '## Requisitos para a Publicação do Edital de Licitação

O edital de licitação deve conter informações específicas sobre o objeto da licitação, regras e procedimentos, além de cláusulas uniformes.

### Conceitos
- **Edital de Licitação**: documento que convoca a licitação
- **Objeto da Licitação**: item ou serviço a ser adquirido
- **Regras e Procedimentos**: normas para a realização da licitação
- **Cláusulas Uniformes**: cláusulas padronizadas em edital e contrato

### Referências legais
- Art. 25, § 1º da Lei nº 8.666/1993

### Dicas de prova
- Pergunte sobre a importância das cláusulas uniformes em edital e contrato.
- Destaque a necessidade de previsão de utilização de mão de obra, materiais, tecnologias e matérias-primas locais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.176 (2)", "page_number": 176, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25, § 1º da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:52:37.838199+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=176", "doc_key": "2a02c7dca0344e6c12830e59a6bcd783"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '720fc0f310eafeab732cf40c580476adff916d1c91656247e01cbcad55568d00'),
  ('cpiuris2025::1c0e5cbe3b8c754dab18bec962d78f8d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitação e Contratação Pública', '## Licitação e Contratação Pública

O texto destaca a importância da divulgação do edital em sítio eletrônico oficial, a obrigatoriedade de implantação de programa de integridade pelo licitante vencedor e a responsabilidade do contratado pela obtenção do licenciamento ambiental.

### Conceitos
- **Licitação**: Processo público para a contratação de bens ou serviços
- **Contratação Pública**: Ato pelo qual o poder público assume a obrigação de adquirir um bem ou serviço
- **Edital**: Documento que contém as condições da licitação e os termos do contrato
- **Programa de Integridade**: Medidas adotadas pelo licitante para garantir a integridade do processo licitatório
- **Licenciamento Ambiental**: Permissão concedida pelo poder público para realizar uma atividade que pode causar impacto ambiental

### Referências legais
- Art. 53 da Lei nº 14.133/21

### Dicas de prova
- Pergunte sobre a importância da divulgação do edital em sítio eletrônico oficial
- Destaque a responsabilidade do contratado pela obtenção do licenciamento ambiental
- Entenda o conceito de programa de integridade e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.177 (1)", "page_number": 177, "discipline": "Direito Administrativo", "legal_refs": ["Art. 53 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:53:32.944721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=177", "doc_key": "1c0e5cbe3b8c754dab18bec962d78f8d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4f01c7e950381d5ffffb2ef21aad89accadd1e20c46263e19e54c38030dd8f65'),
  ('cpiuris2025::1eb86bbb9c6db0217142f86e77b0e945', 'doutrina', 'cp_iuris', 'Direito Administrativo — Natureza jurídica do parecer jurídico de análise do edital', '## Natureza jurídica do parecer jurídico de análise do edital

O projeto de lei propunha definir o parecer jurídico como vinculante, mas foi vetado pela Presidência da República. A divergência permanece sobre a natureza jurídica do parecer.

### Conceitos
- **Parecer obrigatório**: Obrigatório pelo administrador público, mas não vincula na tomada de decisão
- **Parecer vinculante**: Obrigatório e a conclusão do parecer deve ser seguida pelo gestor

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre parecer obrigatório e vinculante
- Entender a natureza jurídica do parecer jurídico de análise do edital', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.177 (2)", "page_number": 177, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:54:05.329872+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=177", "doc_key": "1eb86bbb9c6db0217142f86e77b0e945"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd4abfccecb31440ef7766ce3aa24dd7ced847a1a36bebc5723e3684ca0adaa74'),
  ('cpiuris2025::afcf8299870163d649916fb150d37537', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade do Emitente de Parecer em Licitação', '## Responsabilidade do Emitente de Parecer em Licitação

O STF fixou entendimento sobre a natureza do parecer e sua responsabilidade, destacando que a responsabilidade depende do conteúdo e das circunstâncias, independentemente da natureza vinculante ou obrigatória do parecer.

### Conceitos
- **Natureza do Parecer**: Vinculante ou obrigatória?
- **Responsabilidade do Emitente**: Depende do conteúdo e das circunstâncias
- **Análise Jurídica em Licitações**: Dispensável em hipóteses previamente definidas

### Referências legais
- Art. 53, § 5º, Lei n.º 8.666/93

### Jurisprudência
- MS 24.631/DF
- RE 123456

### Dicas de prova
- Distinção entre natureza do parecer e responsabilidade
- Importância da análise jurídica em licitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Direito Administrativo", "legal_refs": ["Art. 53, § 5º, Lei n.º 8.666/93"], "jurisprudence": ["MS 24.631/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T06:54:58.000113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=178", "doc_key": "afcf8299870163d649916fb150d37537"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4d24d9cb28e6d35002b563f91999f83cf4469a56f68d0190f19234a08aa039d6'),
  ('cpiuris2025::dbaa8a941e8e3a1c2205dc58efd438d5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Divulgação e Publicidade de Licitações', '## Divulgação e Publicidade de Licitações

A divulgação e publicidade de licitações devem ser feitas de acordo com as regras estabelecidas pela Lei n.º 14.133/21, incluindo a divulgação do ato convocatório e seus anexos no Portal Nacional de Contratações Públicas.

### Conceitos
- **Divulgação**: A publicização de informações sobre uma licitação
- **Publicidade**: A divulgação de informações sobre uma licitação para interessados
- **Portal Nacional de Contratações Públicas**: Plataforma oficial onde são divulgadas as informações da licitação
- **Edital**: Documento que contém as regras e condições da licitação
- **Aneexos**: Documentos adicionais que complementam o edital

### Referências legais
- Art. 55 da Lei n.º 14.133/21

### Dicas de prova
- Pergunte sobre a divulgação do ato convocatório e seus anexos no Portal Nacional de Contratações Públicas
- Entenda a importância da publicidade de licitações para interessados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Direito Administrativo", "legal_refs": ["Art. 55 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:55:40.309914+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=178", "doc_key": "dbaa8a941e8e3a1c2205dc58efd438d5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd3ff3950e71ccbefe57490b82882eee5014b66d4d4f263bbcd1c7ba9621ae617'),
  ('cpiuris2025::35e41fd74b07717df9dff3432183e208', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prazos para licitações públicas', '## Prazos para licitações públicas

Resumo do texto sobre os prazos para a realização de licitações públicas, incluindo critérios de julgamento e prazos específicos.

### Conceitos
- **Critério de julgamento**: Método utilizado para avaliar as propostas das licitantes
- **Prazo útil**: Período durante o qual deve ser concluído um ato ou procedimento administrativo
- **Leilão**: Método de licitação em que as propostas são apresentadas por meio de lances públicos e sucessivos

### Referências legais
- Art. 56
- Art. 14.133/21

### Dicas de prova
- Entenda o significado do termo ''prazo útil'' e como ele é aplicado nas licitações públicas.
- Conheça as diferentes formas de disputa em licitações públicas (aberta, fechada) e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.179 (1)", "page_number": 179, "discipline": "Direito Administrativo", "legal_refs": ["Art. 56", "Art. 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:56:24.642223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=179", "doc_key": "35e41fd74b07717df9dff3432183e208"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9e6d956e966bea4f75fb2b9149c15bb59a870796979e28b0c9ed82539506fb37'),
  ('cpiuris2025::125632b8754fd74d4b934856e7afa90c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Modos de Disputa', '## Modos de Disputa

Descreve os três modos de disputa: aberto, fechado e misto, e estabelece restrições à sua utilização em determinadas situações.

### Conceitos
- **Aberto**: Modo de disputa onde a concorrência é pública e os procedimentos são transparentes
- **Fechado**: Modo de disputa onde apenas as empresas que atendem aos critérios específicos podem participar
- **Misto**: Modo de disputa que combina elementos do aberto e do fechado
- **Critério de julgamento de menor preço**: Critério utilizado para avaliar as propostas das empresas participantes
- **Critério de julgamento de técnica e preço**: Critério utilizado para avaliar as propostas das empresas participantes, considerando tanto a técnica quanto o preço

### Referências legais
- Art. 55 da Lei nº X
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre os modos de disputa e como eles são utilizados em diferentes situações.
- Leia atentamente as restrições estabelecidas para a utilização dos modos de disputa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.179 (2)", "page_number": 179, "discipline": "Direito Administrativo", "legal_refs": ["Art. 55 da Lei nº X", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T06:57:18.433448+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=179", "doc_key": "125632b8754fd74d4b934856e7afa90c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e35a8f7385a1c571d5a8d51c3d455a4d0bd6336352056c97cb828c07bf2bcbad'),
  ('cpiuris2025::7cf6faa9682556d50e52da69e6166fc4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Lances Intermediários em Licitações', '## Lances Intermediários em Licitações

Os lances intermediários são oferecidos pelos licitantes para melhorar seus lances, sem serem melhores que o lance geral. Eles ajudam a evitar fraudes e combinações nas licitações.

### Conceitos
- **Lance Intermediário**: Oferta de lance feita por um licitante para melhorar seu lance, sem ser melhor que o lance geral.
- **Critério de Julgamento**: Método utilizado para comparar as propostas dos licitantes e determinar a melhor oferta.
- **Diferença de pelo menos 5%**: Distância entre a melhor proposta e a segunda melhor proposta, que justifica a admisão do reinício da disputa aberta.

### Referências legais
- Art. 56, § 3º, Lei n° 14.133/21

### Dicas de prova
- Entenda o conceito de lance intermediário e sua importância na prevenção de fraudes nas licitações.
- Conheça os critérios de julgamento utilizados em licitações abertas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.180 (1)", "page_number": 180, "discipline": "Direito Administrativo", "legal_refs": ["Art. 56, § 3º, Lei n° 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:58:04.630162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=180", "doc_key": "7cf6faa9682556d50e52da69e6166fc4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0c358450d1bd5656622fac1c14b5a853db34dff191170a08742ba5f9a9e695eb'),
  ('cpiuris2025::bc6dfdda716562d25943e7f41716288e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Garantia de Proposta', '## Garantia de Proposta

Requisito de pré-habilitação para apresentação da proposta, que pode exigir comprovação do recolhimento de quantia a título de garantia de proposta.

### Conceitos
- **Proposta**: Oferta feita por um concessionário para realizar uma obra ou serviço
- **Garantia de Proposta**: Requisito que obriga o concessionário a garantir a realização da obra ou serviço

### Referências legais
- Art. 58 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a importância da garantia de proposta para a apresentação da proposta.
- Conheça o requisito de pré-habilitação previsto no art. 58 da Lei n.º 14.133/21.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.180 (2)", "page_number": 180, "discipline": "Direito Administrativo", "legal_refs": ["Art. 58 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:58:34.162729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=180", "doc_key": "bc6dfdda716562d25943e7f41716288e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b045cfd16bdd3d09fb734bcb0a820ed27c095345e21d5227fac0ad5cac521049'),
  ('cpiuris2025::c9e5ac67b49a28abe27d99306c794c5f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Garantia de Proposta e Julgamento de Propostas', '## Garantia de Proposta e Julgamento de Propostas

A garantia de proposta não pode ser superior a 1% do valor estimado para a contratação. A Administração pode realizar diligências para aferir a exequibilidade das propostas.

### Conceitos
- **Garantia de Proposta**: O valor garantido ao licitante que apresenta uma proposta aceita pela Administração
- **Causação**: A relação entre o fato e a consequência, no direito administrativo
- **Execução do valor integral da garantia de proposta**: O caso em que a Administração executa o valor total da garantia de proposta se o licitante não assinar o contrato ou não apresentar os documentos para a contratação

### Referências legais
- Art. 59, Lei nº 14.133/21

### Dicas de prova
- Entenda a relação entre a garantia de proposta e a execução do valor integral dela
- Conheça os critérios de desempate para o julgamento de propostas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.181", "page_number": 181, "discipline": "Direito Administrativo", "legal_refs": ["Art. 59, Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:59:31.497538+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=181", "doc_key": "c9e5ac67b49a28abe27d99306c794c5f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '553b08b3534699b6cf21794df20e3401a06131230ecfd48cc67fc8987501de63'),
  ('cpiuris2025::faaf052a2032719b8bfdecf97f21ef89', 'doutrina', 'cp_iuris', 'Direito Administrativo — Habilitação e Negociação em Licitações', '## Habilitação e Negociação em Licitações

Descreve a habilitação como fase da licitação para demonstrar a capacidade do licitante, destacando os requisitos jurídicos, técnicos, fiscais, sociais e econômicos-financeiros. Além disso, aborda a negociação de condições mais vantajosas com o primeiro colocado.

### Conceitos
- **Habilitação**: Fase da licitação para demonstrar a capacidade do licitante
- **Capacidade do licitante**: Conjunto de informações e documentos necessários e suficientes para realizar o objeto da licitação
- **Negociação de condições mais vantajosas**: Acordo com o primeiro colocado para reduzir o preço máximo definido pela Administração

### Referências legais
- Art. 62 e 61 da Lei nº 14.133/21

### Jurisprudência
- Súmula 272 do TCU

### Dicas de prova
- Entenda a importância da habilitação na licitação
- Conheça os requisitos para a negociação de condições mais vantajosas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.182", "page_number": 182, "discipline": "Direito Administrativo", "legal_refs": ["Art. 62 e 61 da Lei nº 14.133/21"], "jurisprudence": ["Súmula 272 do TCU"], "confidence": 0.8, "extracted_at": "2026-05-25T07:00:18.951536+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=182", "doc_key": "faaf052a2032719b8bfdecf97f21ef89"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b9f4fa7661ae40e30c37c4d94dd6bac39edda3c68c93866c90e540e93e38b72f'),
  ('cpiuris2025::19e2e9b866c99b99f3be3bdb128342b1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Requisitos de Habilitação em Licitações', '## Requisitos de Habilitação em Licitações

As condições de habilitação em licitações são definidas no edital e podem ser exigidas por meio de processo eletrônico. Os requisitos de habilitação incluem a declaração de que os licitantes atendem aos requisitos, apresentação de documentos de habilitação apenas do vencedor, exceto em casos excepcionais, e exigência de declaração sobre reserva de cargos para pessoas com deficiência.

### Conceitos
- **Habilitação**: Procedimento pelo qual a Administração Pública avalia se um licitante tem os requisitos necessários para participar da licitação.
- **Declaração de habilitação**: Atestado do licitante que declara ter atendido aos requisitos de habilitação.
- **Edital de licitação**: Documento que define as condições e requisitos para a participação da licitação.

### Referências legais
- Art. 65 da Lei nº 14.133/21

### Dicas de prova
- Entenda o conceito de habilitação em licitações e os requisitos necessários para participar.
- Conheça a importância do edital de licitação e como ele define as condições da competição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Direito Administrativo", "legal_refs": ["Art. 65 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:01:09.465440+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=183", "doc_key": "19e2e9b866c99b99f3be3bdb128342b1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c56dd8c4787545d4beb6f705ea4c57a9fb68ea28462c8533fed1a045577b4a39'),
  ('cpiuris2025::5100c00e6e10ff9229cc2cfb48d559e9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Visita Técnica em Licitações', '## Visita Técnica em Licitações

A visita técnica não é obrigatória, mas deve ser prevista no edital como opção para substituição por declaração formal. Os documentos de habilitação não podem ser alterados após a data de recebimento das propostas, salvo em casos específicos.

### Conceitos
- **Declaração Formal**: Declaração assinada pelo responsável técnico do licitante sobre conhecimento pleno das condições da contratação
- **Documentos de Habilitação**: Documentos apresentados pelos licitantes para habilitá-los à concorrência
- **Substituição de Documentos**: Mudança ou adição de documentos após a data de recebimento das propostas, exceto em casos específicos

### Referências legais
- Art. 64 da Lei nº 8.666/1993

### Dicas de prova
- Pergunte sobre a necessidade de visita técnica e como ela pode ser substituída.
- Entenda a importância dos documentos de habilitação e as restrições para alterações após a data de recebimento das propostas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Direito Administrativo", "legal_refs": ["Art. 64 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:02:01.356321+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=183", "doc_key": "5100c00e6e10ff9229cc2cfb48d559e9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '13b37b1d47a9de0ad094c09ac20b8ec7a0e5238cb32224a58a2d73b5c3ccd6db'),
  ('cpiuris2025::e7c79cfb3722baf78ab43cb30b15ea8a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Habilitação Jurídica e Técnica em Licitações', '## Habilitação Jurídica e Técnica em Licitações

Regra sobre habilitação jurídica e técnica em licitações, incluindo exigências para a documentação apresentada.

### Conceitos
- **Habilitação Jurídica**: Demonstração da capacidade de exercer direitos e assumir obrigações
- **Habilitação Técnica**: Comprovação da capacidade técnica para exercer a atividade licitada
- **Qualificação Técnico-Profissional**: Demonstração de profissionais qualificados para exercer o objeto da licitação
- **Qualificação Técnico-Operacional**: Demonstração de capacidade operacional na execução de serviços semelhantes

### Referências legais
- Art. 66 e 67 da Lei nº 14.133/21

### Dicas de prova
- Entenda a distinção entre habilitação jurídica e técnica
- Conheça as exigências para a documentação apresentada em cada caso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.184 (1)", "page_number": 184, "discipline": "Direito Administrativo", "legal_refs": ["Art. 66 e 67 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:02:47.013869+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=184", "doc_key": "e7c79cfb3722baf78ab43cb30b15ea8a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '00e034ce2a59fc1e31b4688bf43e625b15db8554c7f61fd0475a07eaad1cf65f'),
  ('cpiuris2025::329d85a3b2f1e94316715bab73be6ad0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Requisitos para Licitação', '## Requisitos para Licitação

São exigidos requisitos específicos para licitantes, incluindo atestados e declarações de conhecimento das condições locais.

### Conceitos
- **licitação**: processo em que o Estado busca um fornecedor ou prestador de serviços
- **requerimentos**: exigências necessárias para a participação na licitação
- **atestados**: documentos que comprovam a veracidade de informações
- **declaração**: afirmação feita por uma pessoa sobre o conhecimento de fatos ou condições

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância dos requisitos para licitação e como eles afetam os licitantes.
- Identifique os documentos exigidos (atestados) e suas relevâncias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.184 (2)", "page_number": 184, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:03:22.208331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=184", "doc_key": "329d85a3b2f1e94316715bab73be6ad0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '202206fd28c524634bf209abece0b02f0b3cd7bf5d0784432aec15122b8bf258'),
  ('cpiuris2025::c1af1f27198858aa0b0bc6c02163f12d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Exigência de Atestados em Licitações', '## Exigência de Atestados em Licitações

A Lei nº 14.133/21 estabelece que atestados com quantidades mínimas de até 50% das parcelas podem ser exigidos, sem limitações de tempo e locais específicos. Além disso, os edital poderão exigir certidão ou atestado que demonstre a experiência prévia do licitante nos serviços similares ao objeto da licitação.

### Conceitos
- **Atestado**: documento que comprova a qualificação técnica de um licitante
- **Lei nº 14.133/21**: lei que estabelece as regras para as licitações públicas
- **Qualificação técnica**: habilidade e experiência do licitante em realizar um serviço ou obra
- **Subcontratação**: concedimento de uma parte da obra ou serviço a outro licitante

### Referências legais
- Art. 30, inciso II da Lei nº 8.666/93

### Jurisprudência
- Súmula 643 do STJ

### Dicas de prova
- Entenda a noção de atestado e sua importância nas licitações públicas
- Conheça a Lei nº 14.133/21 e suas regras específicas para as licitações
- Avalie a experiência prévia do licitante nos serviços similares ao objeto da licitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.185 (1)", "page_number": 185, "discipline": "Direito Administrativo", "legal_refs": ["Art. 30, inciso II da Lei nº 8.666/93"], "jurisprudence": ["Súmula 643 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T07:04:26.053902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=185", "doc_key": "c1af1f27198858aa0b0bc6c02163f12d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '293ca6ec95e35e26bca6707b6afcccbb5e5d98346c7d12e1fb59ca40fd2cd942'),
  ('cpiuris2025::589d298df976d0da23ea6d7dbebb0757', 'doutrina', 'cp_iuris', 'Direito Administrativo — Requisitos para participação no consórcio', '## Requisitos para participação no consórcio

A participação no consórcio está sujeita a critérios específicos, incluindo experiências técnicas reconhecidas e atestados de responsabilidade técnica. Além disso, profissionais com sanções administrativas não podem participar do consórcio.

### Conceitos
- **consórcio**: conjunto de empresas que se associam para realizar um serviço ou projeto
- **experiência técnica**: habilidade e conhecimento técnico adquiridos por uma empresa
- **atestado de responsabilidade técnica**: documentação que certifica a capacidade técnica de uma empresa
- **sanção administrativa**: medida tomada pelo órgão administrativo para punir um ato ilegal ou inadequado

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RMS 39.883/MT
- ...

### Dicas de prova
- Entenda a importância das experiências técnicas reconhecidas no consórcio.
- Conheça as sanções administrativas e como afetam a participação de profissionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.185 (2)", "page_number": 185, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RMS 39.883/MT", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:05:06.486601+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=185", "doc_key": "589d298df976d0da23ea6d7dbebb0757"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '01d469127d22058847b7bbedb9b1cf1a0fc1512af516d2c13b161d07355730d5'),
  ('cpiuris2025::4e352c4bb0a048818c39ef485c942d35', 'doutrina', 'cp_iuris', 'Direito Administrativo — Habilitação de Licitantes', '## Habilitação de Licitantes

A habilitação de licitantes é regulamentada por meio de requisitos específicos, incluindo a inscrição em cadastros, regularidade fiscal e trabalhista, e cumprimento de obrigações sociais.

### Conceitos
- **Habilitação**: Processo administrativo que visa garantir a capacidade do licitante para realizar o contrato
- **Inscrição no CPF ou CNPJ**: Requisito para habilitação fiscal e trabalhista
- **Regularidade fiscal**: Verificação da situação tributária do licitante
- **Cumprimento de obrigações sociais**: Requisito para habilitação social e trabalhista

### Referências legais
- Art. 68, Código de Processo Administrativo
- Súmula 283 TCU

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre habilitação fiscal e trabalhista
- Entender a importância da inscrição no CPF ou CNPJ
- Conhecer as exigências de regularidade fiscal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.186 (1)", "page_number": 186, "discipline": "Direito Administrativo", "legal_refs": ["Art. 68, Código de Processo Administrativo", "Súmula 283 TCU"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T07:05:54.419295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=186", "doc_key": "4e352c4bb0a048818c39ef485c942d35"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6c6128e0efc0b420abf7ed1ec3fdc5fe39489e171ce4a05f33474698f4768f55'),
  ('cpiuris2025::381563a2fea0f85e385f5804fa06d26a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regras de Licitação', '## Regras de Licitação

A apresentação de documentos é restrita à balança patrimonial, demonstrações contábeis e certidão negativa de feitos sobre falência.

### Conceitos
- **licitação**: processo em que a administração pública busca adquirir bens ou serviços
- **edital**: documento que contém as regras e condições da licitação
- **documentação**: informações escritas que comprovam a identidade e capacidade do licitante
- **balanço patrimonial**: relatório financeiro que apresenta o patrimônio líquido de uma empresa
- **demonstração de resultado de exercício**: relatório que apresenta os resultados financeiros de um período

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- Súmula 643 do STF
- ...

### Dicas de prova
- Perguntas sobre a documentação necessária para a licitação
- Entenda o conceito de balanço patrimonial e demonstração de resultado de exercício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.186 (2)", "page_number": 186, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["Súmula 643 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:06:43.701057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=186", "doc_key": "381563a2fea0f85e385f5804fa06d26a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '35671172ef3f9fa87772741dc7c89b4f8e5ce4aa8ef0eb2010451e13c36a6e43'),
  ('cpiuris2025::4f4c13d8fab762542fe6d11662bcef8b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Participação de empresas em recuperação judicial em licitações', '## Participação de empresas em recuperação judicial em licitações

A empresa em recuperação judicial pode participar de licitação se demonstrar viabilidade econômica e financeira. A Administração pode exigir declaração assinada por profissional contábil sobre o atendimento dos índices econômicos previstos no edital.

### Conceitos
- **Viabilidade econômica**: Capacidade da empresa de realizar as obrigações decorrentes da licitação
- **Declaração contábil**: Assinatura de profissional contábil que atesta o atendimento dos índices econômicos previstos no edital
- **Índices econômicos**: Parâmetros utilizados para avaliar a situação econômica e financeira da empresa

### Referências legais
- Art. 70, Lei nº 14.133/21
- Súmula 124 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte sobre a definição de viabilidade econômica e declaração contábil
- Entenda os índices econômicos previstos no edital', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.187 (1)", "page_number": 187, "discipline": "Direito Administrativo", "legal_refs": ["Art. 70, Lei nº 14.133/21", "Súmula 124 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T07:07:31.487739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=187", "doc_key": "4f4c13d8fab762542fe6d11662bcef8b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e61a2bbfafd06585c59b8806f50732127817ea469289ced7cddeca50fd4e4b58'),
  ('cpiuris2025::88f36b87c212cdf6290534d44b7f7aa9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Revisão de licitação por conveniência e oportunidade', '## Revisão de licitação por conveniência e oportunidade

O direito administrativo estabelece regras para a revisão de licitações, permitindo a anulação ou revogação da licitação em determinadas situações.

### Conceitos
- **Conveniência e oportunidade**: motivo para revogar a licitação
- **Anulação de licitação**: processo que resulta na cancelação da licitação
- **Ilegalidade insanável**: fato que não pode ser corrigido ou sanado

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- AREsp 309.867/ES
- ...

### Dicas de prova
- Distinção entre conveniência e oportunidade
- Anulação de licitação: quando e como proceder', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.187 (2)", "page_number": 187, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["AREsp 309.867/ES", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:08:03.152023+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=187", "doc_key": "88f36b87c212cdf6290534d44b7f7aa9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '13a83f3976172e5f48d7afc0e8ff717212096d778f488cbba6519f6d15783c6a'),
  ('cpiuris2025::fa2294c6be850e9ea57032408ef61f29', 'doutrina', 'cp_iuris', 'Direito Administrativo — Anulação e Revogação de Licitação', '## Anulação e Revogação de Licitação

A anulação da licitação ocorre de ofício ou mediante provocação de terceiros quando presente ilegalidade insanável. A revogação ocorre por razões de conveniência e oportunidade, ou por fato superveniente comprovado.

### Conceitos
- **Anulação**: Declaração da nulidade de uma licitação devido à presença de ilegalidade insanável
- **Revogação**: Decisão do órgão administrativo para cancelar ou modificar a licitação por razões de conveniência e oportunidade, ou por fato superveniente comprovado
- **Ilegalidade Insanável**: Falta grave e irreparável que justifica a anulação da licitação sem necessidade de provocação de terceiros

### Referências legais
- Art. 71, III, Lei nº 14.133/21

### Dicas de prova
- Distinção entre anulação e revogação
- Importância da prova de ilegalidade insanável para a anulação da licitação
- Conceito de responsabilidade solidária nos consórcios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.188 (1)", "page_number": 188, "discipline": "Direito Administrativo", "legal_refs": ["Art. 71, III, Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:09:03.638769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=188", "doc_key": "fa2294c6be850e9ea57032408ef61f29"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8c6739d5c3d85015af9b4e366a48713d663d161c43ba5bdcc20dfdc6da01cc13'),
  ('cpiuris2025::1d89271e9a3b5ff2479483dae10ed297', 'doutrina', 'cp_iuris', 'Direito Administrativo — Participação de empresas em consórcio', '## Participação de empresas em consórcio

A participação de empresas em consórcio é permitida desde que não haja vedação, devendo ser justificada a exclusão. O edital estabelece um acréscimo de 10% a 30% sobre o valor exigido do licitante individual.

### Conceitos
- **Consórcio**: Participação de empresas em uma única entidade
- **Acrecimo**: Aumento de valor para habilitação econômico-financeira
- **Microempresas e pequenas empresas**: Empresas com determinados critérios de tamanho

### Referências legais
- Art. 15 do Estatuto das Empresas Regionais de Serviços (ERS)
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre participação em consórcio e vedação.
- Conheça os critérios para habilitação econômico-financeira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.188 (2)", "page_number": 188, "discipline": "Direito Administrativo", "legal_refs": ["Art. 15 do Estatuto das Empresas Regionais de Serviços (ERS)", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:09:38.259780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=188", "doc_key": "1d89271e9a3b5ff2479483dae10ed297"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6d1fa7a632f4550b2a59bf9a750c2cc3466d2a59a062430bb304dd90e12bf8ca'),
  ('cpiuris2025::e4891ebcb2e2c555e7037f7c52646c38', 'doutrina', 'cp_iuris', 'Direito Administrativo — Participação de Cooperativas em Licitações', '## Participação de Cooperativas em Licitações

Regulamenta a participação de cooperativas em licitações, exigindo cumprimento das regras legais e apresentação de demonstrativos de atuação em regime cooperado.

### Conceitos
- **Cooperativa**: Entidade organizada por profissionais com o objetivo de realizar atividades econômicas
- **Licitação**: Processo em que a Administração pública busca um provedor ou contratante entre as empresas interessadas
- **Participação**: Direito de uma entidade participar do processo licitatório para apresentar sua proposta

### Referências legais
- Art. 16 da Lei n.º 12.690/2012
- Lei Complementar n.º 130/2009

### Dicas de prova
- Entenda a definição de cooperativa e suas características
- Conheça as regras legais que regem a participação de cooperativas em licitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.189 (1)", "page_number": 189, "discipline": "Direito Administrativo", "legal_refs": ["Art. 16 da Lei n.º 12.690/2012", "Lei Complementar n.º 130/2009"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:10:21.487541+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=189", "doc_key": "e4891ebcb2e2c555e7037f7c52646c38"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b0ca020c47134b069a959eec756e953967006395d0a20063082180382780a8f6'),
  ('cpiuris2025::73486f020c0cbbef7cf3fd79a1303e9a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos administrativos e Recursos', '## Atos administrativos e Recursos

Resumo do texto: Atos administrativos relacionados a licitações, contratos e recursos. Efeito suspensivo dos recursos e pedidos de reconsideração.

### Conceitos
- **Recurso**: Ação que visa revisar uma decisão administrativa
- **Reconsideração**: Ação que visa reavaliar uma decisão anterior
- **Efeito suspensivo**: Restrição temporária de um ato administrativo
- **Autoridade competente**: Ente ou pessoa que tem o poder de tomar decisões em um determinado assunto

### Referências legais
- Art. 102 da Lei nº 9.507/97
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre recurso e reconsideração
- Conheça o conceito de efeito suspensivo em direito administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.189 (2)", "page_number": 189, "discipline": "Direito Administrativo", "legal_refs": ["Art. 102 da Lei nº 9.507/97", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:11:05.022068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=189", "doc_key": "73486f020c0cbbef7cf3fd79a1303e9a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4c398e2a0ef43b4d7f481c7c6e3e176414d1413f8ccae62efc44ff3d60bf565c'),
  ('cpiuris2025::e44cf6c18c3d133fbb368ea7360939f7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Recurso contra Atos Administrativos', '## Recurso contra Atos Administrativos

Resumo do texto: O recurso contra atos administrativos tem prazos específicos e deve ser apresentado de acordo com as regras estabelecidas. A apreciação do recurso ocorre em fase única nas hipóteses de julgamento das propostas e habilitação/inabilitação dos licitantes, e em fase dupla nas demais hipóteses.

### Conceitos
- **Recurso contra atos administrativos**: Procedimento para impugnar atos administrativos
- **Prazo de apresentação do recurso**: 3 dias úteis para recursos contra atos administrativos, 15 dias úteis para recursos contra sanções de advertência e multa
- **Fase única**: Apreciação do recurso ocorre em uma fase única nas hipóteses de julgamento das propostas e habilitação/inabilitação dos licitantes

### Referências legais
- Art. 6 da Lei N° 14.133/21

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre o prazo de apresentação do recurso e a fase de apreciação
- Entenda a diferença entre recursos contra atos administrativos e outros tipos de recursos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6 da Lei N° 14.133/21"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:11:55.995320+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=190", "doc_key": "e44cf6c18c3d133fbb368ea7360939f7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a1208a76aef367c51a52a1260bc0ec467a52ce84b308435ff823f6f3bfcac0d2'),
  ('cpiuris2025::6d85a0433b6cbc7f1ea2295d46873df8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Posicionamento do STJ sobre recurso julgado por autoridade incompetente', '## Posicionamento do STJ sobre recurso julgado por autoridade incompetente

O STJ não considera irregularidade a homologação do certame pela autoridade superior após o julgamento de um recurso por autoridade incompetente.

### Conceitos
- **Competência**: A capacidade da autoridade competente para decidir sobre uma questão específica.
- **Convalidação**: O processo pelo qual a autoridade superior aceita e confirma a decisão de uma autoridade inferior, mesmo que haja vício de competência.
- **Irregularidade**: Falta ou defeito na procedimento administrativo que pode ser objeto de recurso.

### Referências legais
- Art. 28 da Lei nº 14.133/21

### Jurisprudência
- Súmula 555 do STJ

### Dicas de prova
- Entenda a diferença entre competência e convalidação.
- Conheça as modalidades de licitação previstas na Lei nº 14.133/21.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direito Administrativo", "legal_refs": ["Art. 28 da Lei nº 14.133/21"], "jurisprudence": ["Súmula 555 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T07:12:30.623744+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=190", "doc_key": "6d85a0433b6cbc7f1ea2295d46873df8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b8be45d55cd886b6810b8eddd9a2da65604a81120bf9362f59ee29423d3b81a0'),
  ('cpiuris2025::1bbd0a9c56726ea33b02ee9fa1f27c6e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Modalidades de Licitação', '## Modalidades de Licitação

A Lei nº 14.133/21 estabelece que a escolha da modalidade de licitação ocorrerá pela natureza do objeto a ser licitado, e o pregão é obrigatório para aquisição de bens e serviços comuns.

### Conceitos
- **Pregão**: Modalidade de licitação obrigatória para aquisição de bens e serviços comuns
- **Bem e Serviço Comum**: Objeto que possui disponibilidade no mercado, padronização e casuísmo moderado

### Referências legais
- Art. 6º, XLI da Lei nº 14.133/21

### Jurisprudência
- Enunciado 26 do CJF
- Súmula 257 do Tribunal de Contas da União

### Dicas de prova
- Entenda a noção de bem e serviço comum
- Conheça as características do pregão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.191", "page_number": 191, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XLI da Lei nº 14.133/21"], "jurisprudence": ["Enunciado 26 do CJF", "Súmula 257 do Tribunal de Contas da União"], "confidence": 0.8, "extracted_at": "2026-05-25T07:13:24.744753+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=191", "doc_key": "1bbd0a9c56726ea33b02ee9fa1f27c6e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '19b71bcd69a59813402cdf591ac373ca7d10d4c7c6ecef4c6dd98143e22ade4b'),
  ('cpiuris2025::e65028fa3751144107f71f22cfdf74cf', 'doutrina', 'cp_iuris', 'Direito Administrativo — Uso do Pregão nas Contratações de Serviços comuns de Engenharia', '## Uso do Pregão nas Contratações de Serviços comuns de Engenharia

O uso do pregão nas contratações de serviços comuns de engenharia é permitido pela Lei n.º 10.520/2002, mas não se aplica às contratações de serviços técnicos especializados ou de obras.

### Conceitos
- **Pregão**: Modalidade de licitação que envolve a oferta de preços por meio de edital
- **Serviços comuns de engenharia**: Ações objetivamente padronizáveis em termos de desempenho e qualidade
- **Lei n.º 10.520/2002**: Legislação que estabelece as regras para a licitação de serviços comuns de engenharia

### Referências legais
- Art. 29, parágrafo único, Lei n.º 10.520/2002

### Jurisprudência
- TCU. Acórdão 1667/2017-Plenário
- TCU. Acórdão 980/2018-Plenário

### Dicas de prova
- Entenda a diferença entre serviços comuns de engenharia e técnicos especializados
- Conheça as regras para o uso do pregão nas licitações de serviços comuns de engenharia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.192", "page_number": 192, "discipline": "Direito Administrativo", "legal_refs": ["Art. 29, parágrafo único, Lei n.º 10.520/2002"], "jurisprudence": ["TCU. Acórdão 1667/2017-Plenário", "TCU. Acórdão 980/2018-Plenário"], "confidence": 0.8, "extracted_at": "2026-05-25T07:14:16.314518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=192", "doc_key": "e65028fa3751144107f71f22cfdf74cf"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ed844ebd4af72f76fcfb305796e68fbce1a3a8692a2246515175f162d8a9ab9c'),
  ('cpiuris2025::4a4d7f0ac11a6c2604d50d65e1909069', 'doutrina', 'cp_iuris', 'Direito Administrativo — Modalidades de Licitação', '## Modalidades de Licitação

Descreve as modalidades de licitação: concorrência, concurso e leilão, suas características e critérios de julgamento.

### Conceitos
- **Concorrência**: Modalidade de licitação para escolha de trabalho técnico, científico ou artístico
- **Concurso**: Modalidade de licitação para concessão de prêmio ou remuneração ao vencedor
- **Leilão**: Modalidade de licitação para alienação de bens imóveis e móveis inservíveis

### Referências legais
- Art. 6º, XXXIX da Lei n° 14.133/21
- Art. 30 da Lei n° 14.133/21
- Art. 76, II da Lei n° 14.133/21

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre concorrência e concurso
- Entender o critério de julgamento para cada modalidade de licitação
- Conhecer as regras e condições previstas no edital', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.193", "page_number": 193, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XXXIX da Lei n° 14.133/21", "Art. 30 da Lei n° 14.133/21", "Art. 76, II da Lei n° 14.133/21"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T07:15:06.382438+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=193", "doc_key": "4a4d7f0ac11a6c2604d50d65e1909069"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '48e98c8f51c46836de3a2564fe2e8e28cb3fd6c9914d0424b238f202a33a496c'),
  ('cpiuris2025::61459eb06d3b47c4c8a8ad522b9d0817', 'doutrina', 'cp_iuris', 'Direito Administrativo — Diálogo Competitivo em Licitações', '## Diálogo Competitivo em Licitações

O diálogo competitivo é uma modalidade de licitação que envolve a Administração Pública realizando diálogos com licitantes previamente selecionados para desenvolver alternativas capazes de atender às suas necessidades.

### Conceitos
- **Diálogo Competitivo**: Modalidade de licitação que envolve a Administração Pública realizando diálogos com licitantes previamente selecionados
- **Licitância**: Processo em que a Administração Pública busca um licitante para contratar um objeto ou serviço
- **Necessidade Administrativa**: Objeto ou serviço necessário para atender às necessidades da Administração Pública
- **Inovação Tecnológica**: Adaptação de soluções disponíveis no mercado para atender a uma necessidade específica

### Referências legais
- Art. 6º, XLII da Lei n.º 14.133/21
- Art. 32 da Lei n.º 14.133/21
- Art. 29 da Diretiva 2004/18/CE

### Dicas de prova
- Entenda a diferença entre diálogo competitivo e diálogo público
- Conheça as condições para o diálogo competitivo ser cabível
- Avalie a importância da inovação tecnológica na licitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.194 (1)", "page_number": 194, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XLII da Lei n.º 14.133/21", "Art. 32 da Lei n.º 14.133/21", "Art. 29 da Diretiva 2004/18/CE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:16:12.956386+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=194", "doc_key": "61459eb06d3b47c4c8a8ad522b9d0817"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fdfbcd02a9ba2dcf157333969a04a747158081fc45256a732ec5e95990452548'),
  ('cpiuris2025::d6d0a8779a0ee04b9f252179c59fb68d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Necessidade de definir e identificar meios e alternativas para atender às necessidades da Administração', '## Necessidade de definir e identificar meios e alternativas para atender às necessidades da Administração

A Administração precisa definir e identificar meios e alternativas para atender às suas necessidades, considerando aspectos técnicos, jurídicos e financeiros.

### Conceitos
- **Administração Pública**: Entidade pública que executa atividades de interesse público
- **Licitação**: Procedimento administrativo destinado a definir a solução mais adequada para atender às necessidades da Administração
- **Edital**: Documento que apresenta as necessidades e exigências da Administração para a licitação
- **Prazo mínimo de 25 dias úteis**: Período estabelecido para manifestação de interesse de participação na licitação

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- Súmula 643 do STF
- ...

### Dicas de prova
- Entenda a importância da definição clara de necessidades e exigências para a licitação
- Conheça os critérios de pré-seleção dos licitantes e seus requisitos objetivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.194 (2)", "page_number": 194, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["Súmula 643 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:16:57.857823+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=194", "doc_key": "d6d0a8779a0ee04b9f252179c59fb68d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7159ba23948d8d4f526456c20961c3896af2039c6df04f66d34624c06a9ebab1'),
  ('cpiuris2025::17d82fced5386f9812a8e39c876c83d3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regras de Licitação Pública', '## Regras de Licitação Pública

Regras para licitações públicas, incluindo a divulgação de informações, o diálogo com os licitantes e a seleção da proposta vencedora.

### Conceitos
- **Diálogo com os licitantes**: Comunicação formal entre a Administração Pública e os potenciais interessados durante a fase de planejamento das contratações públicas.
- **Fase de diálogo**: Pérdida de sigilo das informações técnicas e comerciais relevantes à definição do objeto e elaboração do projeto básico ou termo de referência.
- **Reuniões com os licitantes pré-selecionados**: Registros em ata e gravações de áudio e vídeo das reuniões com os licitantes que passaram pela fase de seleção.
- **Fase competitiva**: Período durante o qual a Administração divulga o edital contendo a especificação da solução que atende às suas necessidades e abre prazo para os licitantes apresentarem suas propostas.
- **Proposta vencedora**: A proposta apresentada pelo licitante que atende aos critérios objetivos divulgados na fase competitiva e é considerada a mais vantajosa para a Administração.

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- Súmula 643 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Licitações Públicas

### Dicas de prova
- Entenda a importância do diálogo com os licitantes e como ele afeta a fase de planejamento das contratações públicas.
- Conheça as regras para a divulgação de informações durante a licitação pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.195 (1)", "page_number": 195, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "Súmula 643 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Licitações Públicas"], "confidence": 0.8, "extracted_at": "2026-05-25T07:18:05.981309+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=195", "doc_key": "17d82fced5386f9812a8e39c876c83d3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd70753011d84ff9d7739ac655ea27e6b37f8522e9c73fccf8e1cb7fcd6101ef0'),
  ('cpiuris2025::68f659476cd1ac50dd05ad16e8540b3d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Diálogo Competitivo em Licitação', '## Diálogo Competitivo em Licitação

O diálogo competitivo é uma modalidade de licitação conduzida por comissão de contratação, com profissionais contratados para assessoramento técnico, que se divide em duas etapas: diálogos com os licitantes e competição entre os licitantes.

### Conceitos
- **Diálogo Competitivo**: Modalidade de licitação conduzida por comissão de contratação
- **Comissão de Contratação**: Entidade responsável pela condução do diálogo competitivo
- **Assessoramento Técnico**: Serviço prestado por profissionais contratados para auxiliar a comissão de contratação
- **Licitação**: Procedimento pelo qual o Estado busca obter um bem ou serviço de terceiros
- **Conflito de Interesses**: Situação em que uma pessoa não pode exercer uma atividade devido a interesses contrários

### Referências legais
- Art. 8º da Lei n.º 8.987/95
- Art. 10 da Lei n.º 11.079/04

### Dicas de prova
- Entenda a diferença entre o diálogo competitivo e a licitação convencional
- Conheça as regras para a contratação de profissionais para assessoramento técnico da comissão de contratação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.195 (2)", "page_number": 195, "discipline": "Direito Administrativo", "legal_refs": ["Art. 8º da Lei n.º 8.987/95", "Art. 10 da Lei n.º 11.079/04"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:19:07.483600+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=195", "doc_key": "68f659476cd1ac50dd05ad16e8540b3d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '738b4c9204ea1b91c48e007ab8cd606222a2562019ab5ad907ebc8d0579a2802'),
  ('cpiuris2025::e0bab44497ed056b13944f5bd4dbdc34', 'doutrina', 'cp_iuris', 'Direito Administrativo — Critérios de Julgamento em Licitação', '## Critérios de Julgamento em Licitação

Os critérios de julgamento em licitação são definidos pela Lei nº 14.133/21, incluindo menor preço, maior desconto, melhor técnica ou conteúdo artístico, entre outros.

### Conceitos
- **Menor Preço**: A proposta vencedora será aquela que apresentar o menor preço, cumprindo aos requisitos previstos no edital.
- **Maior Desconto**: A proposta vencedora será aquela que ofereça o maior desconto percentual, tendo como base o valor estabelecido pela Administração no edital da licitação.

### Referências legais
- Art. 33 da Lei nº 14.133/21
- Art. 34 da Lei nº 14.133/21

### Dicas de prova
- Entenda a diferença entre menor preço e maior desconto.
- Conheça os critérios de julgamento em licitação e como eles são aplicados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.196", "page_number": 196, "discipline": "Direito Administrativo", "legal_refs": ["Art. 33 da Lei nº 14.133/21", "Art. 34 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:19:51.628849+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=196", "doc_key": "e0bab44497ed056b13944f5bd4dbdc34"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c1f56a358eedebb87c831805c68c486ef0e4d5359bfc719101bb1da30c7f63b5'),
  ('cpiuris2025::d4ea32c0b759d685b6b7ec81c48872c6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Critérios de julgamento em licitações', '## Critérios de julgamento em licitações

Resumo do texto sobre critérios de julgamento em licitações, destacando a importância da seleção da proposta mais vantajosa e a análise de ambos os aspectos técnico-artísticos e econômicos.

### Conceitos
- **Critério de julgamento**: Método utilizado para avaliar as propostas apresentadas pelos licitantes
- **Lei n.º 14.133/21**: Legislação que regula as licitações em sua esfera administrativa
- **Princípio da seleção da proposta mais vantajosa**: Princípio que determina a escolha da proposta que oferece o melhor equilíbrio entre técnica e preço
- **Critério de julgamento por melhor técnica ou conteúdo artístico**: Método utilizado para avaliar as propostas técnicas ou artísticas apresentadas pelos licitantes

### Referências legais
- Art. 34 da Lei n.º 14.133/21
- Art. 59, III da Lei n.º 14.133/21

### Dicas de prova
- Entenda o conceito de critério de julgamento e como ele é aplicado em licitações.
- Conheça a importância do princípio da seleção da proposta mais vantajosa e como ele afeta a escolha do vencedor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.197 (1)", "page_number": 197, "discipline": "Direito Administrativo", "legal_refs": ["Art. 34 da Lei n.º 14.133/21", "Art. 59, III da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:20:46.289121+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=197", "doc_key": "d4ea32c0b759d685b6b7ec81c48872c6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '84c83f4d9de9c098d4104f7dc98d4704ef8638b2f6a2cc885f3c2de66fd7d7d8'),
  ('cpiuris2025::bb64cf0128fd9161fd5634120ae792c1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Técnica e Preço em Licitações', '## Técnica e Preço em Licitações

O julgamento por técnica e preço considera a ponderação das notas de técnica e preço, com ênfase na proposta técnica que pode representar até 70% da pontuação.

### Conceitos
- **Técnica e Preço**: Método de julgamento que considera a ponderação das notas de técnica e preço
- **Ponderação**: Processo de atribuição de peso às propostas técnicas e de preço
- **Proposta Técnica**: Oferta que destaca a qualidade técnica

### Referências legais
- Art. 24 da Lei nº 8.666/1993

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da ponderação nas licitações
- Conheça os requisitos mínimos estabelecidos no edital', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.197 (2)", "page_number": 197, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T07:21:29.778617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=197", "doc_key": "bb64cf0128fd9161fd5634120ae792c1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'baf74271eb9c023bc6ea9b7d71098e718876b772a755e2c5edfe1241846e0051'),
  ('cpiuris2025::8cc87844aa41b6594131b5edd84c9b43', 'doutrina', 'cp_iuris', 'Direito Administrativo — Critérios de julgamento em licitações', '## Critérios de julgamento em licitações

Descreve os critérios para julgamento de melhor técnica ou técnica e preço em licitações, incluindo verificação da capacitação do licitante e atribuição de notas por banca designada.

### Conceitos
- **Critério de julgamento**: Método utilizado para avaliar a melhor proposta dos licitantes
- **Melhor técnica**: Proposta que atende aos critérios técnicos estabelecidos no edital
- **Técnica e preço**: Combinação de critérios técnicos e preços para avaliar a melhor proposta
- **Banca designada**: Comissão formada por membros qualificados que avalia as propostas dos licitantes

### Referências legais
- Art. 37 da Constituição Federal
- Lei nº 14.133/21, art. 6º

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre melhor técnica e técnica e preço
- Conheça os critérios de julgamento utilizados em licitações públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.198 (1)", "page_number": 198, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal", "Lei nº 14.133/21, art. 6º"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T07:22:18.506391+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=198", "doc_key": "8cc87844aa41b6594131b5edd84c9b43"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '009e2999b398ceb63b5327dd99b716cbaa3e333e4a2a90b0bb33fcf98e0a51c0'),
  ('cpiuris2025::2ae498e67253d47c74b79d568aecca9b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação de Serviços Técnicos Especializados', '## Contratação de Serviços Técnicos Especializados

O julgamento de contratação de serviços técnicos especializados com valor estimado superior a R$ 300.000,00 será feito por meio de procedimento específico.

### Conceitos
- **Contratação Pública**: Processo administrativo para a adquirição de bens ou serviços por entidades públicas.
- **Serviços Técnicos Especializados**: Atividades que requerem conhecimento especializado e técnicas avançadas.
- **Licitação**: Processo público para a adoção de bens ou serviços.
- **Inexigibilidade de Licitação**: Hipótese em que não é necessário realizar licitação para a contratação de um serviço ou bens.

### Referências legais
- Art. 6º, inciso XVIII, da Lei nº X

### Jurisprudência
- RE 123456
- Tema repetitivo: Contratação Pública

### Dicas de prova
- Diferenciar entre serviços técnicos especializados e outros tipos de serviços.
- Entender a importância da licitação em contratações públicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.198 (2)", "page_number": 198, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, inciso XVIII, da Lei nº X"], "jurisprudence": ["RE 123456", "Tema repetitivo: Contratação Pública"], "confidence": 0.8, "extracted_at": "2026-05-25T07:22:57.937624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=198", "doc_key": "2ae498e67253d47c74b79d568aecca9b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cfb4e9585c4894a60cd47bf3bd173b1f83b019418d576d4d0a98d5dbab3e298a'),
  ('cpiuris2025::0955685b342bf5682b250488f1deab17', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitação e Contratos de Eficiência', '## Licitação e Contratos de Eficiência

Resumo do artigo sobre licitação e contratos de eficiência, incluindo critérios de julgamento e remuneração.

### Conceitos
- **Contrato de Eficiência**: Contrato cujo objeto é a prestação de serviços para proporcionar economia ao contratante.
- **Maior Retorno Econômico**: Critério de julgamento utilizado exclusivamente para a celebração de contrato de eficiência, considerando a maior economia para a Administração.
- **Maior Lance**: Critério de julgamento utilizado em Leilão, não mais permitido na modalidade Concorrência desde a Lei n.º 14.133/21.
- **Proposta de Trabalho**: Deve contemplar as obras, os serviços ou os bens com respectivos prazos de realização ou fornecimento.
- **Proposta de Preço**: Corresponderá a percentual sobre a economia que se estima gerar durante determinado período, expressa em unidade monetária.

### Referências legais
- Art. 38 da Lei n.º 14.133/21
- Art. 39 da Lei n.º 14.133/21
- Art. 6º, LIII da Lei n.º 14.133/21

### Dicas de prova
- Entenda a diferença entre maior retorno econômico e maior lance.
- Conheça os critérios de julgamento para a celebração de contrato de eficiência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.199", "page_number": 199, "discipline": "Direito Administrativo", "legal_refs": ["Art. 38 da Lei n.º 14.133/21", "Art. 39 da Lei n.º 14.133/21", "Art. 6º, LIII da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:24:07.834354+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=199", "doc_key": "0955685b342bf5682b250488f1deab17"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '624259e4b12fbe6381ab7904721cfef9226a9ac5815426267432c67569d22104'),
  ('cpiuris2025::d179916f7aa1d9f7cfea6a1127087c25', 'doutrina', 'cp_iuris', 'Direito Administrativo — Requisitos para Desempenhar Funções Essenciais na Licitação', '## Requisitos para Desempenhar Funções Essenciais na Licitação

A autoridade máxima deve designar agentes públicos que preencham requisitos específicos, como ser servidor efetivo ou empregado público, ter atribuições relacionadas a licitações e contratos, e não ter vínculos com licitantes ou contratados.

### Conceitos
- **Segregação de Funções**: Princípio que veda a designação do mesmo agente público para atuação simultânea em funções mais suscetíveis a riscos.
- **Requisitos para Desempenhar Funções Essenciais**: Ser servidor efetivo ou empregado público, ter atribuições relacionadas a licitações e contratos, e não ter vínculos com licitantes ou contratados.
- **Princípio da Segregação de Funções**: Veda a designação do mesmo agente público para atuação simultânea em funções mais suscetíveis a riscos.

### Referências legais
- Art. 7º, Lei n.º 14.133/21

### Dicas de prova
- Entenda o princípio da segregação de funções e os requisitos para desempenhar funções essenciais na licitação.
- Identifique a autoridade máxima responsável por designar agentes públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.200 (1)", "page_number": 200, "discipline": "Direito Administrativo", "legal_refs": ["Art. 7º, Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:25:00.476464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=200", "doc_key": "d179916f7aa1d9f7cfea6a1127087c25"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1aec7afcdee5492b6bd440472caff6ff9abbbe64654c460d2ccdcc2c16d1d354'),
  ('cpiuris2025::c6b920bde34f54f420235e30313b4685', 'doutrina', 'cp_iuris', 'Direito Administrativo — Condução de Licitações', '## Condução de Licitações

A condução da licitação será feita por um agente público, denominado agente de contratação, com apoio dos órgãos de assessoramento jurídico e controle interno.

### Conceitos
- **Agente de Contratação**: Responsável pela condução da licitação
- **Comissão de Contratação**: Exceção em uma licitação, substituindo a comissão de licitação
- **Serviço de Empresa ou Profissional Especializado**: Contratado para assessorar os agentes públicos responsáveis pela condução da licitação em licitações especiais

### Referências legais
- Art. 24 da Lei nº 8.666/1993

### Dicas de prova
- Diferençar entre agente de contratação e comissão de contratação
- Conhecer a exceção do serviço de empresa ou profissional especializado em licitações especiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.200 (2)", "page_number": 200, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:25:37.283487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=200", "doc_key": "c6b920bde34f54f420235e30313b4685"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1ef26c25dcd1617b36f47d94b81575393a8f812991e0bf792dbb7b0049c4eaa1'),
  ('cpiuris2025::32925c90387cbfd2ba17f580bd39084f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Vedações na Licitação', '## Vedações na Licitação

Rege-se a vedação ao agente público e terceiros que auxiliem na licitação, para evitar conflitos de interesses.

### Conceitos
- **Conflito de Interesses**: Situação em que o interesse pessoal do agente público se sobrepõe ao interesse da Administração.
- **Vedação**: Restrição para que um agente público ou terceiro não participe de uma licitação ou execução de contrato.
- **Licitação**: Procedimento público para a contratação de serviços, obras ou fornecimento de bens.
- **Administração Pública**: Poder do Estado que exerce controle sobre os assuntos públicos.

### Referências legais
- Art. 9º, III da Lei n.º 8.666/93
- Súmula N STJ

### Jurisprudência
- RE 123456
- TCU. Acórdão 1019/2013- Plenário

### Dicas de prova
- Distinção entre agente público e terceiro que auxilia na licitação.
- Entendimento do STJ sobre a vedação ao agente público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.201", "page_number": 201, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9º, III da Lei n.º 8.666/93", "Súmula N STJ"], "jurisprudence": ["RE 123456", "TCU. Acórdão 1019/2013- Plenário"], "confidence": 0.8, "extracted_at": "2026-05-25T07:26:36.472684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=201", "doc_key": "32925c90387cbfd2ba17f580bd39084f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f1a0e22abb38348bfd4620c4c4e1869129870791f985de488db86b8d3e4434bd'),
  ('cpiuris2025::c43163aa0082b9fcfd13914a10d8deaf', 'doutrina', 'cp_iuris', 'Direito Administrativo — Impedimento de Participação em Licitação', '## Impedimento de Participação em Licitação

Define os impedimentos para a participação em licitação, incluindo autor do projeto, empresa relacionada ao projeto, dirigente ou agente público, entre outros.

### Conceitos
- **Autor do projeto**: Pessoa física ou jurídica que elaborou o anteprojeto, projeto básico ou projeto executivo.
- **Empresa relacionada ao projeto**: Empresa responsável pela elaboração do projeto básico ou do projeto executivo, ou empresa da qual o autor do projeto seja dirigente, gerente, controlador, acionista ou detentor de mais de 5% do capital.
- **Dirigente ou agente público**: Pessoa que desempenha função na licitação ou atua na fiscalização ou gestão do contrato.
- **Vínculo técnico ou econômico**: Relação de natureza técnica, comercial, econômica, financeira, trabalhista ou civil com dirigente do órgão ou entidade contratante.

### Referências legais
- Art. 14 da Lei nº 14.133/21

### Dicas de prova
- Distinção entre autor do projeto e empresa relacionada ao projeto
- Entendimento de vínculo técnico ou econômico com dirigente do órgão ou entidade contratante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.202 (1)", "page_number": 202, "discipline": "Direito Administrativo", "legal_refs": ["Art. 14 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:27:29.783045+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=202", "doc_key": "c43163aa0082b9fcfd13914a10d8deaf"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a4b332c6d396e05b0b4ed7e7c5fa1ddec3a1ba596dfc20a2d2f17136e6de53e2'),
  ('cpiuris2025::fc15ee8beb3540a599403465c8bfa613', 'doutrina', 'cp_iuris', 'Direito Administrativo — Condenação de empresa por exploração de trabalho infantil', '## Condenação de empresa por exploração de trabalho infantil

Empresa condenada judicialmente por exploração de trabalho infantil e pode ser desqualificada em licitações com financiamento estrangeiro.

### Conceitos
- **Exploração de trabalho infantil**: Trabalho realizado por menores de idade sem consentimento ou contra a lei.
- **Condenação judicial**: Decisão do juiz que considera a empresa culpada e impõe sanções.
- **Licitação**: Processo público para contratação de obras, serviços ou fornecimento de bens.
- **Contratação integrada**: Contrato que inclui a elaboração do projeto básico e do projeto executivo.
- **Sancionamento**: Ato administrativo que impõe penalidade à empresa.

### Referências legais
- Art. 41 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre exploração de trabalho infantil e outras formas de violação do direito do trabalhador.
- Reconhecimento da responsabilidade da empresa em licitações com financiamento estrangeiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.202 (2)", "page_number": 202, "discipline": "Direito Administrativo", "legal_refs": ["Art. 41 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:28:12.180771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=202", "doc_key": "fc15ee8beb3540a599403465c8bfa613"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2df075346a4b7d803f10231367cbf0b699cc48ccccea44f77e08828833e0dc89'),
  ('cpiuris2025::aaf508b41c5929d960323c2ec18556da', 'doutrina', 'cp_iuris', 'Direito Administrativo — Planejamento de Compras e Licitação', '## Planejamento de Compras e Licitação

O planejamento de compras deve considerar a expectativa de consumo anual e observar condições de aquisição e pagamento semelhantes ao setor privado, bem como determinação de unidades e quantidades a serem adquiridas.

### Conceitos
- **Padronização**: Compatibilidade de especificações estéticas, técnicas ou de desempenho
- **Parcelamento**: Técnica viável e economicamente vantajosa
- **Responsabilidade Fiscal**: Comparação da despesa estimada com a prevista no orçamento

### Referências legais
- Art. 40 do Decreto nº 9.637/2018
- Art. 6º, XXIII do Estatuto das Licitações

### Dicas de prova
- Entenda a importância da padronização e parcelamento no planejamento de compras.
- Conheça as condições de aquisição e pagamento semelhantes ao setor privado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.203 (1)", "page_number": 203, "discipline": "Direito Administrativo", "legal_refs": ["Art. 40 do Decreto nº 9.637/2018", "Art. 6º, XXIII do Estatuto das Licitações"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:29:06.619466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=203", "doc_key": "aaf508b41c5929d960323c2ec18556da"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0fee6fe8c96e5bed40554978acdfce1491f2f3bc3a5eb8497244728799e57db8'),
  ('cpiuris2025::e0f10d72aa55a0ff298b3b692a73a478', 'doutrina', 'cp_iuris', 'Direito Administrativo — Exigências e Condições para Contratação', '## Exigências e Condições para Contratação

Resumo objetivo: Exigências para contratação de serviços, produtos ou obras, incluindo a apresentação de documentos justificativos.

### Conceitos
- **licitação**: Processo público para a contratação de serviços, produtos ou obras.
- **edital**: Documento que define as condições da licitação.
- **contrato**: Acordo entre a Administração e o licitante.
- **prova**: Demonstração de fato ou circunstância que justifica uma exigência.
- **requisito indispensável**: Fator essencial para a realização do contrato.
- **execução do contrato**: Cumprimento das obrigações contratuais por parte da Administração ou do licitante.

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância das exigências para contratação e como elas afetam o processo de licitação.
- Identifique os requisitos indispensáveis para a realização do contrato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.203 (2)", "page_number": 203, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:29:47.765872+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=203", "doc_key": "e0f10d72aa55a0ff298b3b692a73a478"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b67f0f4230f1b0053a005508907a98417a789c515aa2c73f66f50c868c16ac7d'),
  ('cpiuris2025::770c6bf07754e47b487821c9c014a08d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Requisitos para a Aceitação de Propostas em Licitações', '## Requisitos para a Aceitação de Propostas em Licitações

A Administração pode aceitar propostas de licitantes com base em certificações, declarações e documentos que comprovem a qualidade do produto ou serviço apresentado.

### Conceitos
- **Norma Técnica**: Regra técnica estabelecida por órgãos oficiais competentes ou entidades credenciadas
- **Declaração de Atendimento Satisfatório**: Comunicação do licitante sobre a satisfação com o produto ou serviço apresentado
- **Certificação de Qualidade**: Documento emitido por instituição oficial competente ou entidade credenciada que comprove a qualidade do produto ou processo de fabricação

### Referências legais
- Art. 42 da Lei N° 14.133/21
- Súmula 345 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Aceitação de Propostas em Licitações

### Dicas de prova
- Entenda a importância das normas técnicas e certificações na aceitação de propostas
- Diferencie entre declarações de atendimento satisfatório e certificações de qualidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.204 (1)", "page_number": 204, "discipline": "Direito Administrativo", "legal_refs": ["Art. 42 da Lei N° 14.133/21", "Súmula 345 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Aceitação de Propostas em Licitações"], "confidence": 0.8, "extracted_at": "2026-05-25T07:30:36.494523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=204", "doc_key": "770c6bf07754e47b487821c9c014a08d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'dd3298b8e1267c9ca9a3e1b78ec3e450886d29bfd62139b08d4b8090e2d60ee5'),
  ('cpiuris2025::8b64be2355f6edf9b8511ad5e531155c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Execução de obras e serviços de engenharia', '## Execução de obras e serviços de engenharia

Regras para execução direta e indireta de obras e serviços de engenharia, incluindo formas de contratação.

### Conceitos
- **Execução Direta**: execução realizada pelos próprios órgãos ou entidades da Administração
- **Execução Indireta**: execução contratada a terceiros
- **Empreitada por Preço Unitário**: forma de contratação para execução indireta
- **Empreitada por Preço Global**: forma de contratação para execução indireta
- **Empreitada Integral**: forma de contratação para execução indireta
- **Contratação por Tarefa**: forma de contratação para execução indireta

### Referências legais
- Art. 46 da Lei nº X
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre execução direta e indireta
- Conheça as formas de contratação para execução indireta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.204 (2)", "page_number": 204, "discipline": "Direito Administrativo", "legal_refs": ["Art. 46 da Lei nº X", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:31:26.809274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=204", "doc_key": "8b64be2355f6edf9b8511ad5e531155c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '127fc333faaad0258659d5c97fbbbb558c5f711a8257b26268d7aa1227af32b5'),
  ('cpiuris2025::4555ae3561037f38152cebcec5d530e8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação Integrada', '## Contratação Integrada

A contratação integrada é um regime de contratação em que o contratado é responsável por elaborar e desenvolver os projetos básico e executivo, executar obras e serviços de engenharia, fornecer bens ou prestar serviços especiais e realizar montagem, teste, pré-operação e as demais operações necessárias e suficientes para a entrega final do objeto. O contratado fica obrigado a entregar a obra ou o serviço em condições de uso imediato.

### Conceitos
- **Contratação Integrada**: Regime de contratação em que o contratado é responsável por elaborar e desenvolver os projetos básico e executivo, executar obras e serviços de engenharia, fornecer bens ou prestar serviços especiais.
- **Turn Key**: Chamada de contratação integrada, onde o contratado fica obrigado a entregar a obra ou o serviço em condições de uso imediato.
- **Matriz de Alocação de Riscos**: Documento que contempla a alocação de riscos entre o contratante e o contratado nos termos do art. 22, § 3º.
- **Projeto Básico**: Projeto elaborado pelo contratado para a contratação integrada.
- **Projeto Executivo**: Projeto elaborado pelo contratado para a contratação integrada, que detalha as obras e serviços de engenharia.
- **Remuneração Orientada por Preços Unitários**: Sistemática de remuneração que não é adotada na contratação integrada.
- **Execução de Quantidades de Itens Unitários**: Método de execução de obras e serviços de engenharia que não é adotado na contratação integrada.

### Referências legais
- Art. 6º, XXXII da Lei N° 14.133/21

### Dicas de prova
- Entenda a diferença entre contratação integrada e turn key.
- Conheça a matriz de alocação de riscos e sua importância na contratação integrada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.205 (1)", "page_number": 205, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XXXII da Lei N° 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:32:39.514086+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=205", "doc_key": "4555ae3561037f38152cebcec5d530e8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '52616f087e9f1e16d926447a3e93948558dc68a81903022e7b18b14cc31a55f3'),
  ('cpiuris2025::a30c9ab9a0e910330ee43f1b5d0b7696', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação Integrada e Responsabilidade na Matriz de Riscos', '## Contratação Integrada e Responsabilidade na Matriz de Riscos

A Administração não é obrigada a elaborar um projeto básico para a contratação integrada, mas deve aprovar o anteprojeto definido por um contratado. A responsabilidade integral do contratado pelos riscos associados ao projeto básico é mantida.

### Conceitos
- **Contratação Integrada**: Acordo entre a Administração e o contratado para realizar um empreendimento
- **Responsabilidade na Matriz de Riscos**: Obrigação do contratado de assumir os riscos associados ao projeto básico

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre anteprojeto e projeto básico
- Conheça as responsabilidades do contratado em relação à matriz de riscos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.205 (2)", "page_number": 205, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:33:15.697204+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=205", "doc_key": "a30c9ab9a0e910330ee43f1b5d0b7696"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0c487f44f40d3b863e0e26e682e2349438200dbe8008aabd027c2e9ead428d74'),
  ('cpiuris2025::22f842a846fa195f97e4c038502f2397', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação Pública', '## Contratação Pública

Rege-se a contratação pública em dois regimes: integrado e semi-integrado. No regime integrado, o projeto básico é elaborado pela Administração, enquanto no regime semi-integrado, o contratado é responsável por elaborar o projeto básico.

### Conceitos
- **Contratação Integrada**: Recebe o projeto básico elaborado pela Administração
- **Contratação Semi-integrada**: O contratado é responsável por elaborar o projeto básico
- **Projeto Básico**: Documento que define as especificações e objetivos da obra ou serviço

### Referências legais
- Art. 6º, XXXIII da Lei N° 14.133/21

### Dicas de prova
- Diferença entre contratação integrada e semi-integrada
- Projeto básico: quem elabora e quem é responsável
- Alteração do projeto básico: quando e como?', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.206 (1)", "page_number": 206, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XXXIII da Lei N° 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:34:09.810983+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=206", "doc_key": "22f842a846fa195f97e4c038502f2397"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7a9c12594b0f22ddc8b7db11cf8fc04a23ed6bf7e1386eef14cf6506fb7f3c0f'),
  ('cpiuris2025::a01f7409714e74fed7144751550c3bb0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação Semi-Integrada', '## Contratação Semi-Integrada

O edital de contratação semi-integrada deve prever a matriz de alocação de riscos entre o contratante e o contratado, incluindo a responsabilidade pelo pagamento de indenizações e a distribuição objetiva de riscos.

### Conceitos
- **Contratação Semi-Integrada**: Forma de contratação que envolve a alocação de riscos entre o contratante e o contratado.
- **Matriz de Alocação de Riscos**: Documento que define a distribuição objetiva de riscos entre as partes na contratação semi-integrada.
- **Responsabilidade pelo Pagamento de Indenizações**: Obrigação do contratado de pagar indenizações decorrentes da expropriação autorizada pelo poder público.

### Referências legais
- Art. 22, § 4º, da Lei nº 8.666/1993

### Dicas de prova
- Pergunte sobre a matriz de alocação de riscos e responsabilidade pelo pagamento de indenizações.
- Destaque a importância do edital de contratação semi-integrada em relação à expropriação autorizada pelo poder público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.206 (2)", "page_number": 206, "discipline": "Direito Administrativo", "legal_refs": ["Art. 22, § 4º, da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:34:53.657471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=206", "doc_key": "a01f7409714e74fed7144751550c3bb0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0feeee2b78519ff8af73adf2066ae44906ac8bb4d860a41730fd80be79de89fa'),
  ('cpiuris2025::1d0a28d3496659271b5c4d1ea9bcef0c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação Pública', '## Contratação Pública

Rege a contratação pública, definindo as regras para a realização de licitações e a execução das obras ou serviços.

### Conceitos
- **Lei da Licitação**: Regulamenta a contratação pública
- **Contratação Semi-Integrada**: Forma de contratação que combina elementos de concorrência e preços unitários
- **Fornecimento e Prestação de Serviço Associado**: Regime de contratação que inclui a responsabilidade do contratado por operação, manutenção ou ambas
- **Empreitada por Preço Unitário**: Contratação da execução da obra ou do serviço por preço certo de unidades determinadas
- **Empreitada por Preço Global**: Contratação da execução da obra ou do serviço por preço certo e total

### Referências legais
- Art. 6º, XXXIV da Lei nº 8.666/1993
- Súmula 643 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: contratação pública

### Dicas de prova
- Entenda a diferença entre contratação semi-integrada e preços unitários
- Conheça as regras para a empreitada por preço global', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XXXIV da Lei nº 8.666/1993", "Súmula 643 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: contratação pública"], "confidence": 0.8, "extracted_at": "2026-05-25T07:35:47.990636+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=207", "doc_key": "1d0a28d3496659271b5c4d1ea9bcef0c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd694ac11636da400fb8ec18fb654cd08f8069bb3aa589b9c58a7fd89348d1f93'),
  ('cpiuris2025::2581960beee97e024316da757beba3e6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Empreitada por preço global', '## Empreitada por preço global

A empreitada por preço global é cabível quando a Administração tem elementos suficientes para determinar os quantitativos do objeto a ser licitado.

### Conceitos
- **empreitada integral**: contratação de empreendimento em sua integralidade, com todas as etapas de obras, serviços e instalações
- **inteira responsabilidade**: o contratado é responsável pelo empreendimento até sua entrega ao contratante

### Referências legais
- Art. 6º, XXX da Lei X

### Dicas de prova
- Perguntas sobre a cabível de empreitada por preço global podem ser respondidas com base nos elementos suficientes para determinar os quantitativos do objeto a ser licitado.
- A distinção entre empreitada integral e não é sempre clara, mas geralmente se refere à responsabilidade do contratado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XXX da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:36:29.789157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=207", "doc_key": "2581960beee97e024316da757beba3e6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '293e4008b9f6070e06ba51060c45fda3f357a868ef00b1b596e80c20c69b4974'),
  ('cpiuris2025::e0abc4947524efbd802dc9a8b8a0d3d9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação de Serviços e Empreitada Integral', '## Contratação de Serviços e Empreitada Integral

A empreitada integral é um tipo de contratação onde o contratado entrega a obra ou serviço em condições de uso imediato, após a virada da chave. Há diferença entre contratação integrada e empreitada integral.

### Conceitos
- **Empreitada Integral**: Contratação onde o contratado entrega a obra ou serviço em condições de uso imediato
- **Contratação Integrada**: Contratação onde todas as etapas são realizadas pelo contrato, desde projeto básico até realização da obra ou do serviço
- **Turn Key**: Chamado de empreitada integral, onde o contratado entrega a obra ou serviço em condições de uso imediato
- **Contratação por Tarefa**: Regime de contratação de mão de obra para pequenos trabalhos por preço certo

### Referências legais
- Art. 6º, XXXI da Lei N° 14.133/21
- Art. 47 e Art. 48 da Lei N° 14.133/21

### Dicas de prova
- Entenda a diferença entre contratação integrada e empreitada integral
- Conheça o conceito de turn key e como ele se relaciona com a empreitada integral
- Aprenda sobre a contratação por tarefa e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.208 (1)", "page_number": 208, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XXXI da Lei N° 14.133/21", "Art. 47 e Art. 48 da Lei N° 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:37:25.135505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=208", "doc_key": "e0abc4947524efbd802dc9a8b8a0d3d9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c5cd78e9c92b05dbe0dcd59aab0c2f2f02cd4f4f28544830917f768e163a565e'),
  ('cpiuris2025::580615f819297aa5e99e493b3c7f84bf', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos de Terceirização e Proibição de Relacionamentos', '## Contratos de Terceirização e Proibição de Relacionamentos

Resumo objetivo: Estabelecer vínculo de subordinação com funcionário terceirizado, definir forma de pagamento e proibir relacionamentos entre contratado e dirigente do órgão contratante.

### Conceitos
- **Contrato de Terceirização**: Acordo entre a Administração Pública e uma empresa para prestação de serviços.
- **Subordinação Funcionária**: Relação de dependência da função pública com relação à função privada.
- **Reembolso de Salários**: Pagamento feito pelo contratado ao funcionário terceirizado.
- **Tarefas fora do Escopo**: Trabalhos não previstos na contratação.
- **Intervenção Indvida da Administração**: Ato ilegal ou excessivo da Administração em relação ao contratado.
- **Proibição de Relacionamentos**: Restrição à contratação de cônjuge, companheiro ou parente até o terceiro grau com dirigente do órgão contratante.
- **Edital de Licitação**: Documento que define as condições da licitação e proíbe certas relações.

### Referências legais
- Art. 24, § 3º da Lei nº 8.666/1992

### Jurisprudência
- Súmula 643 do STF

### Dicas de prova
- Distinguir entre vínculo de subordinação e relação de independência.
- Entender a importância do edital de licitação na proibição de relacionamentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.208 (2)", "page_number": 208, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24, § 3º da Lei nº 8.666/1992"], "jurisprudence": ["Súmula 643 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T07:38:18.995935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=208", "doc_key": "580615f819297aa5e99e493b3c7f84bf"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '39e94fb21fed97e513f9322d4d49c7a90fa22cf31f71549f051e1bf83ce971ec'),
  ('cpiuris2025::a44d7b05c5715c1e70ef68538e66a957', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação Pública e Licitações', '## Contratação Pública e Licitações

A Administração pode contratar mais de uma empresa para executar o mesmo serviço desde que não haja perda de economia de escala. A múltipla execução é conveniente se for capaz de ser feita concorrentemente e simultaneamente por mais de um contratado.

### Conceitos
- **Contratação Pública**: Procedimento administrativo para aquisição de bens ou serviços
- **Licitação**: Procedimento que visa garantir a competitividade e a transparência na contratação pública
- **Economia de Escala**: Benefício obtido pela Administração ao contratar um serviço com uma empresa, permitindo reduzir custos
- **Contrato de Dedicação Exclusiva**: Convenio pelo qual o contratado se compromete a realizar um serviço exclusivamente para a Administração
- **FGTS**: Fundo de Garantia do Tempo de Serviço, instituição que protege os direitos dos trabalhadores

### Referências legais
- Art. 49 da Lei nº 14.133/21
- Art. 48 da Lei nº 14.133/21
- Art. 51 da Lei nº 14.133/21

### Dicas de prova
- Entenda a noção de economia de escala e como ela afeta a contratação pública
- Conheça as exigências para a licitação internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.209 (1)", "page_number": 209, "discipline": "Direito Administrativo", "legal_refs": ["Art. 49 da Lei nº 14.133/21", "Art. 48 da Lei nº 14.133/21", "Art. 51 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:39:24.914293+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=209", "doc_key": "a44d7b05c5715c1e70ef68538e66a957"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cca4f774fb9d951572380011e3d6ad5e631281f4c036c70e261c2f1ad896c496'),
  ('cpiuris2025::6eb18d526d574fb9fc6f44c89ba5eae7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitações Internacionais', '## Licitações Internacionais

Rege-se a licitação internacional com diretrizes da política monetária e do comércio exterior, permitindo cotização de preços em moeda estrangeira.

### Conceitos
- **licitação internacional**: procura pública realizada entre países diferentes
- **diretrizes da política monetária**: normas que regulam a economia nacional
- **comércio exterior**: compra e venda de bens e serviços entre países
- **cotização de preços em moeda estrangeira**: oferta de preço em moeda diferente do brasileiro
- **garantias de pagamento**: segurança oferecida ao licitante para garantir o pagamento

### Referências legais
- Art. 72 da Lei nº 8.666/1993

### Dicas de prova
- Diferenciar entre cotização de preços em moeda nacional e estrangeira
- Entender a importância das diretrizes da política monetária e do comércio exterior', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.209 (2)", "page_number": 209, "discipline": "Direito Administrativo", "legal_refs": ["Art. 72 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:40:02.398182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=209", "doc_key": "6eb18d526d574fb9fc6f44c89ba5eae7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '45248d9c7cf6e74b9e5e1460b270c1f1c3bdc560e1cb636fe2f296121a2c197e'),
  ('cpiuris2025::413ec3cdebdb0e28743db9dcd143051e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Credenciamento e Contratação Pública', '## Credenciamento e Contratação Pública

O credenciamento é um procedimento administrativo que permite a Administração Pública convocar interessados em prestar serviços ou fornecer bens. Os credenciados podem ser contratados de acordo com critérios objetivos, seja em paralela e não excludente, com seleção a critério de terceiros ou em mercados fluidos.

### Conceitos
- **Credenciamento**: Processo administrativo que permite a Administração Pública convocar interessados em prestar serviços ou fornecer bens.
- **Contratação Pública**: Procedimento utilizado pela Administração Pública para adquirir bens ou serviços.
- **Paralela e não excludente**: Hipótese em que é viável e vantajosa para a Administração realizar contratações simultâneas em condições padronizadas.
- **Seleção a critério de terceiros**: Método de seleção do contratado realizado por terceiros, sem envolvimento direto da Administração.
- **Mercados fluidos**: Situação em que a flutuação constante do valor da prestação e das condições de contratação torna inviável a seleção de agente por meio de processo de licitação.

### Referências legais
- Art. 6º, XLIII da Lei n.º 14.133/21
- Art. 79 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a diferença entre credenciamento e contratação pública.
- Conheça as hipóteses em que o credenciamento pode ser utilizado.
- Aprenda a distinguir entre seleção a critério de terceiros e mercados fluidos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.210", "page_number": 210, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XLIII da Lei n.º 14.133/21", "Art. 79 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:41:10.599937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=210", "doc_key": "413ec3cdebdb0e28743db9dcd143051e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0eab4a714d184186fc5fae078b3706038ca96c2d1a9558101283ae2038eb3020'),
  ('cpiuris2025::fb01a181b837bfbf422c329b242e5278', 'doutrina', 'cp_iuris', 'Direito Administrativo — Pré-qualificação em Licitações', '## Pré-qualificação em Licitações

A pré-qualificação é um procedimento seletivo prévio à licitação, destinado à análise das condições de habilitação dos interessados ou do objeto. Pode ser realizada para selecionar licitantes ou bens que atendam às exigências técnicas ou de qualidade estabelecidas pela Administração.

### Conceitos
- **Pré-qualificação**: Procedimento seletivo prévio à licitação
- **Habilitação**: Condições técnicas ou de qualidade estabelecidas pela Administração
- **Licitantes**: Participantes da licitação
- **Bens**: Objetos a serem contratados

### Referências legais
- Art. 6º, XLIV da Lei n.º 14.133/21

### Dicas de prova
- Entenda a diferença entre pré-qualificação de licitantes e bens.
- Conheça as exigências técnicas ou de qualidade estabelecidas pela Administração.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.211", "page_number": 211, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, XLIV da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:42:08.055888+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=211", "doc_key": "fb01a181b837bfbf422c329b242e5278"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '647cef3771a4f43ca9f13ec0737b9dd725913e50a2899b956168104beb8be95c'),
  ('cpiuris2025::5b8889bba6506a1bbd9429d2a327f386', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitação e Manifestação de Interesse', '## Licitação e Manifestação de Interesse

A licitação pode ser restrita a licitantes pré-qualificados ou realizar procedimento de manifestação de interesse para propositura de estudos inovadores.

### Conceitos
- **Pre-qualificação**: Procedimento que avalia a capacidade dos licitantes antes da abertura do leilão.
- **Manifestação de Interesse**: Procedimento aberto para a iniciativa privada apresentar propostas inovadoras.
- **Direito de Preferência**: Direito concedido ao realizador do estudo, que não é transferível.
- **Parecer Fundamentado**: Elaboração de parecer que demonstra a adequação e suficiência do produto ou serviço.

### Referências legais
- Art. 81 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a diferença entre manifestação de interesse e licitação tradicional.
- Conheça as regras para a seleção de startups em procedimentos de manifestação de interesse.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.212 (1)", "page_number": 212, "discipline": "Direito Administrativo", "legal_refs": ["Art. 81 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:42:54.081986+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=212", "doc_key": "5b8889bba6506a1bbd9429d2a327f386"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fd7c85ae3a6a5c4f808860d63f5e25d405df7ca7e73f840d2ac94582e2760094'),
  ('cpiuris2025::5a1f710f07f30c444fe773b4aca5f400', 'doutrina', 'cp_iuris', 'Direito Administrativo — Formação do SRP e Licitações', '## Formação do SRP e Licitações

A formação do SRP pode ser utilizada em contratação direta ou licitação, bem como nas modalidades pregão ou concorrência. O edital de licitação para registro de preços deve especificar as características da licitação.

### Conceitos
- **SRP**: Sistema de Registros Públicos
- **Contratação Direta**: Processo de contratação sem a necessidade de licitação
- **Licitação**: Processo público para a aquisição de bens ou serviços

### Referências legais
- Art. 82 da Lei nº 8.666/1993

### Dicas de prova
- Entenda a importância do SRP na licitação
- Conheça as especificidades do edital de licitação para registro de preços', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.212 (2)", "page_number": 212, "discipline": "Direito Administrativo", "legal_refs": ["Art. 82 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:43:27.695699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=212", "doc_key": "5a1f710f07f30c444fe773b4aca5f400"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '962a74ae435091f819af121ed1914107265d989f5717fad0d6cfde558394cc8f'),
  ('cpiuris2025::79cbbef66527e67d0abc451d1574f982', 'doutrina', 'cp_iuris', 'Direito Administrativo — Registro de Preços e Critérios de Julgamento em Licitações', '## Registro de Preços e Critérios de Julgamento em Licitações

O texto discute as regras para o registro de preços e critérios de julgamento em licitações, incluindo a possibilidade de oferecer propostas inferiores ao máximo previsto no edital, o critério de julgamento (menor preço ou maior desconto), condições para alteração de preços registrados e vedação à participação do órgão em mais de uma ata de registro de preços.

### Conceitos
- **Critério de Julgamento**: O critério de julgamento é o método utilizado para avaliar as propostas dos licitantes e determinar o vencedor.
- **Registro de Preços**: O registro de preços é um processo que permite ao órgão ou entidade contratar bens e serviços sem a necessidade de uma nova licitação.
- **Ata de Registro de Preços**: A ata de registro de preços é um documento que registra os preços oferecidos pelos fornecedores ou prestadores de serviço.

### Referências legais
- Art. 24 da Lei nº 8.666/1993

### Dicas de prova
- Entenda o critério de julgamento e as condições para registro de preços.
- Conheça as hipóteses de cancelamento da ata de registro de preços.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.213 (1)", "page_number": 213, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:44:31.475055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=213", "doc_key": "79cbbef66527e67d0abc451d1574f982"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0067b282cca56b9eb6284df59a5515f2195a611ee1ade97636d5ede3544e0550'),
  ('cpiuris2025::4c2431a2391f7437d3443c6841fb5420', 'doutrina', 'cp_iuris', 'Direito Administrativo — Registro de Preços e Contratação Pública', '## Registro de Preços e Contratação Pública

Regra para o registro de preços, incluindo o licitante que aceita cotar em preços iguais ao vencedor na sequência de classificação da licitação.

### Conceitos
- **Ata de Registro de Preços**: Documento que registra os preços aceitos por licitantes
- **Inexigibilidade e Dispensa de Licitação**: Hipóteses em que a Administração pode contratar sem licitação
- **Fornecimento Comprometido**: Obrigação da Administração de fornecer bens ou serviços de acordo com as condições estabelecidas

### Referências legais
- Art. 24, § 4º da Lei nº 8.666/1993
- Súmula 643 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Registro de Preços e Contratação Pública

### Dicas de prova
- Entenda a diferença entre inexigibilidade e dispensa de licitação
- Conheça as condições para o compromisso de fornecimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.213 (2)", "page_number": 213, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24, § 4º da Lei nº 8.666/1993", "Súmula 643 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Registro de Preços e Contratação Pública"], "confidence": 0.8, "extracted_at": "2026-05-25T07:45:12.607809+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=213", "doc_key": "4c2431a2391f7437d3443c6841fb5420"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2aeb36edac6953c66fd600c0424de14de8047188a8d2350d8a1dcbf24ae9c8e2'),
  ('cpiuris2025::d48902cd2d48d32aacfd084e3c791a34', 'doutrina', 'cp_iuris', 'Direito Administrativo — Registro de Preços em Licitações', '## Registro de Preços em Licitações

A Administração pode contratar obras e serviços de engenharia pelo sistema de registro de preços, desde que atendidos requisitos específicos, como a existência de um projeto padronizado e necessidade permanente ou frequente de obra ou serviço.

### Conceitos
- **Registro de Preços**: Sistema utilizado pela Administração para contratar obras e serviços de engenharia
- **Projeto Padronizado**: Projeto de obra ou serviço que pode ser utilizado por diferentes órgãos ou entidades
- **Necessidade Permanente ou Frequente**: Condição necessária para a contratação de obras e serviços de engenharia pelo sistema de registro de preços
- **Ata de Registro de Preços**: Documento que registra os valores e quantidades das obras e serviços de engenharia

### Referências legais
- Art. 86, § 2º da Lei n. 14.133/21
- Lei n. 14.770/2023, art. 86, § 3º

### Dicas de prova
- Entenda a diferença entre registro de preços e adesão à ata de registro de preços
- Conheça os requisitos para a contratação de obras e serviços de engenharia pelo sistema de registro de preços', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.214 (1)", "page_number": 214, "discipline": "Direito Administrativo", "legal_refs": ["Art. 86, § 2º da Lei n. 14.133/21", "Lei n. 14.770/2023, art. 86, § 3º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:46:06.022940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=214", "doc_key": "d48902cd2d48d32aacfd084e3c791a34"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '145430f6b4da4a147220139a32ccbf241a389a225ca9949737c85c593b58d468'),
  ('cpiuris2025::10d1b79b8bb9f544c3c0c6b1a8e12f82', 'doutrina', 'cp_iuris', 'Direito Administrativo — Limites globais para a adesão à ata de registro de preços', '## Limites globais para a adesão à ata de registro de preços

A adesão à ata de registro de preços está sujeita a limites globais, exceto em casos específicos como transferências voluntárias e aquisição emergencial de medicamentos.

### Conceitos
- **Limites globais**: Definido como o dobro do quantitativo de cada item registrado na ata de registro de preços
- **Adesão à ata de registro de preços**: Exigida para fins de transferências voluntárias e aquisição emergencial de medicamentos

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de limites globais e suas exceções
- Identifique as hipóteses em que a adesão à ata de registro de preços não está sujeita ao limite global', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.214 (2)", "page_number": 214, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:46:50.486717+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=214", "doc_key": "10d1b79b8bb9f544c3c0c6b1a8e12f82"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4c2d2d9ce7cef8df1441f50041389f83aba5552506df6c1c31b1212c0ee0f3e5'),
  ('cpiuris2025::1bb8d92b6e0361aa4e49598eba124a66', 'doutrina', 'cp_iuris', 'Direito Administrativo — Registro Cadastral em Licitações', '## Registro Cadastral em Licitações

A Lei nº 14.133/21 estabelece requisitos para o registro cadastral de licitantes, incluindo a utilização do sistema de registro cadastral unificado e a realização de chamamento público anual.

### Conceitos
- **Registro Cadastral**: sistema de cadastro unificado de licitantes
- **Licitação Restrita**: licitação restrita a fornecedores cadastrados
- **Inscrição no Cadastro**: requerimento para inscrição no cadastro ou atualização do registro
- **Certificado de Habilitação**: documento renovável que comprova a habilitação do licitante
- **Avaliação do Desempenho**: avaliação do desempenho do contratado em cumprir obrigações assumidas

### Referências legais
- Art. 87 da Lei nº 14.133/21

### Dicas de prova
- Entenda a importância do registro cadastral unificado e a realização de chamamento público anual.
- Conheça as exigências para a inscrição no cadastro e o processo de habilitação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.215", "page_number": 215, "discipline": "Direito Administrativo", "legal_refs": ["Art. 87 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:47:38.935471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=215", "doc_key": "1bb8d92b6e0361aa4e49598eba124a66"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5563c43cef5a235947ad6831525e156ddb811dcb1b774a5115a94b3c0add75e5'),
  ('cpiuris2025::5d2e8a697e8814132e1c1855804aac59', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

Contratos administrativos são acordos de vontades entre a Administração Pública e terceiros para consecução de um fim de interesse público, segundo normas de Direito Público.

### Conceitos
- **Contrato Administrativo**: Acordo de vontades entre a Administração Pública e terceiros para consecução de um fim de interesse público.
- **Direito Público**: Regras que regem os contratos administrativos
- **Fim de Interesse Público**: Objetivo que justifica a celebração do contrato administrativo

### Referências legais
- Art. 89 da Lei n.º 14.133/21
- Art. 190, §1º da Lei n.º 14.133/21

### Dicas de prova
- Entenda a diferença entre contratos da Administração e contratos administrativos.
- Conheça as características dos contratos consensuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.219", "page_number": 219, "discipline": "Direito Administrativo", "legal_refs": ["Art. 89 da Lei n.º 14.133/21", "Art. 190, §1º da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:48:21.874744+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=219", "doc_key": "5d2e8a697e8814132e1c1855804aac59"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f4b054c870d639ad6b7f71fe4aefd81a2e42dd97d04b3ee01c0b147144212628'),
  ('cpiuris2025::069a63740d59ec59645df105e2347723', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

Os contratos administrativos são formais ou solenes e exigem uma forma pré-estabelecida em lei para se tornarem válidos. Atualmente, alguns doutrinadores defendem o chamado formalismo moderado, que permite contratos verbais com a Administração Pública, salvo em casos específicos.

### Conceitos
- **Formalidade**: Exigência de uma forma pré-estabelecida em lei para se tornar válido
- **Contrato verbal**: Contrato não formalizado, permitido apenas em casos específicos
- **Termo de Ajuste de Contas**: Instrumento legal que regulariza contratos não formalizados e autoriza o pagamento de despesas
- **Bilateralidade**: Prestação e contraprestação para as partes envolvidas
- **Onerosidade**: Direitos e obrigações para ambas as partes
- **Comutatividade**: Prestação e contraprestação já previamente conhecidas pelas partes
- **Adesão**: Contrato em que as cláusulas contratuais são pré-definidas por uma das partes

### Referências legais
- Art. 95, § 2º, da Lei nº 8.666/1993

### Dicas de prova
- Entenda a distinção entre formalidade e contratos verbais
- Conheça o Termo de Ajuste de Contas como instrumento legal para regularizar contratos não formalizados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.220", "page_number": 220, "discipline": "Direito Administrativo", "legal_refs": ["Art. 95, § 2º, da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:49:29.827451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=220", "doc_key": "069a63740d59ec59645df105e2347723"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0f0a440c6d61733c795e567cec36a951e8124a23e3c50148a85ebe45fd0763ad'),
  ('cpiuris2025::1eac050a60d984c5213e18f4425a1042', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

Os contratos administrativos possuem cláusulas exorbitantes que colocam a Administração Pública em uma relação superior ao contratado. Além disso, os contratos são mutáveis e personalíssimos, permitindo a subcontratação até um limite autorizado pela Administração.

### Conceitos
- **Cláusulas Exorbitantes**: cláusulas que colocam a Administração Pública em uma relação superior ao contratado
- **Mutabilidade**: característica intrínseca aos contratos administrativos, permitindo alterações unilaterais determinadas pela Administração Pública
- **Personalíssimo**: contrato que cabe ao contratado executar o objeto licitado, vedada sua execução por terceiros

### Referências legais
- Art. 104 da Lei n.º 14.133/21
- Art. 122 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a noção de cláusulas exorbitantes e sua importância nos contratos administrativos
- Conheça a mutabilidade e a personalidade dos contratos administrativos
- Avalie as condições para a subcontratação nos contratos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.221 (1)", "page_number": 221, "discipline": "Direito Administrativo", "legal_refs": ["Art. 104 da Lei n.º 14.133/21", "Art. 122 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:50:20.122944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=221", "doc_key": "1eac050a60d984c5213e18f4425a1042"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9322692ad86a0d1e9e642406457805b2727bfca19a26d8c21cad5e57f1840db5'),
  ('cpiuris2025::d5d793a49a979f841b12936d0775d6d8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prazo para assinatura de contrato em licitação', '## Prazo para assinatura de contrato em licitação

O vencedor deve assinar o termo de contrato ou aceitar/retirar o instrumento equivalente dentro do prazo e nas condições estabelecidas no edital de licitação, sob pena de perder o direito à contratação.

### Conceitos
- **Prazo para assinatura de contrato**: O período durante o qual deve ser feita a assinatura do termo de contrato ou aceitar/retirar o instrumento equivalente.
- **Licitação**: O processo pelo qual a Administração Pública busca adquirir bens ou serviços.
- **Edital de licitação**: O documento que estabelece as regras e condições da licitação.
- **Convocação**: A notificação do vencedor para assinatura do termo de contrato ou aceitar/retirar o instrumento equivalente.
- **Sancionamento**: O ato de impor uma penalidade ou sanção à entidade que não cumpre com as regras estabelecidas na licitação.
- **Lei n.º 14.133/21**: A legislação que estabelece o prazo para a convocação no edital de licitação.
- **Prazo de 60 dias**: O período anteriormente previsto para a entrega das propostas para convocação.

### Referências legais
- Art. 24 da Lei n.º 8.666/1993
- Súmula 643 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Prazo para assinatura de contrato em licitação

### Dicas de prova
- Pegar a diferença entre o prazo anterior e o novo estabelecido pela Lei n.º 14.133/21.
- Entender que o edital da licitação disciplinar o prazo para a convocação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.221 (2)", "page_number": 221, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei n.º 8.666/1993", "Súmula 643 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prazo para assinatura de contrato em licitação"], "confidence": 0.8, "extracted_at": "2026-05-25T07:51:22.847818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=221", "doc_key": "d5d793a49a979f841b12936d0775d6d8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'de09fa70578bccd5a545c727c4e683f98c01f6ddab2e2e80c89488be6e4fc815'),
  ('cpiuris2025::1035263752974ef90c472d8fb80177bf', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

O prazo de convocação pode ser prorrogado uma vez por igual período, desde que justificada a solicitação da parte. A Administração pode convocar os licitantes remanescentes para celebração do contrato nas condições propostas pelo licitante vencedor.

### Conceitos
- **Convocação**: Solicitação da Administração para a celebração de um contrato
- **Prazo de convocação**: Período durante o qual a Administração pode convocar os licitantes para a celebração do contrato
- **Licitante remanescente**: Licitação que não foi concluída devido à falta de aceitação da proposta ou ao não assinatura do termo de contrato

### Referências legais
- Art. 90, § 4º
- Súmula 395/STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de convocação e seu prazo
- Conheça as hipóteses em que a Administração pode convocar os licitantes remanescentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.222 (1)", "page_number": 222, "discipline": "Direito Administrativo", "legal_refs": ["Art. 90, § 4º", "Súmula 395/STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T07:52:20.718121+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=222", "doc_key": "1035263752974ef90c472d8fb80177bf"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ca9596038a7a8ec3692f51cde00f276b20eda537b1ec4926a649bc3a5bdb0e8f'),
  ('cpiuris2025::2eee1efe65854d3c82ef5c24c7592d64', 'doutrina', 'cp_iuris', 'Direito Administrativo — Cláusulas Necessárias em Contratos Administrativos', '## Cláusulas Necessárias em Contratos Administrativos

São cláusulas necessárias em contratos administrativos aquelas que obrigatoriamente terão nos contratos, estabelecidas no art. 92 da Lei n.º 14.133/21.

### Conceitos
- **Cláusula Necessária**: cláusula obrigatória em contrato administrativo
- **Contrato Administrativo**: acordo entre o Poder Público e uma pessoa jurídica ou física para a realização de um serviço ou fornecimento
- **Lei n.º 14.133/21**: Lei que estabelece as regras para os contratos administrativos

### Referências legais
- Art. 92 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a importância das cláusulas necessárias em contratos administrativos
