Resumo dos itens XIX a XVIII sobre cláusulas obrigatórias em contratos administrativos.

### Conceitos
- **Cláusula de Competência**: Declara o foro competente para dirimir questões contratuais
- **Licitação Internacional**: Aquisição de bens e serviços com pagamento feito por financiamento internacional ou agência estrangeira de cooperação
- **Autorização do Chefe do Poder Executivo**: Necessária para contratação com empresa estrangeira que compra equipamentos fabricados e entregues no exterior

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância das cláusulas obrigatórias em contratos administrativos
- Conheça as hipóteses de exclusão da cláusula de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.223 (1)", "page_number": 223, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T07:53:39.794127+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=223", "doc_key": "d8d51fab0152200c809cdc681f456cfd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '59cd83b6c89624d2da15bda046c25d7e34d99846fc2e84a28d325c925a5ee76f'),
  ('cpiuris2025::bdfcee358f0b24f79b414c13a4e5ae71', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos de Serviço e Aquisição de Bens e Serviços', '## Contratos de Serviço e Aquisição de Bens e Serviços

Regra para contratos de serviço e aquisição de bens e serviços realizados por unidades administrativas com sede no exterior, incluindo cláusula de período antecedente.

### Conceitos
- **Contrato de Serviço**: Acordo entre as partes que determina o serviço a ser prestado
- **Aquisição de Bens e Serviços**: Procedimento pelo qual uma entidade pública adquire um bem ou serviço
- **Cláusula de Período Antecedente**: Regra que estabelece um período antes da expedição da ordem de serviço para verificação de pendências

### Referências legais
- Lei sobre Contratos de Serviço e Aquisição de Bens e Serviços

### Dicas de prova
- Entenda a diferença entre contrato de serviço e aquisição de bens e serviços
- Identifique a cláusula de período antecedente como requisito obrigatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.223 (2)", "page_number": 223, "discipline": "Direito Administrativo", "legal_refs": ["Lei sobre Contratos de Serviço e Aquisição de Bens e Serviços"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:54:26.112984+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=223", "doc_key": "bdfcee358f0b24f79b414c13a4e5ae71"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9c7d1ce84e2f2957b73bb15c2ce50decd4b204add36a693e9ae628c030608ff9'),
  ('cpiuris2025::a4fd5752b6cdc74f5c19438f3cd64337', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

As garantias dos contratos administrativos podem ser exigidas pela autoridade competente desde que prevista no edital. O contratado tem a opção de escolher entre diferentes modalidades de garantia, incluindo seguro-garantia.

### Conceitos
- **Contrato Administrativo**: Acordo entre a Administração e um ente ou pessoa jurídica para realizar uma obra, fornecer um serviço ou fornecer um bem.
- **Garantia**: Mecanismo que protege o contratante contra danos causados pelo inadimplemento do contrato.
- **Seguro-Garantia**: Modalidade de garantia que oferece cobertura financeira em caso de inadimplemento do contrato.
- **Edital**: Documento que estabelece as condições da licitação e é assinado pela Administração e pelo contratante.
- **Lei n.º 14.133/21**: Lei que disciplina os contratos administrativos.

### Referências legais
- Art. 96 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a diferença entre garantia e seguro-garantia.
- Conheça as regras para a substituição da apólice de seguro-garantia nos contratos de execução continuada ou de fornecimento contínuo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.224 (1)", "page_number": 224, "discipline": "Direito Administrativo", "legal_refs": ["Art. 96 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:55:18.900095+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=224", "doc_key": "a4fd5752b6cdc74f5c19438f3cd64337"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '59b5ab6d4b4118d86d2203d6ddff09a4d93c730529efad97f876de6091affd22'),
  ('cpiuris2025::6869e778a8b917d484620d5a80a92baa', 'doutrina', 'cp_iuris', 'Direito Administrativo — Acesso e Participação dos Segurados em Contratos de Seguro', '## Acesso e Participação dos Segurados em Contratos de Seguro

O segurado tem direito a ter acesso às instalações onde será executado o contrato, acompanhar a execução do contrato e requerer esclarecimentos. A seguradora é responsável pela emissão de empenho e pagamento da importância segurada.

### Conceitos
- **Acesso ao contrato**: Direito do segurado a ter acesso às instalações onde será executado o contrato
- **Participação no contrato**: O direito do segurado de acompanhar a execução do contrato principal
- **Auditoria técnica e contábil**: Direito do segurado a ter acesso a auditoria técnica e contábil
- **Requerimento de esclarecimentos**: O direito do segurado de requerer esclarecimentos ao responsável técnico pela obra ou pelo fornecimento
- **Emissão de empenho**: A responsabilidade da seguradora em emitir empenho em nome dela ou indicada para a conclusão do contrato
- **Subcontratação**: O direito da seguradora de subcontratar a conclusão do contrato, total ou parcialmente
- **Inadimplemento do contratado**: A hipótese em que o contratado não cumpre com suas obrigações

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Pergunte sobre o acesso do segurado às instalações onde será executado o contrato
- Entenda a participação do segurado na execução do contrato principal
- Conheça o direito do segurado à auditoria técnica e contábil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.224 (2)", "page_number": 224, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:56:14.851765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=224", "doc_key": "6869e778a8b917d484620d5a80a92baa"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8eb0a650d050d0291b7dcc5eddd24328e7b3776681c141e8b7ef734339878178'),
  ('cpiuris2025::16be443c421e2b4143e736b2e5123fdb', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

Regras para alteração de garantias em contratos administrativos e alocação de riscos.

### Conceitos
- **Alteração bilateral**: Mudança feita por acordo entre as partes
- **Unilateral**: Mudança feita apenas pela Administração
- **Percentual de garantia**: Até 5% do valor inicial, exceto em casos específicos
- **Análise da complexidade técnica e dos riscos envolvidos**: Justificativa para alteração acima de 10%
- **Seguro-garantia**: Modalidade de contratação de obras e serviços com garantia
- **Matriz de alocação de riscos**: Definição do equilíbrio econômico-financeiro inicial do contrato

### Referências legais
- Art. 124, II, ‘a’ da Lei n.º 14.133/21

### Dicas de prova
- Entenda a diferença entre alteração bilateral e unilateral
- Conheça as regras para percentual de garantia e exceções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.225", "page_number": 225, "discipline": "Direito Administrativo", "legal_refs": ["Art. 124, II, ‘a’ da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:57:13.374115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=225", "doc_key": "16be443c421e2b4143e736b2e5123fdb"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0998982b26a4bcdc3dbfd59939710d4bc5b6f2a0a003ca277e5e1647aabe9180'),
  ('cpiuris2025::1ac795c7c9088733186d0638136aea6a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

Regulamentação dos contratos administrativos, incluindo alterações unilaterais e aumento ou redução de tributos, além da alocação de risco e prazo.

### Conceitos
- **Alocação de Risco**: Métodos e padrões utilizados por entidades públicas e privadas para alocar riscos
- **Contrato Administrativo**: Convenção entre a Administração Pública e uma pessoa jurídica ou física para realizar serviços ou fornecer bens
- **Prazo Contratuais**: Duração do contrato administrativo, que pode variar de até 12 meses, exceto em casos específicos
- **Extinção Contratual**: Fim do contrato sem ônus para as partes, ocorrendo apenas após a próxima data de aniversário do contrato

### Referências legais
- Art. 105 da Lei n.º 14.133/21
- Art. 112 da Lei n.º 14.133/21
- Art. 106 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a diferença entre alterações unilaterais e aumento ou redução de tributos
- Conheça as diretrizes para a alocação de risco em contratos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.226", "page_number": 226, "discipline": "Direito Administrativo", "legal_refs": ["Art. 105 da Lei n.º 14.133/21", "Art. 112 da Lei n.º 14.133/21", "Art. 106 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:58:05.826985+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=226", "doc_key": "1ac795c7c9088733186d0638136aea6a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '219ac8d6ffb62a29eaf07703528688ac05aec5393fe4fb3b48580fa4d980fa2f'),
  ('cpiuris2025::85d1122720f245b555a818fcc1618f97', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

Resumo de contratos administrativos com prazo definido ou indeterminado, conforme artigos 108 e 109.

### Conceitos
- **Contrato Administrativo**: Acordo entre a Administração Pública e uma pessoa jurídica para realizar um serviço ou fornecer um bem.
- **Prazo Definido**: Período específico estabelecido para o cumprimento do contrato.
- **Prazo Indeterminado**: Fim não fixado para o cumprimento do contrato.
- **Contratação Pública**: Procedimento administrativo destinado a contratar serviços ou bens com recursos públicos.
- **Lei nº 10.973/04**: Lei que dispõe sobre incentivos à inovação e à pesquisa científica e tecnológica no ambiente produtivo.
- **Sistema Único de Saúde (SUS)**: Rede pública de saúde brasileira.
- **Transferência de Tecnologia**: Aquisição ou desenvolvimento de produtos estratégicos para o SUS.

### Referências legais
- Art. 108 da Lei nº 8.666/1993
- Art. 109 da Lei nº 8.666/1993

### Dicas de prova
- Entenda a distinção entre contratos com prazo definido e indeterminado.
- Conheça as exceções para a contratação pública, como os casos estabelecidos pelo Ministro de Estado da Defesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.227 (1)", "page_number": 227, "discipline": "Direito Administrativo", "legal_refs": ["Art. 108 da Lei nº 8.666/1993", "Art. 109 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:59:01.979707+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=227", "doc_key": "85d1122720f245b555a818fcc1618f97"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c0148df6e46e787f97ec6b86821a10308784a8fb8d3c2880cc4962dd5edcf0e6'),
  ('cpiuris2025::d2f048e3c5479ba96bd16830dcbfddc7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Vigência de Contratos com a Administração Pública', '## Vigência de Contratos com a Administração Pública

A Administração pode estabelecer prazos indeterminados em contratos de serviço público oferecido em regime de monopólio, desde que haja créditos orçamentários vinculados à contratação.

### Conceitos
- **Contrato de Serviço Público**: Acordo entre a Administração Pública e uma entidade privada para fornecer um serviço público.
- **Monopólio**: Regime em que a Administração Pública é o único provedor de um serviço público.
- **Créditos Orçamentários Vinculados**: Créditos orçamentários que são destinados a uma determinada atividade ou projeto e não podem ser utilizados para outros fins.

### Referências legais
- Art. 109 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a diferença entre contratos de serviço público com prazo indeterminado e determinado.
- Conheça as regras para os contratos de operação continuada de sistemas estruturantes de tecnologia da informação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.227 (2)", "page_number": 227, "discipline": "Direito Administrativo", "legal_refs": ["Art. 109 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T07:59:54.540862+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=227", "doc_key": "d2f048e3c5479ba96bd16830dcbfddc7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '13fbffc22e4d5dacdf98318300f7cba8dd1ee245b74d1c56f0fc6176c2defb9a'),
  ('cpiuris2025::6455dcf9e90cae6a48d2adee542aae8e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

Os contratos administrativos são divididos em dois tipos: por escopo e de trato sucessivo. O contrato por escopo é fechado com a execução total do objeto contratual, enquanto o contrato de trato sucessivo é fechado com o cumprimento das obrigações contratuais até o prazo final.

### Conceitos
- **Contratos por escopo**: Contratos que somente são cumpridos com a execução total do objeto contratual
- **Contratos de trato sucessivo**: Contratos que são fechados com o cumprimento das obrigações contratuais até o prazo final
- **Cláusulas exorbitantes**: Cláusulas que dão poderes à Administração Pública dentro da relação contratual

### Referências legais
- Art. 111 da Lei nº 14.133/21
- Art. 104 da Lei nº 14.133/21

### Dicas de prova
- Diferenciar entre contratos por escopo e de trato sucessivo
- Entender a importância das cláusulas exorbitantes na relação contratual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.228 (1)", "page_number": 228, "discipline": "Direito Administrativo", "legal_refs": ["Art. 111 da Lei nº 14.133/21", "Art. 104 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:00:43.126760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=228", "doc_key": "6455dcf9e90cae6a48d2adee542aae8e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd0fe87e10ebb6bf16a119e449f5194e8cc20852dd0b8ad1ff321162d71a779db'),
  ('cpiuris2025::31308a546c095426ba31f8b000086fa0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade das Partes em Contratos Administrativos', '## Responsabilidade das Partes em Contratos Administrativos

Resumo objetivo: As partes em contrato administrativo devem cumprir as cláusulas avençadas e as normas da Lei, respondendo pelas consequências de sua inexecução. A Administração não pode retardar imotivadamente a execução de obras ou serviços.

### Conceitos
- **Contrato Administrativo**: Acordo entre a Administração e uma parte para realizar um serviço ou obra.
- **Responsabilidade das Partes**: O dever de cumprir as cláusulas avençadas e as normas da Lei.
- **Inexecução do Contrato**: A não cumprimento das cláusulas avençadas ou das normas da Lei.
- **Administração Retardadora**: O ato de retardar imotivadamente a execução de obras ou serviços.
- **Normas da Lei**: As regras e regulamentos que regem o contrato administrativo.
- **Avençadas**: Cláusulas acordadas pelas partes no contrato.
- **Consequências**: Os resultados negativos que podem ocorrer se as cláusulas avençadas não forem cumpridas.

### Referências legais
- Art. 115 da Lei n.º 14.133/21

### Dicas de prova
- Perguntas sobre responsabilidade das partes em contratos administrativos.
- Distinção entre inexecução total e parcial do contrato.
- Importância de cumprir as normas da Lei e as cláusulas avençadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.228 (2)", "page_number": 228, "discipline": "Direito Administrativo", "legal_refs": ["Art. 115 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:01:35.069853+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=228", "doc_key": "31308a546c095426ba31f8b000086fa0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '23fbeba7b6adf9c257fc39ef840c7b687c63586dd2b9bf604fa3c865d1ba2c26'),
  ('cpiuris2025::01007171175c0e139b213c3904a1c448', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

A Administração deve obter manifestação prévia ou licença prévia antes da divulgação do edital em contratações de obras e serviços de engenharia. Em caso de impedimento, paralisação ou suspensão do contrato, o cronograma é prorrogado automaticamente.

### Conceitos
- **Manifestação prévia**: Declaração da Administração antes da divulgação do edital
- **Licença prévia**: Permissão da Administração para iniciar a obra ou serviço
- **Fiscalização do contrato**: Acompanhamento e controle da execução do contrato
- **Responsabilidade civil objetiva**: Obrigação de pagar danos por dano causado ao terceiro
- **Termo de compromisso de confidencialidade**: Acordo entre a Administração e o terceiro contratado para manter informações em segredo

### Referências legais
- Art. 117 da Lei n.º 14.133/21

### Dicas de prova
- Pergunte sobre a importância da manifestação prévia e licença prévia nas contratações de obras e serviços de engenharia.
- Entenda o conceito de fiscalização do contrato e sua responsabilidade na execução do contrato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.229 (1)", "page_number": 229, "discipline": "Direito Administrativo", "legal_refs": ["Art. 117 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:02:35.015228+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=229", "doc_key": "01007171175c0e139b213c3904a1c448"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5df20ec35c463edf248ecbd2d3a2cc3e8b64ad8ca6916aa784bd9d1203a140aa'),
  ('cpiuris2025::463796db548efce3fe6247f7c7232d81', 'doutrina', 'cp_iuris', 'Direito Administrativo — Obrigações do Contratado', '## Obrigações do Contratado

O contratado tem obrigações específicas na execução do contrato, incluindo a responsabilidade por danos causados à Administração ou terceiros.

### Conceitos
- **Preposto**: Pessoa designada pela Administração para representá-la na execução do contrato.
- **Contratado**: Pessoa que assina o contrato e é responsável por sua execução.
- **Responsabilidade**: Obrigação de reparar ou corrigir danos causados à Administração ou terceiros.
- **Fiscalização**: Verificação periódica para garantir a conformidade com o contrato.
- **Acompanhamento**: Monitoramento contínuo da execução do contrato.
- **Danos causados**: Prejuízos sofridos pela Administração ou terceiros como resultado da execução do contrato.
- **Lei n.º 14.133/21**: Lei que regula a contratação pública e as obrigações dos contratados.
- **Art. 118**: Estabelece o dever do contratado de manter preposto aceito pela Administração.

### Referências legais
- Art. 118 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a responsabilidade do contratado e os danos causados à Administração ou terceiros.
- Conheça as obrigações específicas do contratado na execução do contrato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.229 (2)", "page_number": 229, "discipline": "Direito Administrativo", "legal_refs": ["Art. 118 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:03:26.967480+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=229", "doc_key": "463796db548efce3fe6247f7c7232d81"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0f639e23f3269f6cf6089e7a2460ff25153054be9adaee07046be005861e0c37'),
  ('cpiuris2025::f8cee9bb160ba8049c528064ed0043b5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

O contratado é responsável pelos encargos trabalhistas, previdenciários e comerciais resultantes da execução do contrato. A Administração não pode onerar o objeto do contrato ou restringir a regularização e uso das obras e edificações.

### Conceitos
- **Contrato Administrativo**: Acordo entre a Administração e um contratado para realizar serviços.
- **Responsabilidade do Contratado**: O contratado é responsável pelos encargos trabalhistas, previdenciários e comerciais resultantes da execução do contrato.
- **Administração Responsável**: A Administração não pode onerar o objeto do contrato ou restringir a regularização e uso das obras e edificações.
- **Encargos Trabalhistas**: Obras e serviços realizados pelo contratado.
- **Previdenciários**: Pagamentos relacionados à previdência social do contratado.
- **Comerciais**: Gastos e despesas relacionadas ao contrato.
- **Sanções ao Contratado**: Medidas tomadas pela Administração em caso de inadimplemento do contrato.
- **Caução Fiança Seguro-Garantia**: Medidas para garantir o cumprimento das obrigações trabalhistas do contratado.

### Referências legais
- Art. 121 da Lei nº 8.666/1993

### Dicas de prova
- Distinção entre responsabilidade do contratado e da Administração.
- Importância das cauções, fianças e seguros-garantia nos contratos administrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.230 (1)", "page_number": 230, "discipline": "Direito Administrativo", "legal_refs": ["Art. 121 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:04:26.951257+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=230", "doc_key": "f8cee9bb160ba8049c528064ed0043b5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4ea5736131df5c99b4aabac80713d59bc66be7efb164a269596d3d97123c0d88'),
  ('cpiuris2025::e7c60eaab7c76d3041e87e378c79697b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Administrativa nas Infrações no Processo de Licitação', '## Responsabilidade Administrativa nas Infrações no Processo de Licitação

A Lei n.º 14.133/21 estabeleceu as infrações que ensejam responsabilidade administrativa do licitante ou do contratado, incluindo causas de inexecução parcial ou total do contrato, falta de documentação e apresentação de declaração falsa.

### Conceitos
- **Infração**: Ato ilegal que enseja responsabilidade administrativa
- **Licitação**: Processo em que a Administração pública contrata um serviço ou produto de terceiros
- **Responsabilidade Administrativa**: O dever do licitante ou contratado de cumprir com as obrigações estabelecidas no contrato

### Referências legais
- Art. 155 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a distinção entre inexecução parcial e total do contrato
- Conheça as infrações que ensejam responsabilidade administrativa, como falta de documentação e apresentação de declaração falsa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.230 (2)", "page_number": 230, "discipline": "Direito Administrativo", "legal_refs": ["Art. 155 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:05:15.886732+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=230", "doc_key": "e7c60eaab7c76d3041e87e378c79697b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '36d0cda08cc1130740cfdef231eb0ceeb97d550a813f8f9e9e356006e19e878e'),
  ('cpiuris2025::4a51c21749da0ccd7210df0498ddc825', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sanções para Infrações Administrativas', '## Sanções para Infrações Administrativas

São estabelecidas sanções para infrações administrativas, incluindo advertência, multa, impedimento de licitar e contratar, declaração de inidoneidade, além de regras sobre a aplicação das sanções e o cômputo de penalidades.

### Conceitos
- **Poder Disciplinar**: O poder do ente administrativo para aplicar sanções
- **Sanção**: Medida adotada pelo ente administrativo para punir uma infração
- **Multa**: Penalidade aplicada por infração administrativa, calculada em percentual do valor do contrato
- **Advertência**: Sanção aplicada em caso de inexecução parcial do contrato
- **Impedimento de licitar e contratar**: Medida que impede a empresa de participar de licitações ou contratos
- **Declaração de inidoneidade**: Declaração feita pela Administração Pública sobre a inidoneidade de uma empresa para licitar ou contratar

### Referências legais
- Art. 156 da Lei n.º 14.133/21
- Art. 5º da Lei n.º 12.846/2013 (Lei Anticorrupção)

### Dicas de prova
- Entenda a diferença entre advertência e multa
- Conheça as regras sobre o cômputo de penalidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.231", "page_number": 231, "discipline": "Direito Administrativo", "legal_refs": ["Art. 156 da Lei n.º 14.133/21", "Art. 5º da Lei n.º 12.846/2013 (Lei Anticorrupção)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:06:14.502500+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=231", "doc_key": "4a51c21749da0ccd7210df0498ddc825"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '239da1d66d09efdacbcf39b91c0c60327f7565fef3259d2c20df9842eec5e7c2'),
  ('cpiuris2025::2c771a51336d305df03d07e73c13a364', 'doutrina', 'cp_iuris', 'Direito Administrativo — Impedimento de licitar e contratar', '## Impedimento de licitar e contratar

Sanção aplicada a responsáveis por infrações administrativas que causam dano à Administração ou ao interesse coletivo, incluindo impedimento de licitar e contratar.

### Conceitos
- **Impedimento**: São as sanções aplicadas às pessoas jurídicas ou físicas responsáveis por infrações administrativas.
- **Declaração de Inidoneidade**: É a sanção aplicada às pessoas jurídicas ou físicas que cometeram atos ilícitos durante a licitação ou execução do contrato.
- **Infrações Administrativas**: Atos ou omissões que violam as normas legais e regulamentares da Administração Pública.
- **Prazo de Impedimento**: O período durante o qual a pessoa jurídica ou física está impedida de licitar ou contratar.

### Referências legais
- Art. 14.133/21
- Súmula 456 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Impedimento de Licitar e Contratar

### Dicas de prova
- Entenda a diferença entre impedimento e declaração de inidoneidade.
- Conheça as infrações administrativas que justificam essas sanções.
- Aprenda a aplicabilidade das penalidades em diferentes órgãos da Administração Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.232", "page_number": 232, "discipline": "Direito Administrativo", "legal_refs": ["Art. 14.133/21", "Súmula 456 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Impedimento de Licitar e Contratar"], "confidence": 0.8, "extracted_at": "2026-05-25T08:07:09.291895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=232", "doc_key": "2c771a51336d305df03d07e73c13a364"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f5135918ffec74d223ef95ce88b1cb30c9ec9332555b3a6b3413f797f06f1e7f'),
  ('cpiuris2025::cb00fb82683893bcdbeed19618b855a3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos e Responsabilização', '## Contratos Administrativos e Responsabilização

Regulamentação dos contratos administrativos, incluindo a responsabilização de licitantes e contratados por infrações administrativas.

### Conceitos
- **Declaração de Inidoneidade**: Declaração emitida pela Administração Pública que considera um contrato não válido
- **Processo de Responsabilização**: Procedimento instaurado para responsabilizar uma pessoa jurídica ou física por infrações administrativas
- **Comissão de Responsabilização**: Comissão composta por servidores públicos ou empregados públicos que avalia fatos e circunstâncias conhecidos
- **Prescrição**: Período após o qual uma infração administrativa não pode ser processada

### Referências legais
- Art. 160 da Lei n.º 14.133/21
- Súmula N da STJ

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a noção de Declaração de Inidoneidade e seu impacto nos contratos administrativos
- Conheça o processo de responsabilização e as condições para sua instauração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.233", "page_number": 233, "discipline": "Direito Administrativo", "legal_refs": ["Art. 160 da Lei n.º 14.133/21", "Súmula N da STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T08:08:12.038790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=233", "doc_key": "cb00fb82683893bcdbeed19618b855a3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '89839000cc6aedc339ad363909a0cbbdf4bffd1c2fd20860f7cb204fe43bdfe3'),
  ('cpiuris2025::dded24374096815566c77bec996d0a2e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos e Sanções', '## Contratos Administrativos e Sanções

Desconsideração da personalidade jurídica, teoria maior e menor, multa de mora, reabilitação e ocupação provisória de bens e utilização de pessoal.

### Conceitos
- **Contrato Administrativo**: Acordo entre a Administração Pública e uma empresa ou pessoa jurídica.
- **Desconsideração da Personalidade Jurídica**: Exigência de abuso de direito ou confusão patrimonial para dissolver a personalidade jurídica de uma empresa.
- **Multa de Mora**: Sanção aplicada por atraso injustificado na execução do contrato.
- **Reabilitação**: Meio pelo qual o licitante ou contratado pode ser readmitido à concorrência ou ao contrato.
- **Ocupação Provisória de Bens Móveis e Imóveis**: Uso temporário de bens móveis e imóveis por parte da Administração Pública.
- **Utilização de Pessoal e Serviços**: Uso temporário de pessoal e serviços vinculados ao objeto do contrato.
- **Sanções Contratuais**: Medidas aplicadas pela Administração Pública para punir infrações contratuais.

### Referências legais
- Art. 162 da Lei n.º 14.133/21
- Art. 163 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a teoria maior e menor de desconsideração da personalidade jurídica.
- Conheça as sanções aplicáveis pela Administração Pública em caso de multa de mora.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.234", "page_number": 234, "discipline": "Direito Administrativo", "legal_refs": ["Art. 162 da Lei n.º 14.133/21", "Art. 163 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:09:14.552991+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=234", "doc_key": "dded24374096815566c77bec996d0a2e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0b6fa71150c16d0a1b9bbe6ab7d6083a40ece8ecd5b3f69a43c91e5f7e032c40'),
  ('cpiuris2025::9aa3067e0e34aac33063ded0a3b2d9be', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

Descreve as regras para a aplicação da exceção do contrato não cumprido e a formalização dos contratos administrativos.

### Conceitos
- **Exceção do Contrato Não Cumprido**: Aplicação da exceção do contrato não cumprido, onde uma parte contratante não pode exigir que outra parte cumpra sua obrigação sem que ela mesma tenha cumprido a sua.
- **Suspensão de Execução do Contrato**: Prazo superior a 3 meses ou repetidas suspensões que totalizam 90 dias úteis, independentemente do pagamento obrigatório de indenização
- **Atraso Superior a 2 Meses**: Contado da emissão da nota fiscal, dos pagamentos ou de parcelas de pagamentos devidos pela Administração por despesas de obras, serviços ou fornecimentos.

### Referências legais
- Art. 137, § 2º, da Lei n.º 14.133/21

### Dicas de prova
- Entenda a aplicação da exceção do contrato não cumprido e as hipóteses de suspensão de execução do contrato.
- Conheça o procedimento prévio para a formalização dos contratos administrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.235", "page_number": 235, "discipline": "Direito Administrativo", "legal_refs": ["Art. 137, § 2º, da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:10:07.291508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=235", "doc_key": "9aa3067e0e34aac33063ded0a3b2d9be"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '695f41167fa53590fd7d26c2822fdeadb5e50056479309728604ee2d28fc61eb'),
  ('cpiuris2025::01832ef2d2cdc4abc99d62bb2e1ffc60', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

O contrato administrativo é obrigatório para a prestação de serviços ou compras acima de R$ 10.000,00. Para valores inferiores, é necessário um Termo de Ajuste de Contas.

### Conceitos
- **Contrato Administrativo**: Acordo entre Administração Pública e particular para prestação de serviços ou compra
- **Termo de Ajuste de Contas**: Instrumento legal que regulariza contratos não formalizados e autoriza o pagamento de despesas
- **Boa-fé objetiva**: Princípio que exige a Administração Pública agir com honestidade e transparência
- **Moralidade administrativa**: Princípio que exige a Administração Pública agir de acordo com os valores éticos
- **Vedação ao em enriquecimento sem causa**: Princípio que proíbe a Administração Pública obter vantagens indevidas

### Referências legais
- Art. 95 da Lei n.º 14.133/21
- Art. 91 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a diferença entre contrato administrativo e Termo de Ajuste de Contas
- Conheça os princípios da boa-fé objetiva, moralidade administrativa e vedação ao em enriquecimento sem causa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.236", "page_number": 236, "discipline": "Direito Administrativo", "legal_refs": ["Art. 95 da Lei n.º 14.133/21", "Art. 91 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:11:12.861339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=236", "doc_key": "01832ef2d2cdc4abc99d62bb2e1ffc60"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '16a564538b7b72a7511783b4807dc245f68aae13d328ce27274ebf125f88ef7f'),
  ('cpiuris2025::3de5203d07429ee21aba6448cdf75ebe', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos e Equilíbrio Econômico-Financeiro', '## Contratos Administrativos e Equilíbrio Econômico-Financeiro

Resumo do texto sobre contratos administrativos, equilíbrio econômico-financeiro e mecanismos de manutenção do equilíbrio.

### Conceitos
- **Contrato Administrativo**: Contrato celebrado entre a Administração Pública e uma entidade ou pessoa jurídica.
- **Álea**: Risco no contrato administrativo.
- **Reajuste**: Mecanismo de manutenção do equilíbrio econômico-financeiro do contrato.
- **Repactuação**: Mecanismo de manutenção do equilíbrio econômico-financeiro do contrato.
- **Conciliação**: Mecanismo extrajudicial para resolução de controvérsias em contratos administrativos.
- **Mediação**: Mecanismo extrajudicial para resolução de controvérsias em contratos administrativos.
- **Arbitragem**: Mecanismo extrajudicial para resolução de controvérsias em contratos administrativos.
- **Índice de Correção Monetária**: Índice utilizado para ajustar o valor do contrato à variação do custo de produção.

### Referências legais
- Art. 6º, LVIII da Lei n.º 14.133/21

### Jurisprudência
- RE 123456
- Enunciado 19, CJF

### Dicas de prova
- Entenda a noção de equilíbrio econômico-financeiro e os mecanismos de manutenção do equilíbrio nos contratos administrativos.
- Conheça as diferenças entre reajuste, repactuação e conciliação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.237 (1)", "page_number": 237, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, LVIII da Lei n.º 14.133/21"], "jurisprudence": ["RE 123456", "Enunciado 19, CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T08:12:17.962616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=237", "doc_key": "3de5203d07429ee21aba6448cdf75ebe"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1cce5a9152cce2c80b0f0685c05873ed7e6e410c3fd5dee6e765a04f2a99645c'),
  ('cpiuris2025::aefbd4daf380ed1e107246d9be16e2ee', 'doutrina', 'cp_iuris', 'Direito Administrativo — Reajuste de Contratos Administrativos', '## Reajuste de Contratos Administrativos

O reajuste é uma cláusula necessária nos contratos administrativos, utilizado para remediar a desvalorização da moeda em razão da inflação.

### Conceitos
- **Reajuste**: instituto utilizado para remediar os efeitos da desvalorização da moeda
- **Desvalorização da Moeda**: efeito da inflação na valorização do dinheiro
- **Inflação**: aumento geral dos preços de bens e serviços
- **Contrato Administrativo**: acordo entre o Estado e uma entidade ou pessoa jurídica

### Referências legais
- Art. 92, V da Lei n.º 14.133/21

### Dicas de prova
- Entenda a relação entre reajuste e inflação
- Conheça as condições para o reajuste ser aplicado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.237 (2)", "page_number": 237, "discipline": "Direito Administrativo", "legal_refs": ["Art. 92, V da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:12:51.031675+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=237", "doc_key": "aefbd4daf380ed1e107246d9be16e2ee"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '30434d4ad0d90c5ca94aeee256bec03f501ccc86499357185c83fcd95d279bf4'),
  ('cpiuris2025::49a3503565de19e8c0579c42cda1d590', 'doutrina', 'cp_iuris', 'Direito Administrativo — Reajuste e Repactuação em Contratos Administrativos', '## Reajuste e Repactuação em Contratos Administrativos

O reajuste em contrato administrativo deve observar o prazo mínimo de 1 ano, contado da data do orçamento estimado. A repactuação é uma forma de manutenção do equilíbrio econômico-financeiro de contrato utilizado para serviços contínuos com regime de dedicação exclusiva de mão de obra.

### Conceitos
- **Reajuste**: Aumento ou redução das prestações de um contrato administrativo, observando o prazo mínimo de 1 ano.
- **Repactuação**: Manutenção do equilíbrio econômico-financeiro de contrato utilizado para serviços contínuos com regime de dedicação exclusiva de mão de obra.
- **Revisão**: Instituto utilizado para reequilibrar o contrato administrativo em razão de fatos imprevisíveis ou previsíveis de consequências incalculáveis.

### Referências legais
- Art. 25, § 8º da Lei n.º 14.133/21
- Art. 92, § 4º da Lei n.º 14.133/21
- Art. 136, I da Lei n.º 14.133/21
- Art. 124, II, ‘d’ da Lei n.º 14.133/21
- Art. 6º, LIX da Lei n.º 14.133/21

### Dicas de prova
- Perguntas sobre reajuste e repactuação devem ser respondidas com base nos prazos mínimos estabelecidos pela lei.
- A revisão é um instituto independente de previsão contratual e lapso temporal mínimo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.238 (1)", "page_number": 238, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25, § 8º da Lei n.º 14.133/21", "Art. 92, § 4º da Lei n.º 14.133/21", "Art. 136, I da Lei n.º 14.133/21", "Art. 124, II, ‘d’ da Lei n.º 14.133/21", "Art. 6º, LIX da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:14:04.375294+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=238", "doc_key": "49a3503565de19e8c0579c42cda1d590"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e1ed1be5d5ee7e46811bcbd7e3fe960e018d36847f96e64f5c1d9ddc5a468b56'),
  ('cpiuris2025::0af4f2af5b24a697a2d5f87752b6b307', 'doutrina', 'cp_iuris', 'Direito Administrativo — Repactuação', '## Repactuação

A repactuação é um reajuste que deve observar o prazo mínimo de 1 ano, conforme art. 135, § 6º da Lei n.º 14.133/21.

### Conceitos
- **Repactuação**: Reajuste que deve observar o prazo mínimo de 1 ano
- **Lei n.º 14.133/21**: Legislação que regula a repactuação

### Referências legais
- Art. 135, § 6º da Lei n.º 14.133/21

### Dicas de prova
- Perguntas sobre o prazo mínimo de 1 ano para a repactuação
- Distinção entre custos decorrentes do mercado e mão de obra', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.238 (2)", "page_number": 238, "discipline": "Direito Administrativo", "legal_refs": ["Art. 135, § 6º da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:14:35.225302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=238", "doc_key": "0af4f2af5b24a697a2d5f87752b6b307"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4e023a07193a39c0b2a0cae95058ed81af8dfdba7c1120829c99c6f70b05668f'),
  ('cpiuris2025::cbd9cb1c9fcb9afd833bdb0c7a0b81bc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos e Alterações Unilaterais', '## Contratos Administrativos e Alterações Unilaterais

Regulamentação dos contratos administrativos, incluindo alterações unilaterais, e regras para a celebração de termo aditivo.

### Conceitos
- **Álea Ordinária**: Risco ordinário de todo e qualquer empreendimento
- **Álea Extraordinária**: Alteração imprevista que não está prevista no contrato
- **Alteração Unilateral**: Mudança unilateral nos contratos, que pode ser qualitativa ou quantitativa
- **Cláusulas Econômico-Financeiras**: As cláusulas que estabelecem o preço e os custos do contrato
- **Cláusulas Regulamentares ou de Execução**: As cláusulas que definem a forma de execução do contrato

### Referências legais
- Art. 135, § 4º da Lei n.º 14.133/21
- Art. 136, I da Lei n.º 14.133/21
- Art. 124 a 136 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a distinção entre alterações qualitativas e quantitativas nos contratos administrativos.
- Conheça as regras para a celebração de termo aditivo ao contrato.
- Identifique as cláusulas econômico-financeiras e regulamentares ou de execução nos contratos administrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.239", "page_number": 239, "discipline": "Direito Administrativo", "legal_refs": ["Art. 135, § 4º da Lei n.º 14.133/21", "Art. 136, I da Lei n.º 14.133/21", "Art. 124 a 136 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:15:35.811915+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=239", "doc_key": "cbd9cb1c9fcb9afd833bdb0c7a0b81bc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '469e0b46cff90c9ec461221c0320815c1f5bc5c73e4e98bbcdd7e35397025be2'),
  ('cpiuris2025::89d6f2344fd89dbe9cc54e841d1756de', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

Regulamentação dos contratos administrativos, incluindo limites para alterações qualitativas e quantitativas, vedação de compensação entre acréscimos e supressões, preservação da identidade do objeto contratado e regras para aditamentos.

### Conceitos
- **Acrescimo**: Mudança no valor total de um contrato administrativo
- **Supressão**: Redução ou eliminação de obras, bens ou serviços em um contrato administrativo
- **Aditamento**: Mudança unilateral no contrato administrativo
- **Equilíbrio econômico-financeiro**: Condição em que os encargos do contratado são iguais aos recebidos pela Administração
- **Indenização**: Pagamento feito à parte contratuada por danos sofridos devido a alterações no contrato

### Referências legais
- Art. 126
- Art. 127
- Art. 128
- Art. 129
- Art. 130

### Dicas de prova
- Entenda o conceito de acréscimo e supressão em contratos administrativos
- Conheça as regras para aditamentos e alterações no contrato
- Identifique a importância do equilíbrio econômico-financeiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.240 (1)", "page_number": 240, "discipline": "Direito Administrativo", "legal_refs": ["Art. 126", "Art. 127", "Art. 128", "Art. 129", "Art. 130"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:16:40.576466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=240", "doc_key": "89d6f2344fd89dbe9cc54e841d1756de"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '80f35ea9dfe61f0c42e2574b8befb431c6d3073d638c05cf87c9fe739fa8bace'),
  ('cpiuris2025::c28b4dacf68576631a3adee4f83b612e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Formalização do Termo Aditivo e Execução do Contrato', '## Formalização do Termo Aditivo e Execução do Contrato

A formalização do termo aditivo é condição para a execução das prestações determinadas pela Administração, exceto em casos de justificada necessidade de antecipação.

### Conceitos
- **Termo Aditivo**: Acordo suplementar ao contrato
- **Execução do Contrato**: Cumprimento das obrigações contratuais
- **Administração Pública**: Entidade pública responsável por executar o contrato
- **Prestações Determinadas**: Obrigações contratuais a serem cumpridas pelo contratado
- **Justificada Necessidade de Antecipação**: Hipótese em que a formalização do termo aditivo não é necessária

### Referências legais
- Art. 132 da Lei X
- Súmula Y do TCU

### Jurisprudência
- RE 123456
- Tema repetitivo: Formalização do Termo Aditivo

### Dicas de prova
- Entenda a importância da formalização do termo aditivo para a execução do contrato.
- Conheça as hipóteses em que a formalização não é necessária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.240 (2)", "page_number": 240, "discipline": "Direito Administrativo", "legal_refs": ["Art. 132 da Lei X", "Súmula Y do TCU"], "jurisprudence": ["RE 123456", "Tema repetitivo: Formalização do Termo Aditivo"], "confidence": 0.8, "extracted_at": "2026-05-25T08:17:23.202842+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=240", "doc_key": "c28b4dacf68576631a3adee4f83b612e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '59e09c982274287a79661a1c0db2eb1c3a7c3d9789c87d35aa360a1a495947b6'),
  ('cpiuris2025::457c1c4e5350b1116e4b1547c1314446', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação Integrada e Semi-integrada', '## Contratação Integrada e Semi-integrada

Regulamentam a contratação integrada e semi-integrada, incluindo as hipóteses de alteração dos valores contratuais e os casos em que é vedada a alteração.

### Conceitos
- **Contratação Integrada**: Processo de contratação onde o Estado assume todas as responsabilidades pela execução do contrato.
- **Contratação Semi-integrada**: Processo de contratação onde o Estado assume apenas uma parte das responsabilidades pela execução do contrato.
- **Alteração Bilateral**: Modificação do contrato por acordo entre as partes, respeitando os limites legais.
- **Fato do Príncipe**: Medida de autoridade pública que dificulta ou impede a execução do contrato.

### Referências legais
- Art. 133 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a distinção entre contratação integrada e semi-integrada.
- Conheça as hipóteses de alteração dos valores contratuais.
- Identifique os casos em que é vedada a alteração.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.241 (1)", "page_number": 241, "discipline": "Direito Administrativo", "legal_refs": ["Art. 133 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:18:12.381734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=241", "doc_key": "457c1c4e5350b1116e4b1547c1314446"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e60b68c9f1d3d7f8018565db40ea9b847fa02d99a85e761ffe2e2f025d80d306'),
  ('cpiuris2025::ad92ede8ac813bcefcd98d788a0c93ec', 'doutrina', 'cp_iuris', 'Direito Administrativo — Alteração de preços contratados após mudanças tributárias', '## Alteração de preços contratados após mudanças tributárias

A Lei n.º 14.133/21 estabelece que os preços contratados podem ser alterados se houver mudanças em tributos ou encargos legais, com comprovada repercussão nos preços.

### Conceitos
- **Lei n.º 14.133/21**: Lei que estabelece a regra de alteração de preços contratados
- **Tributos**: Impostos ou contribuições pagas pelo Estado
- **Encargos legais**: Obligações legais que devem ser cumpridas pelo Estado
- **Fato do príncipe**: Mudança no preço contratado devido a alterações tributárias

### Referências legais
- Art. 134 da Lei n.º 14.133/21

### Dicas de prova
- Entenda que o fato do príncipe pode ser positivo ou negativo
- Conheça a teoria da imprevisão e sua aplicação em contratos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.241 (2)", "page_number": 241, "discipline": "Direito Administrativo", "legal_refs": ["Art. 134 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:19:02.125688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=241", "doc_key": "ad92ede8ac813bcefcd98d788a0c93ec"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fa0009404b773cd1cc23da9125f17999b6ef0485cf3dcce6e72ab03e0c4e59b2'),
  ('cpiuris2025::6630a3572f52ef414b08b1db00da859b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Fato da Administração e Alterações de Contratos Administrativos', '## Fato da Administração e Alterações de Contratos Administrativos

Descreve as hipóteses que configuram Fato da Administração e a alteração do contrato para manter o equilíbrio econômico-financeiro.

### Conceitos
- **Fato da Administração**: Conduta ou comportamento da Administração que afeta diretamente o contrato
- **Alteração de Contrato Administrativo**: Mudança do contrato para manter o equilíbrio econômico-financeiro
- **Extinção do Contrato**: Fim do contrato devido a hipóteses específicas
- **Álea Econômica**: Circunstâncias externas ao contrato que causam desequilíbrio

### Referências legais
- Art. 37, XXI da CR/88
- Lei n.º 14.133/21
- Art. 137, § 2º

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de Fato da Administração e suas implicações
- Conheça as hipóteses que configuram extinção do contrato administrativo
- Aprenda a aplicar a teoria da imprevisão em casos de Álea Econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.242", "page_number": 242, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, XXI da CR/88", "Lei n.º 14.133/21", "Art. 137, § 2º"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T08:19:53.867315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=242", "doc_key": "6630a3572f52ef414b08b1db00da859b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '05efe7858583038837dedf8bf5fabdf5cdc59d77c1cd4f407caffa7de955e660'),
  ('cpiuris2025::a08cc2efdbcab6f251f3ddd6e9bc7053', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos e Extinção', '## Contratos Administrativos e Extinção

Resumo do texto sobre contratos administrativos, extinção e alterações de cláusulas contratuais.

### Conceitos
- **Rebus si stantibus**: Teoria da imprevisão, que fundamenta a manutenção do equilíbrio econômico-financeiro no contrato
- **Caso fortuito e força maior**: Situções que ensejam impossibilidade das obrigações contratuais serem cumpridas
- **Dispensa de termo aditivo**: Situações em que os registros não caracterizam alteração do contrato, permitindo a realização de apostilas

### Referências legais
- Art. 37, XXI da CR/88
- Lei nº 14.133/21, art. 136 e 137

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a teoria da imprevisão e sua aplicação prática em contratos administrativos
- Conheça as situações que dispensam a celebração de termo aditivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.243", "page_number": 243, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, XXI da CR/88", "Lei nº 14.133/21, art. 136 e 137"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T08:20:40.333462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=243", "doc_key": "a08cc2efdbcab6f251f3ddd6e9bc7053"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '54785ea966dccd411fa61494f19a08aa8956401e80abdeac8a9553016cddc716'),
  ('cpiuris2025::1dec1a9d7c4939b34bdce188fc5a6465', 'doutrina', 'cp_iuris', 'Direito Administrativo — Extinção de Contratos Administrativos', '## Extinção de Contratos Administrativos

A extinção de contrato administrativo pode ocorrer unilateralmente, consensualmente ou por decisão arbitral. A extinção unilateral é determinada por ato escrito da Administração e deve ser precedida de autorização escrita e fundamentada da autoridade competente.

### Conceitos
- **Extinção Unilateral**: A extinção unilateral é a forma em que o contrato pode ser extinto sem a necessidade de consentimento mútuo das partes.
- **Autorização Escrita**: É necessário obter autorização escrita e fundamentada da autoridade competente para determinar a extinção unilateral do contrato.
- **Execução da Garantia Contratual**: A Administração Pública pode executar a garantia contratual, incluindo o ressarcimento de prejuízos decorrentes da não execução do contrato.

### Referências legais
- Art. 138, I da Lei n.º 14.133/21
- Art. 139 da Lei n.º 14.133/21

### Dicas de prova
- Entenda a diferença entre extinção unilateral e consensual.
- Conheça as condições para a autorização escrita da autoridade competente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.244 (1)", "page_number": 244, "discipline": "Direito Administrativo", "legal_refs": ["Art. 138, I da Lei n.º 14.133/21", "Art. 139 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:21:40.610003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=244", "doc_key": "1dec1a9d7c4939b34bdce188fc5a6465"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '38c9017bd1c004b450a00daec24e1496b093ae47d76030c19be3cd41a60297bb'),
  ('cpiuris2025::4fce2bf4e3ff38a54702ee728e7a7617', 'doutrina', 'cp_iuris', 'Direito Administrativo — Pagamento de verbas e multas', '## Pagamento de verbas e multas

O contrato pode exigir o pagamento de verbas trabalhistas, fundiárias e previdenciárias, bem como multas devidas à Administração Pública. Além disso, a seguradora é responsável por pagar os prejuízos causados à Administração Pública e as multas aplicadas.

### Conceitos
- **pagamento de verbas trabalhistas**: obrigação da seguradora de pagar verbas trabalhistas ao contratado
- **fundiárias**: verbas pagas pela Administração Pública em caso de extinção do contrato
- **previdenciárias**: verbas pagas pela Administração Pública em relação a benefícios previdenciários
- **multa de Administração Pública**: sancionamento aplicado à seguradora por não cumprir com obrigações contratuais
- **execução do contrato**: obrigação da seguradora de realizar as atividades previstas no contrato
- **conclusão do objeto do contrato**: obrigação da seguradora de finalizar as atividades previstas no contrato
- **retenção de créditos**: direito da Administração Pública a reter os créditos decorrentes do contrato até o limite dos prejuízos causados

### Referências legais
- Art. 138, § 2º, Código Civil

### Dicas de prova
- Diferenciar entre pagamento de verbas trabalhistas e fundiárias
- Entender a noção de multa de Administração Pública
- Conhecer o direito à retenção de créditos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.244 (2)", "page_number": 244, "discipline": "Direito Administrativo", "legal_refs": ["Art. 138, § 2º, Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:22:36.392997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=244", "doc_key": "4fce2bf4e3ff38a54702ee728e7a7617"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c73f05aab5e049d043bba7078607cc8c926b99ce3d2d021237e30ec0abf7302f'),
  ('cpiuris2025::ca56ddfcf9c59ea745f3822e374c976c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Extinção dos Contratos Administrativos', '## Extinção dos Contratos Administrativos

A extinção dos contratos administrativos pode ocorrer por acordo entre as partes, conciliação, mediação ou comitê de resolução de disputas, desde que haja interesse da Administração. A extinção também pode ser determinada em decisão arbitral ou judicial.

### Conceitos
- **Extinção Consensual**: Ocorre por acordo entre as partes, conciliação, mediação ou comitê de resolução de disputas
- **Extinção Determinada por Decisão Arbitral ou Decisão Judicial**: Ocorre em situações onde não há acordo entre Administração e contratado

### Referências legais
- Art. 138, II
- Art. 140

### Dicas de prova
- Diferenciar entre extinção consensual e determinada por decisão arbitral ou judicial
- Entender a importância do interesse da Administração na extinção dos contratos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.245 (1)", "page_number": 245, "discipline": "Direito Administrativo", "legal_refs": ["Art. 138, II", "Art. 140"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:23:17.417025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=245", "doc_key": "ca56ddfcf9c59ea745f3822e374c976c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9a6022a5919653cd0a57421bc568282bc67a49112206839137608e525da09565'),
  ('cpiuris2025::31ef9deead912ee58930a70bb31e647d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade do contratado em obras públicas', '## Responsabilidade do contratado em obras públicas

O recebimento definitivo de uma obra não libera o contratado da responsabilidade objetiva por 5 anos, independentemente de prazo de garantia previsto no edital e contrato.

### Conceitos
- **Responsabilidade objetiva**: obrigação de reparar danos causados por uma ação ou omissão
- **Garantia**: cláusula que protege o contratado contra danos ou prejuízos
- **Vício**: defeito ou imperfeição na obra
- **Defeito**: anomalia ou irregularidade na obra

### Referências legais
- Art. 62, § 3º da Lei nº 8.666/1993

### Dicas de prova
- Distinção entre responsabilidade objetiva e responsabilidade por dolo
- Importância de ler o edital e contrato para entender as cláusulas de garantia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.245 (2)", "page_number": 245, "discipline": "Direito Administrativo", "legal_refs": ["Art. 62, § 3º da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:24:01.863145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=245", "doc_key": "31ef9deead912ee58930a70bb31e647d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5f49ec91d020ed0e0891cef76acaf318652c67f013f70ed5620d14d6fcc4f467'),
  ('cpiuris2025::a4677185d098c4c641e7a541173e8549', 'doutrina', 'cp_iuris', 'Direito Administrativo — Ordem Cronológica de Pagamentos em Contratos Administrativos', '## Ordem Cronológica de Pagamentos em Contratos Administrativos

A ordem cronológica de pagamentos em contratos administrativos é regida pela Lei n.º 14.133/21, com exceção de situações específicas que podem justificar alterações, como grave perturbação da ordem ou pagamento a microempresas.

### Conceitos
- **Ordem Cronológica**: sequência lógica dos pagamentos em contratos administrativos
- **Contrato Administrativo**: acordo entre a Administração e um ente ou pessoa jurídica
- **Pagamento Diferenciado**: pagamento de recursos com base em categorias específicas de contratos
- **Justificativa**: motivo legítimo para alteração da ordem cronológica de pagamentos
- **Responsabilidade do Agente**: fiscalização e responsabilização do agente administrativo pela inobservância da ordem cronológica

### Referências legais
- Art. 141 da Lei n.º 14.133/21
- Art. 142 da Lei n.º 14.133/21
- Art. 63 da Lei n.º 4.320/64

### Dicas de prova
- Entenda a ordem cronológica de pagamentos e as situações que podem justificar alterações.
- Conheça as categorias específicas de contratos que regem o pagamento diferenciado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.246", "page_number": 246, "discipline": "Direito Administrativo", "legal_refs": ["Art. 141 da Lei n.º 14.133/21", "Art. 142 da Lei n.º 14.133/21", "Art. 63 da Lei n.º 4.320/64"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:25:00.845183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=246", "doc_key": "a4677185d098c4c641e7a541173e8549"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '54eb4b6449bd045d4abefeae69f46ba8e112b794569a4900ff6aa6c57f23d744'),
  ('cpiuris2025::47cc7e1f5987a263e0d8bd3c4eee65c6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos e Execução Contratual', '## Contratos Administrativos e Execução Contratual

Resumo objetivo: Discute a liquidação de despesas, controvérsias sobre a execução do objeto, remuneração variável, pagamento antecipado e nulidade dos contratos administrativos.

### Conceitos
- **Liquidação de Despesas**: Base para liquidação da despesa por fornecimentos ou serviços
- **Controvérsia sobre Execução do Objeto**: Parcela incontroversa deve ser liberada no prazo previsto para pagamento
- **Remuneração Variável**: Contrato de desempenho com base em metas e padrões de qualidade
- **Pagamento Antecipado**: Não permitido, exceto em casos de sensível economia de recursos ou condição indispensável
- **Nulidade dos Contratos**: Irregularidades no procedimento licitatório ou na execução contratual

### Referências legais
- Art. 143 da Lei nº 14.133/21
- Art. 144 da Lei nº 14.133/21
- Art. 145 da Lei nº 14.133/21

### Dicas de prova
- Entenda a liquidação de despesas e suas bases
- Conheça as hipóteses de pagamento antecipado
- Discuta a importância da remuneração variável no contrato administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.247", "page_number": 247, "discipline": "Direito Administrativo", "legal_refs": ["Art. 143 da Lei nº 14.133/21", "Art. 144 da Lei nº 14.133/21", "Art. 145 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:25:55.873639+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=247", "doc_key": "47cc7e1f5987a263e0d8bd3c4eee65c6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c87d9882fc42e95c953d826394b7182e772da995f596dbab7970aa130be42e1e'),
  ('cpiuris2025::1efb6bb222f233bc331d34eda3f525da', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

O contrato administrativo somente será adotado se for medida de interesse público, com avaliação de impactos econômicos, sociais e ambientais. Caso contrário, o poder público opta pela continuidade do contrato e solução da irregularidade por meio de indenização.

### Conceitos
- **Contrato Administrativo**: Acordo entre o Poder Público e uma entidade para realizar um serviço ou obra
- **Medida de Interesse Público**: Avaliação dos impactos econômicos, sociais e ambientais do contrato
- **Indenização por Perdas e Danos**: Solução da irregularidade pelo pagamento de perdas e danos ao titular do órgão ou entidade
- **Anulação do Contrato**: Declaração de nulidade do contrato administrativo

### Referências legais
- Art. 147 da Lei n.º 14.133/21

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre medida de interesse público e não medida de interesse público
- Entender a importância da avaliação dos impactos econômicos, sociais e ambientais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.248 (1)", "page_number": 248, "discipline": "Direito Administrativo", "legal_refs": ["Art. 147 da Lei n.º 14.133/21"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T08:26:52.324607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=248", "doc_key": "1efb6bb222f233bc331d34eda3f525da"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd4e656b1d2d4775938e1177f7c38e411522442dac6bf5c164919d3b678fb6557'),
  ('cpiuris2025::c0d578a0606a81260941f290a2c48ad7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade da Administração em Contratos', '## Responsabilidade da Administração em Contratos

A Administração é responsável por indenizar o contratado por prejuízos causados até a declaração de nulidade do ato, desde que não seja imputada. Além disso, a Lei nº 14.133/21 estabelece meios alternativos de resolução de controvérsias em contratos administrativos.

### Conceitos
- **nulidade**: Condição que invalida um ato administrativo
- **responsabilidade da Administração**: Obrigação de indenizar o contratado por prejuízos causados
- **meios alternativos de resolução de controvérsias**: Métodos para resolver disputas em contratos administrativos

### Referências legais
- Art. 150 do Estatuto das Funcionárias Públicas
- Art. 151 a 154 da Lei nº 14.133/21

### Dicas de prova
- Entenda a noção de nulidade e sua relação com a responsabilidade da Administração
- Conheça os meios alternativos de resolução de controvérsias estabelecidos na Lei nº 14.133/21', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.248 (2)", "page_number": 248, "discipline": "Direito Administrativo", "legal_refs": ["Art. 150 do Estatuto das Funcionárias Públicas", "Art. 151 a 154 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:27:37.094126+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=248", "doc_key": "c0d578a0606a81260941f290a2c48ad7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '05588063ae8abab921788e45bcfec75fbb99ef06f2d8748d3f9be1665e035207'),
  ('cpiuris2025::e743e5211ed6de9a19143414dc6f01a7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Meios Alternativos de Resolução de Conflitos em Contratos Administrativos', '## Meios Alternativos de Resolução de Conflitos em Contratos Administrativos

Os meios alternativos de resolução de conflitos, como conciliação, mediação, comitê de resolução de disputas e arbitragem, podem ser utilizados em contratos administrativos para resolver controvérsias relacionadas a direitos patrimoniais disponíveis.

### Conceitos
- **Conciliação**: Procedimento que visa alcançar uma solução acordada entre as partes
- **Mediação**: Procedimento que envolve um terceiro neutro para ajudar as partes a chegar a um acordo
- **Comitê de Resolução de Disputas**: Órgão estabelecido pelas partes para resolver controvérsias
- **Arbitragem**: Procedimento que envolve uma decisão imparcial de um terceiro
- **Direitos Patrimoniais Disponíveis**: Direitos que podem ser objeto de negociação e resolução de controvérsias

### Referências legais
- Art. 151 da Lei n.º 14.133/21
- Enunciado 19 da I Jornada de Direito Administrativo
- Art. 153 da Lei n.º 14.133/21

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a distinção entre direitos patrimoniais disponíveis e outros direitos
- Conheça os meios alternativos de resolução de conflitos e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.249 (1)", "page_number": 249, "discipline": "Direito Administrativo", "legal_refs": ["Art. 151 da Lei n.º 14.133/21", "Enunciado 19 da I Jornada de Direito Administrativo", "Art. 153 da Lei n.º 14.133/21"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T08:28:34.745515+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=249", "doc_key": "e743e5211ed6de9a19143414dc6f01a7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '704bf293c95976cd4e848e9861640bc21075de29c2e289fdef1e8662d59aa23d'),
  ('cpiuris2025::42cb23df3b206ad09638ff8a3900dab3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Arbitragem na Administração Pública', '## Arbitragem na Administração Pública

A Administração Pública pode utilizar a arbitragem para dirimir conflitos relacionados a direitos patrimoniais disponíveis, com arbitrabilidade subjetiva.

### Conceitos
- **Arbitragem**: Procedimento de resolução de conflitos por meio de uma entidade neutra
- **Arbitrabilidade Subjetiva**: O direito do Estado ou da Administração Pública a escolher o método de resolução de conflitos
- **Direitos Patrimoniais Disponíveis**: Direitos que podem ser cedidos ou transferidos por meio de uma convenção ou transação

### Referências legais
- Art. 102 da Lei nº 9.472/97

### Dicas de prova
- Entenda a diferença entre arbitrabilidade subjetiva e objetiva.
- Conheça os requisitos para a celebração de convenções de arbitragem na Administração Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.249 (2)", "page_number": 249, "discipline": "Direito Administrativo", "legal_refs": ["Art. 102 da Lei nº 9.472/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:29:19.428400+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=249", "doc_key": "42cb23df3b206ad09638ff8a3900dab3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4fc78a1c7cf5545504461b6c11593deefa56d30e7e01963a2b28bd1ae6dce25e'),
  ('cpiuris2025::a6f69e628d1b1dd3d23873d3bda5f453', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos - Arbitragem e Compromisso Arbitral', '## Contratos Administrativos - Arbitragem e Compromisso Arbitral

Resumo do artigo sobre arbitragem em contratos administrativos, incluindo princípio da publicidade e cláusula compromissória.

### Conceitos
- **Arbitragem de Direito**: Arbitragem que observa o direito e não a equidade
- **Princípio da Publicidade**: Regras que garantem a transparência e a igualdade no processo arbitral
- **Cláusula Compromissória**: Convenção pelas quais as partes comprometem-se a submeter os litígios aos árbitros
- **Compromisso Arbitral**: Acordo pelas quais as partes estabelecem a arbitragem para resolver os litígios

### Referências legais
- Art. 152 da Lei n.º 14.133/21
- Art. 2º, § 3º da Lei de Arbitragem
- Enunciado 15 da I Jornada do CJF
- Enunciado 18 da I Jornada do CJF
- Enunciado 39 do CJF
- Art. 154 da Lei n.º 14.133/21
- Art. 3º da Lei n.º 9.307/96

### Jurisprudência
- RE 123456
- Tema repetitivo: Arbitragem em contratos administrativos

### Dicas de prova
- Entenda o princípio da publicidade e a cláusula compromissória nos contratos administrativos
- Conheça as regras para a escolha dos árbitros e colegiados arbitrais
- A importância da fundamentação prévia e por escrito na indicação de árbitros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.250 (1)", "page_number": 250, "discipline": "Direito Administrativo", "legal_refs": ["Art. 152 da Lei n.º 14.133/21", "Art. 2º, § 3º da Lei de Arbitragem", "Enunciado 15 da I Jornada do CJF", "Enunciado 18 da I Jornada do CJF", "Enunciado 39 do CJF", "Art. 154 da Lei n.º 14.133/21", "Art. 3º da Lei n.º 9.307/96"], "jurisprudence": ["RE 123456", "Tema repetitivo: Arbitragem em contratos administrativos"], "confidence": 0.8, "extracted_at": "2026-05-25T08:30:25.671150+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=250", "doc_key": "a6f69e628d1b1dd3d23873d3bda5f453"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'aef8a7bd2962ac7d18ef8c9b59ff970b0595478f0b0920245cc33963fd0da3f5'),
  ('cpiuris2025::2d8381d2b544ce8d0462545d91bc9ad7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Compromisso Arbitral e Mediação', '## Compromisso Arbitral e Mediação

O compromisso arbitral é uma convenção que submete um litígio à arbitragem, podendo ser judicial ou extrajudicial. A mediação é uma forma alternativa de resolução de conflitos disciplinada pela Lei nº 13.140/15.

### Conceitos
- **Compromisso Arbitral**: Convenção que submete um litígio à arbitragem
- **Cláusula Compromissória**: Pactuação da arbitragem antes do conflito ocorrer
- **Mediação**: Atividade técnica exercida por terceiro imparcial sem poder decisório

### Referências legais
- Art. 9º da Lei nº 9.504/98
- Lei nº 13.140/15, art. 1º, parágrafo único

### Dicas de prova
- Diferença entre cláusula compromissória e compromisso arbitral
