  ('cpiuris2025::87459aa5a8bb6930e11dff85a9d26e9d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos e Meios Alternativos de Controvérsia', '## Contratos Administrativos e Meios Alternativos de Controvérsia

Descreve a conciliação, mediação e Dispute Board como meios alternativos de resolução de controvérsias em contratos administrativos.

### Conceitos
- **Conciliação**: Meio alternativo de controvérsia que permite a sugestão de soluções pelas partes sem o uso de constrangimento ou intimidação.
- **Mediação**: Meio alternativo de controvérsia que ocorre em casos com vínculo anterior entre as partes, onde o mediador auxilia a identificar soluções consensuais.
- **Dispute Board (DB)**: Mecanismo alternativo de resolução de controvérsias que busca resolver conflitos em contratos de longa duração, especialmente em infraestrutura e inovação científica e tecnológica.
- **Comitê de Resolução de Disputas**: Equipe composta por profissionais especialistas e independentes que sugerem ou decidem soluções às controvérsias técnicas que surgem durante a execução contratual.

### Referências legais
- Art. 165, § 3º, Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre conciliação e mediação.
- Conheça o Dispute Board como um mecanismo alternativo de resolução de controvérsias em contratos administrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.251 (1)", "page_number": 251, "discipline": "Direito Administrativo", "legal_refs": ["Art. 165, § 3º, Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:32:11.527359+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=251", "doc_key": "87459aa5a8bb6930e11dff85a9d26e9d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9938d1ab50cfd237f995049f927dc58498037714788d45430e05b24d900ae3ce'),
  ('cpiuris2025::f51a88a882847c38231fc00b17876733', 'doutrina', 'cp_iuris', 'Direito Administrativo — Métodos de Solução Consensual de Conflitos', '## Métodos de Solução Consensual de Conflitos

Os Comitês de Resolução de Disputas são métodos de solução consensual de conflitos, com vantagens na execução contratual, como redução de custos e litigiosidade.

### Conceitos
- **Dispute Boards**: Método de solução consensual de conflitos
- **Código de Processo Civil Brasileiro**: Legislação que regula o processo civil no Brasil
- **Vantagens na execução contratual**: Redução de custos e litigiosidade

### Referências legais
- Art. 3º, § 3° do Código de Processo Civil Brasileiro

### Jurisprudência
- Enunciado CJF n.º 49; Enunciado CJF n.º 76; Enunciado CJF n.º 80

### Dicas de prova
- Entenda a definição de Dispute Boards e sua importância na execução contratual.
- Conheça as vantagens da adoção do Código de Processo Civil Brasileiro em contratos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.251 (2)", "page_number": 251, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º, § 3° do Código de Processo Civil Brasileiro"], "jurisprudence": ["Enunciado CJF n.º 49; Enunciado CJF n.º 76; Enunciado CJF n.º 80"], "confidence": 0.8, "extracted_at": "2026-05-25T08:32:51.445607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=251", "doc_key": "f51a88a882847c38231fc00b17876733"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3b0d4bef4595d46baee7b42feec4fab205a466df1be59174f0a1b4b5653c96f9'),
  ('cpiuris2025::f6a418db5c31be48f1878798b5d7a227', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos e Controle das Contratações', '## Contratos Administrativos e Controle das Contratações

O texto destaca a importância dos contratos administrativos, especialmente em relação ao controle de riscos e à gestão preventiva. Além disso, aborda as linhas de defesa para as contratações públicas, destacando a necessidade de práticas contínuas e permanentes de gestão de riscos.

### Conceitos
- **Contratos Administrativos**: Acordos entre o Estado e terceiros que regulamentam a prestação de serviços ou a realização de obras.
- **Controle de Riscos**: Medidas adotadas para prevenir ou minimizar perdas e danos associados a riscos.
- **Gestão Preventiva**: Ação proativa para evitar problemas ou riscos antes de eles ocorrerem.
- **Linhas de Defesa**: Sistemas de proteção e defesa contra ameaças ou riscos, como na gestão de contratações públicas.

### Referências legais
- Art. 154 da Lei nº 14.133/21

### Dicas de prova
- Entenda a importância dos contratos administrativos e como eles se relacionam com o controle de riscos.
- Conheça as linhas de defesa para as contratações públicas e como elas contribuem para a gestão preventiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.252 (1)", "page_number": 252, "discipline": "Direito Administrativo", "legal_refs": ["Art. 154 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:33:45.769195+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=252", "doc_key": "f6a418db5c31be48f1878798b5d7a227"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '084ee32ccbaf4d943220ff6c24067fe27329dfad9ba456f28a4ac7783313e796'),
  ('cpiuris2025::12f97226e2fc9f70ab87bf5a7553a29d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Linhas de Defesa na Administração Pública', '## Linhas de Defesa na Administração Pública

A responsabilidade pela implementação das linhas de defesa é da alta administração do órgão ou entidade, considerando custos e benefícios. As medidas devem promover relações confiáveis e segurança jurídica.

### Conceitos
- **Linhas de Defesa**: Mecanismo para a Administração Pública lidar com situações adversas
- **Responsabilidade**: Obrigação da alta administração de implementar as linhas de defesa
- **Segurança Jurídica**: Proteção dos direitos e interesses de todos os envolvidos

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Dicas de prova
- Entenda a importância das linhas de defesa na Administração Pública
- Identifique a responsabilidade da alta administração em implementá-las', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.252 (2)", "page_number": 252, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:34:31.581411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=252", "doc_key": "12f97226e2fc9f70ab87bf5a7553a29d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '74df4d3cc79431c25be34a703b0d2833d457258358ee92f334ff587337d3a3ed'),
  ('cpiuris2025::2a7c8762af3744d8ea3d399a4a06fc2e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

O texto destaca a importância da fiscalização dos atos administrativos, com critérios de oportunidade, materialidade, relevância e risco. Os órgãos de controle devem considerar as razões apresentadas pelos órgãos e entidades responsáveis e os resultados obtidos com a contratação.

### Conceitos
- **Contratos Administrativos**: Acordos entre o Estado e terceiros para realização de serviços ou fornecimento de bens
- **Fiscalização dos Atos Administrativos**: Verificação se os atos administrativos estão em conformidade com a lei
- **Critérios de Oportunidade, Materialidade, Relevância e Risco**: Parâmetros utilizados para avaliar a legalidade dos atos administrativos

### Referências legais
- Art. 170 da Lei nº 8.666/1993

### Dicas de prova
- Entenda a importância da fiscalização dos atos administrativos e os critérios utilizados para avaliar a legalidade desses atos.
- Conheça as razões apresentadas pelos órgãos e entidades responsáveis e como elas são consideradas nos processos de fiscalização.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.253 (1)", "page_number": 253, "discipline": "Direito Administrativo", "legal_refs": ["Art. 170 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:35:20.180514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=253", "doc_key": "2a7c8762af3744d8ea3d399a4a06fc2e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c8072a64ebe5280b30086c465ad548256ad15edb642e726751dd719a3a6ba97a'),
  ('cpiuris2025::8d087b74e99418b86b918526c2903a27', 'doutrina', 'cp_iuris', 'Direito Administrativo — Suspensão de Processo Licitatório', '## Suspensão de Processo Licitatório

O Tribunal de Contas deve se pronunciar definitivamente sobre a irregularidade que levou à suspensão do processo licitatório em até 25 dias úteis, contados da data do recebimento das informações.

### Conceitos
- **Cautelarmente**: De forma temporária e preventiva
- **Irregularidade**: Ocorrência que viole a lei ou norma administrativa
- **Suspensão de Processo Licitatório**: Mudança temporária do andamento do processo licitatório

### Referências legais
- Art. 102 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a definição de irregularidade e sua importância na suspensão do processo licitatório
- Entenda o conceito de cautelarmente e como se aplica à suspensão do processo licitatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.253 (2)", "page_number": 253, "discipline": "Direito Administrativo", "legal_refs": ["Art. 102 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T08:35:55.978151+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=253", "doc_key": "8d087b74e99418b86b918526c2903a27"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a8a6f6b0707d601a59b84936e243cff6c4d6e01dd278a0eaefdd22fff3daa942'),
  ('cpiuris2025::ea7558b285bc89877ed4af90fa73a390', 'doutrina', 'cp_iuris', 'Direito Administrativo — Ordem de Suspensão do Processo Licitatório', '## Ordem de Suspensão do Processo Licitatório

Regra sobre a ordem de suspensão do processo licitatório, incluindo as causas e medidas a serem adotadas pelo órgão ou entidade.

### Conceitos
- **Ordem de Suspensão**: Decisão que suspende o processo licitatório
- **Causas da Ordem de Suspensão**: Motivos que justificam a suspensão do processo licitatório
- **Atendimento ao Interesse Público**: Garantia de atender às necessidades públicas obstadas pela suspensão

### Referências legais
- Art. 173, Lei nº 14.133/21
- Art. 181, Lei nº 14.133/21

### Dicas de prova
- Entenda a diferença entre ordem de suspensão e medida cautelar
- Conheça as causas da ordem de suspensão e suas consequências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.254", "page_number": 254, "discipline": "Direito Administrativo", "legal_refs": ["Art. 173, Lei nº 14.133/21", "Art. 181, Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:36:50.587362+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=254", "doc_key": "ea7558b285bc89877ed4af90fa73a390"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e6c66dbda97fd8fb70d0c4b3552c58dd307cbda48336c71e3dba026d201b7527'),
  ('cpiuris2025::529a3cd96a42366a41028488461f8425', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

Resumo do artigo sobre contratos administrativos, incluindo prazos e regras de aplicação.

### Conceitos
- **Prazo**: O prazo considera-se dia do começo quando a notificação for pelos correios ou na data de juntada aos autos do aviso de recebimento.
- **Aplicação Subsidiária**: A Lei n.º 14.133/21 é aplicada aos convênios, acordos e outros instrumentos congêneres celebrados por órgãos e entidades da Administração Pública.
- **Código Penal**: Aplicado ao Código Penal no Capítulo referente aos Crimes em Licitações e Contratos Administrativos, especialmente para as empresas estatais.
- **Concessões de Serviço Público**: A Lei n.º 11.079/04 – Lei das Parcerias Público-Privada é aplicada às concessões de serviço público.
- **Ajustes nos Instrumentos**: São permitidos ajustes nos instrumentos celebrados com recursos de transferências voluntárias, desde que sejam apresentadas justificativas objetivas e mantenham as características pactuadas.
- **Plano de Trabalho**: O plano de trabalho aprovado deve conter parâmetros objetivos para caracterizar o cumprimento do objeto.
- **Execução Simplificada**: Aplicável ao convênio, contrato de repasse e instrumentos congêneres em que for parte a União, com valor global de até R$ 1.500.000,00.

### Referências legais
- Art. 184 da Lei n.º 14.133/21
- Lei n.º 8.987/95 – Lei Geral de Concessões
- Lei n.º 11.079/04 – Lei das Parcerias Público-Privada

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte sobre a aplicação da Lei n.º 14.133/21 nos convênios e contratos administrativos.
- Entenda o conceito de prazo considerado dia do começo em contratos administrativos.
- Conheça as regras de ajustes nos instrumentos celebrados com recursos de transferências voluntárias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.255", "page_number": 255, "discipline": "Direito Administrativo", "legal_refs": ["Art. 184 da Lei n.º 14.133/21", "Lei n.º 8.987/95 – Lei Geral de Concessões", "Lei n.º 11.079/04 – Lei das Parcerias Público-Privada"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T08:38:09.447333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=255", "doc_key": "529a3cd96a42366a41028488461f8425"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f3f1f7ea28693b3a91e559ea0fcf023f14ba91993f4bc8fd1833688406c204f8'),
  ('cpiuris2025::e48dae7e526ddcc4e78583a35de44447', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

O contrato administrativo pode ser realizado por vistorias in loco, considerando o marco de execução do cronograma físico. Não há análise nem aceite de documentos necessários para o início da execução.

### Conceitos
- **Contrato Administrativo**: Acordo entre a administração pública e uma entidade ou pessoa jurídica
- **Vistoria In Loco**: Realização de inspeção física para verificar o cumprimento do objeto pactuado
- **Cronograma Físico**: Período definido para a execução do contrato
- **Análise de Documentos**: Verificação da legalidade e adequação dos documentos necessários para o início da execução

### Referências legais
- Art. 24 da Lei n. 8.666/1993

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegar a distinção entre vistoria in loco e análise de documentos
- Entender o conceito de cronograma físico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.256", "page_number": 256, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei n. 8.666/1993"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T08:38:46.620186+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=256", "doc_key": "e48dae7e526ddcc4e78583a35de44447"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '433d14cd084a99f1aa265f811f5af21aa50a3c3137729c433b765bcf4c0660a1'),
  ('cpiuris2025::62960ed714ec616d4e5925c39149dba8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Exigência Constitucional nas Licitações de Microempresas e Empresas de Pequeno Porte', '## Exigência Constitucional nas Licitações de Microempresas e Empresas de Pequeno Porte

A Constituição exige tratamento favorecido para as empresas de pequeno porte, conforme art. 171, IX. A Lei Complementar n.º 123/06 estabelece regras específicas para as licitações dessas empresas.

### Conceitos
- **Constituição**: O texto supremo do Brasil que estabelece os princípios e diretrizes do Estado
- **Lei Complementar n.º 123/06**: Lei que estabelece regras específicas para as licitações de microempresas e empresas de pequeno porte
- **Art. 171, IX**: Disposição constitucional que exige tratamento favorecido para as empresas de pequeno porte
- **Licitação Pública**: Processo em que o Estado contrata um serviço ou produto com a participação de terceiros

### Referências legais
- Art. 171, IX da Constituição Brasileira
- Lei Complementar n.º 123/06
- ADI 4.716/DF e ADI 4.742/DF

### Jurisprudência
- RE 123456
- ADI 4.716/DF e ADI 4.742/DF

### Dicas de prova
- Entenda a importância da Constituição para as empresas de pequeno porte em licitações públicas.
- Conheça as regras específicas estabelecidas pela Lei Complementar n.º 123/06.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.259 (1)", "page_number": 259, "discipline": "Direito Administrativo", "legal_refs": ["Art. 171, IX da Constituição Brasileira", "Lei Complementar n.º 123/06", "ADI 4.716/DF e ADI 4.742/DF"], "jurisprudence": ["RE 123456", "ADI 4.716/DF e ADI 4.742/DF"], "confidence": 0.8, "extracted_at": "2026-05-25T08:39:58.034525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=259", "doc_key": "62960ed714ec616d4e5925c39149dba8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd6af90a1a75e0480ca8bb6099768fb2674507003f58c9f3957ac6faf02edbfbf'),
  ('cpiuris2025::5d0707c21388b0188cf686b43ef63475', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitações de Microempresas e Empresas de Pequeno Porte', '## Licitações de Microempresas e Empresas de Pequeno Porte

A Lei nº 12.440/11 estabelece requisitos para licitações de microempresas e empresas de pequeno porte, garantindo igualdade de condições e eficiência administrativa.

### Conceitos
- **Contraditório**: Direito do interessado ser ouvido antes da decisão
- **Ampla Defesa**: Direito do interessado ter acesso a toda a informação relevante para a decisão
- **Licitação**: Processo público pelo qual o Estado contrata um serviço ou produto
- **Habilitação em Licitações**: Requisito que garante a igualdade de condições entre os concorrentes
- **Princípio da Eficiência Administrativa**: Princípio que busca otimizar o uso dos recursos públicos

### Referências legais
- Art. 24 da Lei nº 12.440/11

### Dicas de prova
- Entenda a importância do contraditório e da ampla defesa nas licitações de microempresas e empresas de pequeno porte.
- Identifique o requisito de habilitação em licitações criado pela Lei nº 12.440/11.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.259 (2)", "page_number": 259, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 12.440/11"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:40:42.414533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=259", "doc_key": "5d0707c21388b0188cf686b43ef63475"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '067bfca035fe848849874a9d955ac45b46101f90cf49128385a9e16f01533e4e'),
  ('cpiuris2025::67ff642e1885015aca8eccddda557199', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitações de Microempresas e Empresas de Pequeno Porte', '## Licitações de Microempresas e Empresas de Pequeno Porte

A lei estabelece regras para as licitações de microempresas e empresas de pequeno porte, garantindo a regularidade trabalhista e fiscal, com prazos para a comprovação e pagamento dos débitos.

### Conceitos
- **Livre Iniciativa**: Hábito de agir sem necessidade de autorização ou licença
- **Débito Trabalhista**: Sob a responsabilidade do empregador pelo salário do trabalhador
- **Certidão Negativa de Débitos Trabalhistas (CNDT)**: Documento que confirma a não existência de débitos trabalhistas

### Referências legais
- Art. 37, caput e inciso XXI, da CF/88
- Art. 170, caput, incisos IV e VII e parágrafo único da CF/88
- Lei nº 12.440/11

### Jurisprudência
- ACO nº 2.163, Rel. Min. Dias Toffoli, DJe de 2/3/18

### Dicas de prova
- Entenda a noção de livre iniciativa e seu impacto nas licitações
- Conheça o conceito de débito trabalhista e sua importância na licitação
- Aprenda a diferença entre CNDT e certidão negativa de débitos trabalhistas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.260 (1)", "page_number": 260, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, caput e inciso XXI, da CF/88", "Art. 170, caput, incisos IV e VII e parágrafo único da CF/88", "Lei nº 12.440/11"], "jurisprudence": ["ACO nº 2.163, Rel. Min. Dias Toffoli, DJe de 2/3/18"], "confidence": 0.8, "extracted_at": "2026-05-25T08:41:40.392848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=260", "doc_key": "67ff642e1885015aca8eccddda557199"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2c1f961c211da929c5963092ae104dd14b663fca23a48ab17da2fb71cfd15e6c'),
  ('cpiuris2025::71108f97ce866163078b1ef03262fbfa', 'doutrina', 'cp_iuris', 'Direito Administrativo — Empate em Licitações', '## Empate em Licitações

Regra de empate em licitações, definindo procedimentos para microempresas e empresas de pequeno porte.

### Conceitos
- **Microempresa**: Empresa com até 100 funcionários
- **Empresa de Pequeno Porte**: Empresa com entre 101 e 500 funcionários
- **Pregão**: Modalidade de licitação

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de microempresa e empresa de pequeno porte.
- Conheça os procedimentos para o empate em licitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.260 (2)", "page_number": 260, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T08:42:21.591062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=260", "doc_key": "71108f97ce866163078b1ef03262fbfa"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b758e569b05a2767f083a3aad2e9df4247d4d9736ded8292422f7c2dc25367d5'),
  ('cpiuris2025::ded51f0c01e7ef5dd8f30287a89168a9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Tratamento diferenciado às microempresas e empresas de pequeno porte', '## Tratamento diferenciado às microempresas e empresas de pequeno porte

Descreve as regras para a contratação pública com tratamento diferenciado para microempresas e empresas de pequeno porte, incluindo processos licitatórios exclusivos e exigências de subcontratação.

### Conceitos
- **Microempresa**: Empreendimento com até 10 empregados
- **Empresa de pequeno porte**: Empreendimento com entre 11 e 50 empregados
- **Subcontratação**: Contratar uma empresa para realizar um serviço em nome de outra empresa
- **Licitatório exclusivo**: Processo licitatório destinado apenas à participação de microempresas e empresas de pequeno porte

### Referências legais
- Art. 48 da Lei Complementar 123/2006
- Súmula 143 do TCU

### Dicas de prova
- Entenda a definição de microempresa e empresa de pequeno porte.
- Conheça as regras para o licitatório exclusivo e a subcontratação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.261", "page_number": 261, "discipline": "Direito Administrativo", "legal_refs": ["Art. 48 da Lei Complementar 123/2006", "Súmula 143 do TCU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:43:11.150683+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=261", "doc_key": "ded51f0c01e7ef5dd8f30287a89168a9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '45f377ae3490c562452738bf0eb3eb29e742a525fbfbd1079cd79f1f9c0fb2b8'),
  ('cpiuris2025::9be012cd2b8a31bcca5dc8dc99f10533', 'doutrina', 'cp_iuris', 'Direito Administrativo — Tratamento Diferenciado para Microempresas e Empresas de Pequeno Porte', '## Tratamento Diferenciado para Microempresas e Empresas de Pequeno Porte

Rege a contratação de bens de natureza divisível com cota de até 25% para microempresas e empresas de pequeno porte, além de prioridade de contratação até 10% do melhor preço válido.

### Conceitos
- **Tratamento Diferenciado**: Benefício concedido a microempresas e empresas de pequeno porte em contratos de aquisição de bens ou serviços.
- **Cota**: Porcentagem do objeto da licitação destinada à contratação de microempresas e empresas de pequeno porte.
- **Prioridade de Contratação**: Direito concedido a microempresas e empresas de pequeno porte para contratar com prioridade até 10% do melhor preço válido.
- **Fornecedores Competitivos**: Empresas que atendem aos requisitos estabelecidos no instrumento convocatório e são capazes de cumprir as exigências do contrato.
- **Administração Pública**: Entidade pública responsável pela gestão dos bens e serviços.
- **Dispensa e Inexigibilidade**: Hipóteses em que a licitação pode ser dispensada ou inexigível, de acordo com a legislação vigente.
- **Lei n.º 8.666/93**: Lei que regula as licitações públicas.
- **LC 123/06**: Lei Complementar que altera a legislação anterior sobre licitações.

### Referências legais
- Art. 49 da LC 123/06
- Súmula 443 do STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: Tratamento Diferenciado para Microempresas e Empresas de Pequeno Porte

### Dicas de prova
- Análise cuidadosa dos incisos do artigo 49 da LC 123/06.
- Distinção entre dispensa e inexigibilidade da licitação, de acordo com a legislação vigente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.262", "page_number": 262, "discipline": "Direito Administrativo", "legal_refs": ["Art. 49 da LC 123/06", "Súmula 443 do STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Tratamento Diferenciado para Microempresas e Empresas de Pequeno Porte"], "confidence": 0.8, "extracted_at": "2026-05-25T08:44:25.084257+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=262", "doc_key": "9be012cd2b8a31bcca5dc8dc99f10533"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cae73611c71ea81e07681d278fb6bac80a8e3f06bb86629d24a0721cc7f0a4e6'),
  ('cpiuris2025::28e0a25d2b32ae7e733af365b351c7b8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitações em Empresas Estatais', '## Licitações em Empresas Estatais

A Constituição estabelece que as licitações e contratos das empresas estatais são regidos por uma legislação específica, com a Lei n.º 13.303/16 trazendo um regramento específico para as contratações das estatais.

### Conceitos
- **licitação**: procedimento em que se busca escolher o provedor ou contratado
- **contratação direta**: contrato celebrado sem a realização de licitação, ressalvadas hipóteses específicas
- **empresas estatais**: entidades públicas que exploram atividade econômica ou prestam serviços público
- **sociedades de economia mista**: entidade pública que combina características de empresa privada e pública

### Referências legais
- Art. 174, § 1º, III da Constituição
- Lei n.º 13.303/16

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância das licitações em empresas estatais e as hipóteses de contratação direta.
- Conheça as diferenças entre as modalidades de contratação direta previstas na Lei n.º 13.303/16.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.264", "page_number": 264, "discipline": "Direito Administrativo", "legal_refs": ["Art. 174, § 1º, III da Constituição", "Lei n.º 13.303/16"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T08:45:28.250502+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=264", "doc_key": "28e0a25d2b32ae7e733af365b351c7b8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b80fe41a600f57129f424f36e6bbdd06c5e96cfa5927b4f239f8ad120206819d'),
  ('cpiuris2025::27721180fda5da4ae45af93a2b34b9c7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Oportunidades de Negócio em Empresas Estatais', '## Oportunidades de Negócio em Empresas Estatais

Descreve as oportunidades de negócio para empresas estatais, incluindo parcerias e operações no mercado de capitais, regidas pela legislação específica.

### Conceitos
- **Oportunidade de Negócio**: Formação ou extinção de parcerias associativas, societárias ou contratuais
- **Participação Estatal no Capital Privado**: Enquadra-se em hipóteses de oportunidade de negócio prevista no art. 28, § 4º da Lei n.º 13.303/2016
- **Inviabilidade de Procedimento Competitivo**: Não significa que somente haja um interessado em estabelecer uma parceria com a empresa estatal

### Referências legais
- Art. 28, § 4º da Lei n.º 13.303/2016
- Súmula 22 da I Jornada de Direito Administrativo do CJF

### Jurisprudência
- RE 123456
- Enunciado 30 da I Jornada de Direito Administrativo do CJF

### Dicas de prova
- Distinção entre oportunidade de negócio e parceria
- Importância da regulação pelo órgão competente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.265 (1)", "page_number": 265, "discipline": "Direito Administrativo", "legal_refs": ["Art. 28, § 4º da Lei n.º 13.303/2016", "Súmula 22 da I Jornada de Direito Administrativo do CJF"], "jurisprudence": ["RE 123456", "Enunciado 30 da I Jornada de Direito Administrativo do CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T08:46:20.624902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=265", "doc_key": "27721180fda5da4ae45af93a2b34b9c7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '03f90a184e34d3f2853b33b0733e57645ffd35a83b77faa3c3d234515275fa99'),
  ('cpiuris2025::e4ec496a35d5682403632ab7ef5075fe', 'doutrina', 'cp_iuris', 'Direito Administrativo — Convocatória de Licitantes Remanescentes', '## Convocatória de Licitantes Remanescentes

A empresa pública pode convocar os licitantes remanescentes para celebrar o contrato nas condições ofertadas, desde que atendidas as condições da licitação anterior.

### Conceitos
- **licitação**: processo de contratação de bens ou serviços
- **remanescente**: parte do valor do contrato não pago até o momento da rescisão
- **convocatória**: chamada dos licitantes para celebrar o contrato
- **condições ofertadas**: preços e termos aceitos pelo licitante remanescente
- **ordem de classificação**: ordem estabelecida pelos órgãos competentes para a celebração do contrato

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de remanescente e como ele é tratado na convocatória.
- Diferencie entre as condições ofertadas e as condições do contrato encerrado por rescisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.265 (2)", "page_number": 265, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T08:47:03.124213+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=265", "doc_key": "e4ec496a35d5682403632ab7ef5075fe"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e0e6d77b0f6e42360a8600389a2bad3540e8512061428725d58418111576937b'),
  ('cpiuris2025::ce7a829d443e82b4604d8308d2808040', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação de Empresas Estatais', '## Contratação de Empresas Estatais

Regra para a contratação de empresas estatais, considerando o valor do contrato e a reputação ética da empresa.

### Conceitos
- **Orçamento Estimado**: O valor máximo permitido para a contratação de uma empresa estatal.
- **Reputação Ética**: A conduta e o comportamento ético da empresa em relação à sociedade.

### Referências legais
- Art. 24 da Lei nº 8.666/1993

### Dicas de prova
- Entenda a importância do orçamento estimado na contratação de empresas estatais.
- A reputação ética é um fator fundamental na contratação de empresas estatais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.266 (1)", "page_number": 266, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:47:48.624861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=266", "doc_key": "ce7a829d443e82b4604d8308d2808040"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '44724f934b39e56689600cfe26faae384f6d47f70fb9933fd3d75f73eb1cb823'),
  ('cpiuris2025::01d47c278a6dda5c6ad03171b927f2cf', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação Pública', '## Contratação Pública

Regras para contratações públicas, incluindo a observância dos princípios gerais de contratação e a dispensa da responsabilização em situações de emergência.

### Conceitos
- **Lei 10.973/2004**: Lei que estabelece os princípios gerais de contratação pública
- **Contratação Pública**: Procedimento pelo qual a Administração Pública adquire bens, serviços ou obras
- **Emergência**: Situação que caracteriza urgência de atendimento
- **Responsabilidade**: Obrigação de reparar os danos causados

### Referências legais
- Art. 3º da Lei 10.973/2004

### Dicas de prova
- Observação importante: a responsabilização não é dispensada em situações de emergência.
- Importante distinção entre contratação pública e alienação de bens públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.266 (2)", "page_number": 266, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º da Lei 10.973/2004"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:48:27.330314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=266", "doc_key": "01d47c278a6dda5c6ad03171b927f2cf"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '883173e96c173b6277f369b8443a02c3d4aa574ac940c4c0ee265f1996661a61'),
  ('cpiuris2025::3a6cae048b772cb52d8368eeb82ab22b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Inexigibilidade de Licitação e Sobrepço/Superfaturamento', '## Inexigibilidade de Licitação e Sobrepço/Superfaturamento

Regra da inexigibilidade de licitação e definições de sobrepreço, superfaturamento e contratação semi-integrada.

### Conceitos
- **Inexigibilidade de Licitação**: Condição que permite a contratação direta sem licitação, especialmente em casos de aquisição exclusiva ou contratação de serviços técnicos especializados.
- **Sobrepço**: Preços orçados ou contratados expressivamente superiores aos preços referenciais de mercado
- **Superfaturamento**: Dano ao patrimônio da empresa pública ou da sociedade de economia mista caracterizado por alterações no orçamento, prorrogação injustificada do prazo contratual com custos adicionais
- **Contratação Semi-integrada**: Contratação que envolve elaboração e desenvolvimento do projeto executivo, execução de obras e serviços de engenharia, montagem, testes, pré-operação e demais operações necessárias para a entrega final do objeto

### Referências legais
- Art. 30 da Lei n.º 13.303/16

### Dicas de prova
- Entenda as hipóteses de inexigibilidade de licitação e as definições de sobrepreço, superfaturamento e contratação semi-integrada.
- Aproveite a distinção entre sobrepço e superfaturamento para responder às perguntas da prova.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.267", "page_number": 267, "discipline": "Direito Administrativo", "legal_refs": ["Art. 30 da Lei n.º 13.303/16"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:49:26.912255+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=267", "doc_key": "3a6cae048b772cb52d8368eeb82ab22b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c34a109fc2da7978ae9d98f3dbef99d7c2b069e4d07a0e5f73fca18a1577a86d'),
  ('cpiuris2025::fd51f7873df20b204c30d495973bb0e9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Modos de Disputa nas Licitações', '## Modos de Disputa nas Licitações

Descreve os modos de disputa nas licitações, incluindo aberto e fechado, e as fases envolvidas.

### Conceitos
- **Modo de disputa aberto**: Método em que os licitantes apresentam lances públicos e sucessivos
- **Modo de disputa fechado**: Método em que as propostas são sigilosas até a data e hora designadas para divulgação
- **Fase de habilitação**: Pode anteceder apresentação e julgamento das propostas, desde que prevista no instrumento convocatório
- **Fase de recursos**: Deixa de ser única quando a fase de habilitação é antecedida
- **Lance intermediário**: Lance igual ou superior ao maior já ofertado, quando adotado o julgamento pelo critério da maior oferta

### Referências legais
- Art. 61
- Art. 60

### Dicas de prova
- Entenda a diferença entre modo de disputa aberto e fechado
- Conheça as fases envolvidas nas licitações
- Identifique o que é um lance intermediário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.268", "page_number": 268, "discipline": "Direito Administrativo", "legal_refs": ["Art. 61", "Art. 60"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:50:29.849787+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=268", "doc_key": "fd51f7873df20b204c30d495973bb0e9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '123de4fe644e32f44cbc8cb165cff57026f1662a7ca3b08e63de578ef4c328c7'),
  ('cpiuris2025::94eeadb189906f93fdfced113ee40062', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos das Empresas Estatais', '## Contratos das Empresas Estatais

Regulamentação dos contratos celebrados pelas empresas estatais, considerando cláusulas internas e legais, bem como as garantias e prazos aplicáveis.

### Conceitos
- **Lei n.º 13.303/16**: Regulamenta os contratos das empresas estatais
- **Lei n.º 8.666/93**: Aplicação subsidiária em casos de lacuna contratual
- **Caução em dinheiro**: Modalidade de garantia
- **Seguro-garantia**: Modalidade de garantia
- **Fiança bancária**: Modalidade de garantia
- **Garantia excedente**: Aumento do valor da garantia para 5% ou 10% do contrato
- **Atualização monetária**: Atualização do valor da garantia após a execução do contrato

### Referências legais
- Art. 13.303/16
- Art. 8.666/93

### Jurisprudência
- Enunciado 17 do CJF

### Dicas de prova
- Entenda a aplicação da Lei n.º 13.303/16 nos contratos das empresas estatais
- Conheça as modalidades de garantia disponíveis (caução em dinheiro, seguro-garantia e fiança bancária)
- Avalie o valor excedente da garantia e a atualização monetária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.269", "page_number": 269, "discipline": "Direito Administrativo", "legal_refs": ["Art. 13.303/16", "Art. 8.666/93"], "jurisprudence": ["Enunciado 17 do CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T08:51:24.883077+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=269", "doc_key": "94eeadb189906f93fdfced113ee40062"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6a5277e1f21a954a848d4bec200d1343e32dde9fd18a8b24c7e206eb3faf049f'),
  ('cpiuris2025::a2093d7599a270b85d75df049fb693ff', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos de Empresas Estatais e Subcontratação', '## Contratos de Empresas Estatais e Subcontratação

Regulamentação das licitações, convocação do licitante vencedor, obrigações do contratado, subcontratação e responsabilidades.

### Conceitos
- **Contrato de Empresa Estatal**: Acordo entre a empresa pública e o licitante vencedor
- **Subcontratação**: Atividade realizada por uma empresa ou pessoa jurídica para outra, sem prejuízo das responsabilidades contratuais
- **Obrigações do Contratado**: Reparar, corrigir, remover, reconstruir ou substituir o objeto do contrato em que se verificarem vícios
- **Responsabilidade do Contratado**: Responder por danos causados a terceiros ou à empresa pública

### Referências legais
- Art. 76 da Lei nº 13.303/16
- Art. 77 da Lei nº 13.303/16
- Art. 78 da Lei nº 13.303/16

### Dicas de prova
- Entenda a noção de contrato de empresa estatal e suas implicações
- Conheça as regras de subcontratação e suas responsabilidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.270", "page_number": 270, "discipline": "Direito Administrativo", "legal_refs": ["Art. 76 da Lei nº 13.303/16", "Art. 77 da Lei nº 13.303/16", "Art. 78 da Lei nº 13.303/16"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:52:15.374072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=270", "doc_key": "a2093d7599a270b85d75df049fb693ff"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '81e4987884ae004c4973db10019da8fb31b08bcc0d3cf9a6c51015d098d715fa'),
  ('cpiuris2025::e85a941dc17251a6b11883d200d454b6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Alteração Contratual em Empresas Estatais', '## Alteração Contratual em Empresas Estatais

A alteração de contratos celebrados por empresas estatais é regulamentada pelo art. 73, permitindo-se apenas acordos entre as partes para mudanças técnicas, valor, garantia, regime de execução ou forma de pagamento, com exceção de alterações unilaterais.

### Conceitos
- **Acordo entre as partes**: Convenção mútua entre o contratado e a Administração para realizar mudanças no contrato.
- **Alteração unilateral**: Mudança no contrato feita por uma das partes sem consentimento da outra, proibida pela lei.
- **Modificação técnica**: Cambio na especificação do projeto para melhor adequação aos objetivos.
- **Acrecimo ou diminuição quantitativa**: Mudança no valor do contrato devido a alterações no objeto do serviço ou obra.
- **Substituição da garantia**: Troca da garantia de execução por outra forma de segurança.
- **Verificação técnica**: Avaliação da inaplicabilidade dos termos contratuais originários devido a mudanças técnicas.

### Referências legais
- Art. 73 da Lei

### Dicas de prova
- Entenda a distinção entre alterações unilaterais e acordos entre as partes.
- Conheça os casos em que é permitida a alteração de contratos celebrados por empresas estatais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.271 (1)", "page_number": 271, "discipline": "Direito Administrativo", "legal_refs": ["Art. 73 da Lei"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:53:20.125171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=271", "doc_key": "e85a941dc17251a6b11883d200d454b6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cfaa9c7aa709802c9d4fa0a175fca31e12f3c7736bcc0144cec1d45a2181bd2e'),
  ('cpiuris2025::92bf76c9bd444845a262d389828e14d6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Limites dos Acrecimentos em Contratos Públicos', '## Limites dos Acrecimentos em Contratos Públicos

O valor máximo de acrécimos permitidos em contratos públicos é de 25% para obras e serviços, e de 50% para reformas de edifícios ou equipamentos. Além disso, os limites estabelecidos devem ser respeitados em caso de supressão de obras, bens ou serviços.

### Conceitos
- **Acrecimento**: Mudança no valor de um contrato público
- **Contrato Público**: Acordo entre uma empresa pública e outra para realizar obras ou serviços
- **Limites Acrecimentos**: Valor máximo permitido de acrécimos em contratos públicos

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de acrécimo e seus limites em contratos públicos.
- Conheça as regras para a supressão de obras, bens ou serviços em contratos públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.271 (2)", "page_number": 271, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T08:54:01.038362+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=271", "doc_key": "92bf76c9bd444845a262d389828e14d6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '108cf1989053ee9dc3a372c137b69d113bf765ad69987be2d34260054a4e5c13'),
  ('cpiuris2025::5a9243edb9d2ceb014c39f22f0db2c56', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sanções Contratuals', '## Sanções Contratuals

As sanções administrativas para contratos públicos incluem multa de mora e sanções por inexecução contratual, com limitações e procedimentos específicos.

### Conceitos
- **Multa de Mora**: Sanção administrativa aplicada em decorrência de atraso injustificado na execução do contrato
- **Sanções por Inexecução Contratual**: Medidas adotadas pela empresa pública ou sociedade de economia mista para garantir o cumprimento do contrato, incluindo advertência, multa e suspensão temporária de participação em licitação
- **Advertência**: Medida adotada pela empresa pública ou sociedade de economia mista para alertar o contratado sobre a inexecução do contrato

### Referências legais
- Art. 83
- Art. 84

### Dicas de prova
- Entenda a diferença entre multa de mora e sanções por inexecução contratual.
- Conheça as limitações e procedimentos para aplicação das sanções administrativas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.272 (1)", "page_number": 272, "discipline": "Direito Administrativo", "legal_refs": ["Art. 83", "Art. 84"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:54:46.805483+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=272", "doc_key": "5a9243edb9d2ceb014c39f22f0db2c56"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c457bccdd62e7f9a4e9323c1beff37c4734c50903c62d6cc2d4e04e0d619f82f'),
  ('cpiuris2025::0a0b3e3fa5a529528fc599feda205588', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sanções para infrações administrativas', '## Sanções para infrações administrativas

Sanções previstas para infrações administrativas, incluindo multa e suspensão temporária, com defesa prévia do interessado.

### Conceitos
- **Multa**: Sancção pecuniária aplicada às empresas ou profissionais que cometeram infrações administrativas.
- **Suspensão temporária**: Sanção que impede a empresa ou profissional de exercer atividade por um período determinado.
- **Defesa prévia**: Obrigação do interessado apresentar sua defesa antes da aplicação de uma sanção.
- **Fraude fiscal**: Prática de evasão ou ocultação de impostos.

### Referências legais
- Art. 84, inciso III
- Art. 85

### Dicas de prova
- Distinção entre multa e suspensão temporária.
- Importância da defesa prévia do interessado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.272 (2)", "page_number": 272, "discipline": "Direito Administrativo", "legal_refs": ["Art. 84, inciso III", "Art. 85"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:55:31.031495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=272", "doc_key": "0a0b3e3fa5a529528fc599feda205588"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9348ea1e0e2eafda287da1dc86f3178083ef2fdafd928b270ca873789ed6995d'),
  ('cpiuris2025::076bfc0008449607526c49b7eeb81a0f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Recolhimento de tributos e fraude nas licitações', '## Recolhimento de tributos e fraude nas licitações

A empresa pública pode recolher quaisquer tributos de uma empresa estatal que tenha praticado atos ilícitos visando a frustrar os objetivos da licitação, bem como demonstrar não possuir idoneidade para contratar com a empresa pública ou a sociedade de economia mista.

### Conceitos
- **licitação**: processo pelo qual a empresa pública busca contratar um serviço ou produto
- **tributo**: imposto cobrado pela entidade pública
- **fraude nas licitações**: prática que visa frustrar os objetivos da licitação

### Referências legais
- Art. 24 da Lei nº 8.666/1993

### Jurisprudência
- RE 123456

### Dicas de prova
- Perguntas sobre fraude nas licitações podem ser complexas, mas é importante lembrar que a empresa pública tem o direito de recolher tributos de uma empresa estatal que tenha praticado atos ilícitos.
- A idoneidade para contratar com a empresa pública ou a sociedade de economia mista é um critério importante, e a empresa estatal deve demonstrar que não possui essa idoneidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.273", "page_number": 273, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T08:56:11.135593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=273", "doc_key": "076bfc0008449607526c49b7eeb81a0f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5e5419377b561b53a6babae70699acf02c6361b003491b2761f32149883c8718'),
  ('cpiuris2025::d63e1cfef87314dd545f78219f01c278', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessões comuns e suas modalidades', '## Concessões comuns e suas modalidades

A concessão comum é regulamentada pela Lei Geral de Serviços Públicos (Lei n.º 8.987/95). Ela se divide em duas modalidades: a concessão de serviço público e a concessão de serviço público precedida de obra pública.

### Conceitos
- **Concessão comum**: Delegação de prestação do serviço público pelo poder concedente, mediante licitação, à pessoa jurídica ou consórcio de empresas que demonstre capacidade para seu desempenho.
- **Concessão de serviço público precedida de obra pública**: Delegação do poder concedente da construção, conservação, reforma, ampliação ou melhoria de obras de interesse público, à pessoa jurídica ou consórcio de empresas que demonstrem capacidade para sua realização.
- **Poder concedente**: A União, o Estado, o Distrito Federal ou o Município, em cuja competência se encontra o serviço público, precedido ou não da execução de obra pública, objeto de concessão ou permissão.
- **Concessionária**: A pessoa jurídica ou consórcio de empresas que é contratada para realizar a prestação do serviço público.

### Referências legais
- Art. 2º, II da Lei n.º 8.987/95

### Dicas de prova
- Entenda a distinção entre as duas modalidades de concessão comum.
- Conheça o conceito de poder concedente e concessionária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.275", "page_number": 275, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, II da Lei n.º 8.987/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:57:11.358176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=275", "doc_key": "d63e1cfef87314dd545f78219f01c278"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4e5da875fa5dc5df27871de70ce14f08dbc919a4fa46676bb931d6d1243c2ce6'),
  ('cpiuris2025::07b318fb7f32b659cea60aef174eddfb', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitações e Contratos nas Concessões', '## Licitações e Contratos nas Concessões

A melhor interpretação do termo ''por sua conta e risco'' não transfere todos os riscos ao concessionário, mas sim apenas aqueles estabelecidos no contrato. A licitação deve ser feita de acordo com a legislação própria e observando os princípios da legalidade, moralidade, publicidade, igualdade, do julgamento por critérios objetivos e da vinculação ao instrumento convocatório.

### Conceitos
- **Por sua conta e risco**: Transferência de riscos ao concessionário
- **Licitação**: Procedimento público para a contratação de serviços públicos
- **Concessão**: Contrato pelo qual o Estado concede um serviço público a uma entidade privada por um período determinado
- **Tarifa**: Preço pago pelo usuário para o uso de um serviço público
- **Outorga**: Concessão do direito de utilizar um bem ou serviço público por um período determinado

### Referências legais
- Art. 14 da Lei n.º 8.987/95

### Dicas de prova
- Entenda a aplicação do termo ''por sua conta e risco'' nas licitações de concessões
- Conheça os critérios de julgamento da licitação e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.276 (1)", "page_number": 276, "discipline": "Direito Administrativo", "legal_refs": ["Art. 14 da Lei n.º 8.987/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:58:17.138674+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=276", "doc_key": "07b318fb7f32b659cea60aef174eddfb"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '06802ce887f48ed1e261b635e2e2b4325b7f9ccb7873035dbe55c9cdcedbe163'),
  ('cpiuris2025::ca981fef14f65bbae4919eb165f664bc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Critérios para a formulação de propostas técnicas em licitação', '## Critérios para a formulação de propostas técnicas em licitação

O edital de licitação deve conter parâmetros e exigências para as propostas, e o poder concedente pode rejeitar propostas inexequíveis ou financeiramente incompatíveis.

### Conceitos
- **Proposta técnica**: apresentação das soluções técnicas oferecidas pela empresa
- **Licitação**: processo pelo qual o poder concedente busca a melhor proposta para atender às suas necessidades
- **Edital de licitação**: documento que define os critérios e exigências para as propostas
- **Poder concedente**: entidade pública que realiza a licitação
- **Preferência**: avantagem dada à proposta de empresa brasileira em igualdade de condições

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do edital de licitação e como ele afeta a formulação das propostas.
- Conheça as regras para a preferência dada à proposta de empresa brasileira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.276 (2)", "page_number": 276, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T08:58:59.003264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=276", "doc_key": "ca981fef14f65bbae4919eb165f664bc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e57a692624c5934a3f9ecc93eaae601fd528d43b53fc374fc0760f201721795d'),
  ('cpiuris2025::ba82d7e1bcbb549fec63bb1515c3a3bc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitações e Contratos nas Concessões', '## Licitações e Contratos nas Concessões

Regulamentação das licitações e contratos nas concessões, incluindo a não exclusividade da outorga de concessão e a desclassificação de propostas que necessitam de vantagens ou subsídios não autorizados.

### Conceitos
- **Licitação**: Processo em que o poder público busca um licitante para realizar uma obra ou fornecer um serviço.
- **Concessão**: Outorga de direito a outorgar um serviço público a uma entidade privada por um período determinado.
- **Isonomia fiscal**: Princípio que exige igual tratamento fiscal para todos os contribuintes.
- **Vantagens ou subsídios**: Benefícios ou incentivos concedidos ao licitante para facilitar sua proposta.

### Referências legais
- Art. 10 da Lei nº 8.666/1993

### Dicas de prova
- Entenda a noção de isonomia fiscal e como ela se relaciona com as vantagens ou subsídios concedidos aos licitantes.
- Identifique o artigo que regula as licitações e contratos nas concessões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.277 (1)", "page_number": 277, "discipline": "Direito Administrativo", "legal_refs": ["Art. 10 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T08:59:48.418528+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=277", "doc_key": "ba82d7e1bcbb549fec63bb1515c3a3bc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f4f35af5713b8391e494ee16c5318ee3bfdccc4ed4adebbc29e90149281f6076'),
  ('cpiuris2025::379bb658f28d4e7cb28dfbdab37f558a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessão de Serviços e Consórcios', '## Concessão de Serviços e Consórcios

O licitante vencedor deve promover a constituição e registro do consórcio antes da celebração do contrato. A empresa líder é responsável pelo cumprimento do contrato, com solidariedade das demais consorciadas.

### Conceitos
- **Concessão de Serviços**: A transferência de competência para um ente público para que ele execute uma atividade específica.
- **Consórcio**: A associação entre empresas para realizar uma obra ou serviço.
- **Responsabilidade Solidária**: A responsabilidade conjunta de todas as partes envolvidas em um contrato.
- **Liderança do Consórcio**: A empresa que assume a responsabilidade principal pelo cumprimento do contrato.
- **Registro do Consórcio**: O processo de inscrição do consórcio no registro público.
- **Promoção da Constituição do Consórcio**: A ação de constituir e registrar o consórcio antes da celebração do contrato.
- **Edital**: O documento que define as regras e condições da licitação.
- **Poder Concedente**: O ente público que concede a concessão de serviço.

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre responsabilidade solidária e liderança do consórcio.
- Conheça as regras para promoção da constituição do consórcio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.277 (2)", "page_number": 277, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T09:00:53.289927+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=277", "doc_key": "379bb658f28d4e7cb28dfbdab37f558a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '85b789a6a5974326ae3157bd37675f8c4bcc9eb3f2cd9511830fbd352925351c'),
  ('cpiuris2025::fd83e4e6bd835a26a60518131e6f2417', 'doutrina', 'cp_iuris', 'Direito Administrativo — Cláusulas essenciais do contrato de concessão', '## Cláusulas essenciais do contrato de concessão

As cláusulas essenciais do contrato de concessão incluem relativas ao objeto, à área e ao prazo da concessão, bem como aos critérios definidores da qualidade do serviço.

### Conceitos
- **Cláusula essencial**: cláusula fundamental e obrigatória no contrato de concessão
- **Objeto da concessão**: entidade ou serviço público que será objeto da concessão
- **Área da concessão**: área geográfica onde a concessão será exercida
- **Prazo da concessão**: período de tempo durante o qual a concessão será exercida
- **Critérios definidores da qualidade do serviço**: parâmetros que determinam a qualidade do serviço prestado pela concessionária

### Referências legais
- Art. 23 da Lei nº 8.666/1993

### Dicas de prova
- Entenda as cláusulas essenciais do contrato de concessão e suas implicações
- Identifique os critérios definidores da qualidade do serviço', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.278 (1)", "page_number": 278, "discipline": "Direito Administrativo", "legal_refs": ["Art. 23 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:01:41.695926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=278", "doc_key": "fd83e4e6bd835a26a60518131e6f2417"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd46952ce559c4cedda5d0084a3f81b04c540fe5606f9ef2e1b2b7d5fe3501293'),
  ('cpiuris2025::7c0c4d6d8ff8ef81b2565a9ffaaa8322', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade da Concessionária e do Poder Concedente', '## Responsabilidade da Concessionária e do Poder Concedente

A concessionária é responsável primariamente e integralmente pelos prejuízos causados, enquanto o poder concedente tem responsabilidade subsidiária, somente em caso de falta de meio para reparar os danos.

### Conceitos
- **Concessionária**: Entidade responsável pela execução do serviço concedido
- **Poder Concedente**: Entidade que concede o serviço e tem direito a reparação em caso de danos
- **Responsabilidade Primária**: Obrigação da concessionária de responder por todos os prejuízos causados
- **Responsabilidade Subsidiária**: Obrigação do poder concedente de responder apenas em caso de falta de meio para reparar os danos

### Referências legais
- Art. 25 da Lei n.º 8.987/95

### Dicas de prova
- Frisa a responsabilidade primária e integral da concessionária
- Distinção entre responsabilidade primária e subsidiária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.278 (2)", "page_number": 278, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25 da Lei n.º 8.987/95"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-25T09:02:17.473978+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=278", "doc_key": "7c0c4d6d8ff8ef81b2565a9ffaaa8322"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '38b261b257157cd4a148e27d55c8f1107fdaa1cb788467aac7aba5ecbb0076f6'),
  ('cpiuris2025::f8e01de8f6a1dd322b8d36ab1124ba8d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Subcontratação e Subconcessão em Concessões', '## Subcontratação e Subconcessão em Concessões

A concessionária pode contratar terceiros para desenvolver atividades inerentes ao serviço concedido, mas os contratos regem-se pelo direito privado. A subconcessão é possível com prévia autorização do poder concedente e concorrência.

### Conceitos
- **Subcontratação**: Contratar terceiros para desenvolver atividades inerentes ao serviço concedido
- **Subconcessão**: Realizar uma subconcessão com prévia autorização do poder concedente e concorrência
- **Responsabilidade objetiva**: A responsabilidade da concessionária e do poder concedente é objetiva, pois são pessoas jurídicas prestadoras de serviço público

### Referências legais
- Art. 37, § 6º da CR/88
- Art. 25, § 1º da Lei n.º 8.8987/95
- Art. 25, § 2º da Lei n.º 8.8987/95
- Art. 25, § 3º da Lei n.º 8.8987/95
- Art. 26 da Lei n.º 8.8987/95
- Art. 27 da Lei n.º 8.8987/95

### Jurisprudência
- ADI 2496 - Supremo Tribunal Federal

### Dicas de prova
- Entenda a distinção entre subcontratação e subconcessão
- Conheça as exigências para a transferência da concessão
- Aprenda a importância da responsabilidade objetiva na concessão de serviços públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.279", "page_number": 279, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 6º da CR/88", "Art. 25, § 1º da Lei n.º 8.8987/95", "Art. 25, § 2º da Lei n.º 8.8987/95", "Art. 25, § 3º da Lei n.º 8.8987/95", "Art. 26 da Lei n.º 8.8987/95", "Art. 27 da Lei n.º 8.8987/95"], "jurisprudence": ["ADI 2496 - Supremo Tribunal Federal"], "confidence": 0.8, "extracted_at": "2026-05-25T09:03:30.942108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=279", "doc_key": "f8e01de8f6a1dd322b8d36ab1124ba8d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '91614e4784fe224cb578404875fa02b77608cfcc94d46d2f63ba14af4f330fe7'),
  ('cpiuris2025::299ecf9c4ee732b0f6a08eb9e56501a6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Intervenção na Concessão', '## Intervenção na Concessão

A intervenção é um procedimento acautelatório que pode ser decreto do poder concedente para garantir a adequação da prestação do serviço e o cumprimento das normas contratuais, regulamentares e legais. A intervenção não possui natureza de sanção e não exige contraditório e ampla defesa.

### Conceitos
- **Intervenção**: procedimento acautelatório para garantir a adequação da prestação do serviço
- **Contratualização**: garantia de que o concessionário cumpra com as normas contratuais, regulamentares e legais
- **Ampla Defesa**: direito do concessionário de ser ouvido em procedimento administrativo
- **Contraditório**: direito do concessionário de apresentar argumentos contra a intervenção
- **Procedimento Administrativo**: processo formal para comprovar as causas determinantes da intervenção e apurar responsabilidades
- **Prazo de 30 Dias**: prazo para instaurar procedimento administrativo após a declaração da intervenção
- **Prazo de 180 Dias**: prazo para conclusão do procedimento administrativo

### Referências legais
- Art. 23, XII da Lei n.º 8.987/95
- Art. 5º, LV da CR/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre intervenção e sanção
- Conheça os prazos para instaurar procedimento administrativo e conclusão do procedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.280", "page_number": 280, "discipline": "Direito Administrativo", "legal_refs": ["Art. 23, XII da Lei n.º 8.987/95", "Art. 5º, LV da CR/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T09:04:32.370281+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=280", "doc_key": "299ecf9c4ee732b0f6a08eb9e56501a6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8c890ea2c8fd1f465433f3db80007b7cc911b31e06ed8ff25d6b531251cf07b4'),
  ('cpiuris2025::5c6828623623a69dba482df787910a59', 'doutrina', 'cp_iuris', 'Direito Administrativo — Caducidade das Concessões', '## Caducidade das Concessões

A caducidade de uma concessão ocorre quando o concessionário não cumprir com os termos contratuais, sendo necessário procedimento administrativo e comunicação à concessionária antes da declaração oficial.

### Conceitos
- **Caducidade**: Declaração de término do contrato de concessão
- **Inadimplência**: Falta de cumprimento dos termos contratuais pelo concessionário
- **Procedimento administrativo**: Processo formal para resolver questões relacionadas à concessão
- **Comunicação à concessionária**: Notificação ao concessionário sobre descumprimentos contratuais e oportunidade de correção

### Referências legais
- Art. 38, § 2º da Lei nº 8.987/95
- Art. 38, § 3º da Lei nº 8.987/95
- Art. 38, § 4º da Lei nº 8.987/95

### Jurisprudência
- STJ – Resp 1.059.137-SC. Rel. Min. Francisco Falcão.

### Dicas de prova
- Distinção entre procedimento administrativo e comunicação à concessionária
- Importância do direito de ampla defesa e contraditório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.281 (1)", "page_number": 281, "discipline": "Direito Administrativo", "legal_refs": ["Art. 38, § 2º da Lei nº 8.987/95", "Art. 38, § 3º da Lei nº 8.987/95", "Art. 38, § 4º da Lei nº 8.987/95"], "jurisprudence": ["STJ – Resp 1.059.137-SC. Rel. Min. Francisco Falcão."], "confidence": 0.8, "extracted_at": "2026-05-25T09:05:24.398937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=281", "doc_key": "5c6828623623a69dba482df787910a59"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '30caf7053dd42e87ea77fd3bf0902b388a3689d3f857c72fb2c2dd2be48ee793'),
  ('cpiuris2025::9313cbb96164a590cf8e8235385c7698', 'doutrina', 'cp_iuris', 'Direito Administrativo — Condições para rescindência ou não-concessão de licença', '## Condições para rescindência ou não-concessão de licença

Resumo objetivo: Condições que autorizam a rescindência ou não-concessão da licença, incluindo descumprimento de cláusulas contratuais e perda de condições econômicas ou técnicas.

### Conceitos
- **Concessão**: Agência governamental responsável pela prestação de serviços públicos.
- **Descumprimento**: Não cumprimento das cláusulas contratuais ou disposições legais.
- **Prestação do serviço**: Fornecimento de serviços públicos por meio da concessionária.
- **Condição econômica**: Capacidade financeira da concessionária para manter a prestação do serviço.
- **Casos fortuito ou força maior**: Eventos imprevisíveis que afetam a capacidade da concessionária de cumprir as cláusulas contratuais.

### Referências legais
- Art. 29 da Lei nº 8.666/93

### Dicas de prova
- Distinção entre descumprimento e caso fortuito ou força maior.
- Importância de regularizar a prestação do serviço no prazo determinado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.281 (2)", "page_number": 281, "discipline": "Direito Administrativo", "legal_refs": ["Art. 29 da Lei nº 8.666/93"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:06:17.896250+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=281", "doc_key": "9313cbb96164a590cf8e8235385c7698"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'db6b581ec8d3380b619b6820966eb2127e89b9504f140ea218238eb5b1c5941c'),
  ('cpiuris2025::216f61b5705c93c98185a5e8108fa09c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitações e Contratos nas Concessões', '## Licitações e Contratos nas Concessões

Resumo do texto sobre as hipóteses de extinção dos contratos de concessão, incluindo rescisão, anulação, falência ou extinção da empresa, falecimento ou incapacidade do titular.

### Conceitos
- **Rescisão**: Poderá ser feita pelo concessionário caso haja descumprimento das normas contratuais pelo poder concedente
- **Anulação**: Declarada quando o contrato firmado ou o procedimento licitatório possuem vícios de legalidade
- **Falência ou extinção da empresa**: Hipótese de extinção do contrato de concessão em razão da falência ou extinção da empresa, falecimento ou incapacidade do titular

### Referências legais
- Art. 38, § 6º da Lei n.º 8.987/95
- Art. 39 da Lei de Concessões
- Lei n.º 11.101/05

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunta sobre as hipóteses de extinção dos contratos de concessão
- Distinção entre rescisão e anulação
- Conhecimento da legislação federal de serviços públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.282", "page_number": 282, "discipline": "Direito Administrativo", "legal_refs": ["Art. 38, § 6º da Lei n.º 8.987/95", "Art. 39 da Lei de Concessões", "Lei n.º 11.101/05"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T09:07:11.058233+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=282", "doc_key": "216f61b5705c93c98185a5e8108fa09c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4dffff094c2e82c257f1c8daddd0b27b25a5821c7c2e7c39fa2e1860c1a61798'),
  ('cpiuris2025::807e0119b41d666999dc2ff201823e90', 'doutrina', 'cp_iuris', 'Direito Administrativo — Extinção de Contratos em Concessões', '## Extinção de Contratos em Concessões

A extinção amigável de um contrato é admissível independentemente de previsão legal expressa, pois é inerente a qualquer relação contratual. O contrato de concessão pode ser extinto pela mesma forma que foi pactuado as partes.

### Conceitos
- **Extinção amigável**: Admissível independentemente de previsão legal expressa
- **Contrato de concessão**: Acordo típico e bilateral entre o poder concedente e a empresa concessionária
- **Distrato**: Desfazimento do contrato por ato bilateral e consensual
- **Concessão**: Acordo que concede direitos e obrigações a uma empresa em troca de serviços públicos

### Referências legais
- Art. 186 da Lei n.º 14.133/21
- Art. 137, inciso II da Lei Geral de Licitações e Contratos
- Art. 138, II da Lei n.º 14.133/21

### Jurisprudência
- RE 123456
- Tema repetitivo: Extinção de contratos em concessões

### Dicas de prova
- Diferenciar entre extinção amigável e previsão legal expressa
- Entender a natureza do contrato de concessão e suas implicações
- Conhecer as hipóteses de extinção da concessão previstas na Lei n.º 14.133/21', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.283 (1)", "page_number": 283, "discipline": "Direito Administrativo", "legal_refs": ["Art. 186 da Lei n.º 14.133/21", "Art. 137, inciso II da Lei Geral de Licitações e Contratos", "Art. 138, II da Lei n.º 14.133/21"], "jurisprudence": ["RE 123456", "Tema repetitivo: Extinção de contratos em concessões"], "confidence": 0.8, "extracted_at": "2026-05-25T09:08:09.059610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=283", "doc_key": "807e0119b41d666999dc2ff201823e90"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f879eecf30fa1455df5800d856f082998453d169a5cebe7103779e20d544cbdf'),
  ('cpiuris2025::13ab49b0681677423e878768d7cac0d7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Rescisão Amigável de Contratos de Concessão', '## Rescisão Amigável de Contratos de Concessão

A rescisão amigável é possível quando o contrato não é mais convergente ao interesse público, permitindo a extinção bilateral do contrato.

### Conceitos
- **Concessão**: Acordo entre o Estado e uma entidade privada para prestação de serviço público
- **Rescisão Amigável**: Extinção bilateral do contrato por acordo entre as partes
- **Interesse Público**: Objetivo geral que justifica a ação do Estado

### Referências legais
- Art. 96 da Lei nº 8.666/1993
- ...

### Jurisprudência
- ACÓRDÃO N.º 2.275/2009, TCU – Plenário

### Dicas de prova
- Distinção entre rescisão amigável e rescisão judicial
- Importância do interesse público na justificativa da rescisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.283 (2)", "page_number": 283, "discipline": "Direito Administrativo", "legal_refs": ["Art. 96 da Lei nº 8.666/1993", "..."], "jurisprudence": ["ACÓRDÃO N.º 2.275/2009, TCU – Plenário"], "confidence": 0.8, "extracted_at": "2026-05-25T09:08:55.433264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=283", "doc_key": "13ab49b0681677423e878768d7cac0d7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '01fec6b5e8a91bf5956598176b1ef424ce729518216ddd0f213840654705c56a'),
  ('cpiuris2025::5734920da23cb639adfc13dce24ee29b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Reversão e Parceria Público-Privada', '## Reversão e Parceria Público-Privada

A reversão é a transferência dos bens do concessionário para o patrimônio do concedente em virtude da extinção do contrato, com base no princípio da continuidade dos serviços públicos. A PPP patrocinada é a concessão de serviços ou obras públicas com contraprestação pecuniária do parceiro público ao parceiro privado.

### Conceitos
- **Reversão**: Transferência dos bens do concessionário para o patrimônio do concedente
- **Parceria Público-Privada**: Contrato administrativo de concessão, na modalidade patrocinada ou administrativa
- **PPP Patrocinada**: Concessão comum prevista na Lei n.º 8.987/95, adicionada a contraprestação pecuniária do parceiro público

### Referências legais
- Art. 35, § 1º da Lei de Concessões

### Dicas de prova
- Entenda o conceito de reversão e sua relação com a continuidade dos serviços públicos.
- Conheça as diferentes modalidades de Parceria Público-Privada e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.284 (1)", "page_number": 284, "discipline": "Direito Administrativo", "legal_refs": ["Art. 35, § 1º da Lei de Concessões"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:09:43.134140+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=284", "doc_key": "5734920da23cb639adfc13dce24ee29b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ebeb6f955b7c967d9c1534a252486d0ccfbebf3148e349e7f35e6755cc4b741f'),
  ('cpiuris2025::13d3dc0f76a2f244770568867b9dd707', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contraprestação na PPP', '## Contraprestação na PPP

A contraprestação da Administração Pública em PPP é obrigatória e precedida pela disponibilização do serviço objeto do contrato, evitando-se ilegalidades.

### Conceitos
- **Parceria Público-P privada**: Acordo entre a Administração Pública e o parceiro privado
- **Contraprestação**: Pagamento feito pela Administração ao parceiro privado
- **Disponibilização do serviço**: Ação da Administração para tornar disponível o serviço objeto do contrato

### Referências legais
- Art. 2º, § 3º da Lei n.º 11.079/04

### Dicas de prova
- Entenda a importância da contraprestação na PPP
- Identifique o momento em que a Administração deve pagar ao parceiro privado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.284 (2)", "page_number": 284, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, § 3º da Lei n.º 11.079/04"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:10:15.201206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=284", "doc_key": "13d3dc0f76a2f244770568867b9dd707"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '49750745bd5e8217bdb18f3e2d027dfc22e84d9f9434b0c7f95233d9a87ef64d'),
  ('cpiuris2025::750c2cdcbbe0f45506c5debae8c2d737', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessões e Contratos em Concessões Públicas-Privadas (PPPs)', '## Concessões e Contratos em Concessões Públicas-Privadas (PPPs)

Resumo do texto sobre contratação de parceria público-privada, incluindo exemplos de concessões e PPP administrativa.

### Conceitos
- **Contraprestação**: o valor pago pela Administração Pública ao parceiro privado
- **Concessão Pública-P Privada (PPP)**: acordo entre Administração Pública e parceiro privado para prestação de serviços ou execução de obras
- **Aporte de Recursos**: doação de recursos pelo parceiro privado para realizar obras ou aquisição de bens reversíveis

### Referências legais
- Art. 6º, § 2º da Lei n.º 11.079/04
- Art. 2, § 4º da Lei n.º 11.079/04

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de contraprestação e como ela é pagada pela Administração Pública
- Conheça as diretrizes para a contratação de parceria público-privada previstas no art. 4º da Lei n.º 11.079/04', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.285", "page_number": 285, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, § 2º da Lei n.º 11.079/04", "Art. 2, § 4º da Lei n.º 11.079/04"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T09:11:14.501531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=285", "doc_key": "750c2cdcbbe0f45506c5debae8c2d737"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '11ae1cca6e6423c3c800a9e2c657d0e09d3e597ebd0010e47433fefb7fedc87d'),
  ('cpiuris2025::bf7c3611294301b974cc53cc942f17da', 'doutrina', 'cp_iuris', 'Direito Administrativo — Garantias em contratos de parceria público-privada', '## Garantias em contratos de parceria público-privada

A lei estabelece garantias para as obrigações pecuniárias da Administração Pública em contrato de parceria, incluindo vinculação de receitas, instituição de fundos especiais e contratação de seguro-garantia.

### Conceitos
- **Parceria público-privada**: Acordo entre a Administração Pública e uma empresa privada para realizar um projeto ou serviço
- **Garantias**: Métricas que asseguram a cobertura das obrigações pecuniárias da Administração Pública em contrato de parceria
- **Vinculação de receitas**: Obrigação de transferir uma parte das receitas públicas para garantir as obrigações pecuniárias do contrato

### Referências legais
- Art. 8o da Lei n.º 11.079/04
- Inciso IV do Art. 167 da Constituição Federal

### Jurisprudência
- Enunciado 34 do CJF

### Dicas de prova
- Entenda a importância das garantias em contratos de parceria público-privada
- Conheça as diferentes formas de garantia previstas na lei
- Aprenda a distinguir entre garantias e responsabilidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.286 (1)", "page_number": 286, "discipline": "Direito Administrativo", "legal_refs": ["Art. 8o da Lei n.º 11.079/04", "Inciso IV do Art. 167 da Constituição Federal"], "jurisprudence": ["Enunciado 34 do CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T09:12:05.651551+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=286", "doc_key": "bf7c3611294301b974cc53cc942f17da"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fc75a7a249a35995a2d283fb18a2eb605aa573a61584d39bcdec310497dabeef'),
  ('cpiuris2025::6b9323120558fa4d22af75a7b44c5af2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sociedade de Propósito Específico em PPP''s', '## Sociedade de Propósito Específico em PPP''s

A sociedade de propósito específica é uma pessoa jurídica de direito privado, criada para implantar e gerir o objeto da parceria, antes da celebração do contrato das PPP''s.

### Conceitos
- **Sociedade de Propósito Específico**: Pessoa jurídica de direito privado criada para implementar e gerir um objeto específico
- **PPC''s**: Parcerias Público-Privadas
- **Licitante vencedor**: A empresa que obtém o contrato após a concorrência
- **Poder Concedente**: O ente público que concede o contrato

### Referências legais
- Art. 9º da Lei das PPP''s

### Dicas de prova
- Entenda a diferença entre SPE e outras formas de sociedade
- Conheça as características da Sociedade de Propósito Específica em PPP''s', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.286 (2)", "page_number": 286, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9º da Lei das PPP''s"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:12:40.950768+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=286", "doc_key": "6b9323120558fa4d22af75a7b44c5af2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6a652a2ca8a34cd819d2f4fffd4f8d921cc0af96ab62416a3e83d5120eef3110'),
  ('cpiuris2025::b31e34b372ba928329560bd77b3827a4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratação de Parceria Público-Privada', '## Contratação de Parceria Público-Privada

A contratação de parceria público-privada é precedida de licitação, com requisitos específicos para abertura do processo licitatório e condições para a transferência do controle da sociedade de propósito específico.

### Conceitos
- **Parceria Público-Privada**: Acordo entre o Estado e uma empresa privada para realizar um projeto ou serviço
- **Licitação**: Processo em que as empresas concorrem para fornecer um bem ou serviço à Administração Pública
- **Concorrência**: Modalidade de licitação em que todas as propostas são comparadas e a mais vantajosa é escolhida
- **Diálogo Competitivo**: Modalidade de licitação em que apenas uma empresa é convidada a apresentar uma proposta
- **Autorização da Autoridade Competente**: Requisito para abertura do processo licitatório, que deve ser fundamentado em estudo técnico
- **Estudo Técnico**: Análise detalhada de uma proposta ou projeto para avaliar sua viabilidade e conveniência

### Referências legais
- Art. 10 da Lei Complementar nº 101/2000
- Súmula 645 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Parceria Público-Privada

### Dicas de prova
- Entenda a diferença entre concorrência e diálogo competitivo
- Conheça os requisitos para abertura do processo licitatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.287 (1)", "page_number": 287, "discipline": "Direito Administrativo", "legal_refs": ["Art. 10 da Lei Complementar nº 101/2000", "Súmula 645 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Parceria Público-Privada"], "confidence": 0.8, "extracted_at": "2026-05-25T09:13:54.352495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=287", "doc_key": "b31e34b372ba928329560bd77b3827a4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '36d28448f573a59d3fe46e77d1c69071aa840a64db1e829c78c436315507ee34'),
  ('cpiuris2025::3fa5c85b0a4ea078285a9d7499d04168', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratações Públicas', '## Contratações Públicas

Requisitos para a celebração de contratos com recursos públicos.

### Conceitos
- **Contratação Pública**: Processo pelo qual a Administração Pública adquire bens ou serviços.
- **Orçamento Público**: Plano que estabelece as receitas e despesas da União, dos Estados e dos Municípios.
- **Fluxo de Recursos Públicos**: Movimento de recursos públicos destinados a financiar atividades ou projetos.
- **Plano Plurianual**: Documento que estabelece as diretrizes gerais para o desenvolvimento do país durante um período de quatro anos.
- **Consulta Pública**: Procedimento pelo qual a Administração Pública busca a opinião e sugestões da população.
- **Edital**: Documento que publica as condições da contratação pública.

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Reconheça os requisitos para a celebração de contratos com recursos públicos.
- Entenda o papel do orçamento público e do plano plurianual na gestão pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.287 (2)", "page_number": 287, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T09:14:40.718431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=287", "doc_key": "3fa5c85b0a4ea078285a9d7499d04168"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e0d6c3ddd1f639eb91e8bbbedc45627840006eb7015d0a4dea4f220372bf26b7'),
  ('cpiuris2025::e9e033feeed45c4f36c384b0efd714d0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessões Públicas - Procedimento e Contratos', '## Concessões Públicas - Procedimento e Contratos

Regra para atualização de estudos e demonstrações após assinatura do contrato em exercício diverso, dependência de autorização legislativa específica para concessões patrocinadas com mais de 70% da remuneração do parceiro privado pago pela Administração Pública.

### Conceitos
- **Concessão Pública**: Acordo entre a Administração Pública e o parceiro privado para realização de obra ou serviço.
- **Parceria Público-Privada**: Acordo entre a Administração Pública e o parceiro privado para realização de obra ou serviço, com participação do setor público e privado.
- **Edital**: Instrumento convocatório que convida os licitantes a apresentar propostas.
- **Garantia de Proposta**: Valor mínimo que o licitante deve oferecer para participar da licitação.
- **Arbitragem**: Mecanismo de resolução de disputas entre as partes do contrato.
- **Procedimento de Licitação**: Sistema estabelecido pela Administração Pública para escolher o licitante que realizará a obra ou serviço.

### Referências legais
- Art. 11 da Lei nº 8.987/1995
- Art. 58, § 1º da Lei nº 14.133/21

### Dicas de prova
- Pergunte sobre a atualização de estudos e demonstrações após assinatura do contrato.
- Entenda o conceito de garantia de proposta e seu valor.
- Conheça os mecanismos de resolução de disputas, como a arbitragem.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.288 (1)", "page_number": 288, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11 da Lei nº 8.987/1995", "Art. 58, § 1º da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:15:44.009105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=288", "doc_key": "e9e033feeed45c4f36c384b0efd714d0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3ff0c8f2be5595310a9ede2cd1bc2148af22cf528c27aa71d30f3971e2bec2a1'),
  ('cpiuris2025::a43bc4b5c1e0a144c7b84457202e4f84', 'doutrina', 'cp_iuris', 'Direito Administrativo — Procedimento de Licitação', '## Procedimento de Licitação

Descreve os critérios que podem ser adotados no julgamento de licitações, incluindo a pontuação mínima e a combinação de critérios.

### Conceitos
- **Pontuação Mínima**: Valor mínimo que um licitante deve alcançar para participar das etapas subsequentes.
- **Critérios de Licitação**: Métodos utilizados para avaliar as propostas dos licitantes.
- **Tarifa do Serviço Público**: Preço do serviço público a ser prestado.
- **Oferta**: Quantidade ou valor oferecido pelo licitante.
- **Concessão**: Outorga da concessão de um serviço público ao concessionário.
- **Proposta Técnica**: Desenvolvimento detalhado do serviço público a ser prestado.
- **Contraprestação**: Valor pago pela Administração Pública ao licitante que for contratado.

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- Súmula 643 do STF
- ...

### Dicas de prova
- Entenda a importância da pontuação mínima na licitação.
- Conheça os critérios de licitação e suas combinações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.288 (2)", "page_number": 288, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["Súmula 643 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T09:16:41.231351+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=288", "doc_key": "a43bc4b5c1e0a144c7b84457202e4f84"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd22e55e2156f81f7d979b7d26dc10c9284873f975c6c74bb2537c7b5435da63d'),
  ('cpiuris2025::be1c4977fa990a5f4185728f9cbe2556', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitações e Contratos nas Concessões', '## Licitações e Contratos nas Concessões

Regulamentação das licitações e contratos em concessões, incluindo apresentação de propostas econômicas, lances em viva voz e saneamento de falhas.

### Conceitos
- **Edital**: Instrumento que define as regras e condições da licitação
- **Proposta Econômica**: Oferta econômica feita pelo licitante
- **Lances em Viva Voz**: Oferecimento de propostas em competição, com a apresentação de lances em voz alta
- **Habilitação**: Verificação se o licitante atende às condições fixadas no edital
- **Saneamento de Falhas**: Correção de erros ou falhas nos documentos do licitante
- **Concessão**: Contrato que concede direito a outorgar um bem ou serviço público

### Referências legais
- Art. 13 da Lei nº 8.666/1993

### Dicas de prova
- Pergunte sobre a apresentação de propostas econômicas e lances em viva voz
- Entenda o conceito de habilitação e saneamento de falhas
- Conheça as condições para a concessão de direitos a bens ou serviços públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.289", "page_number": 289, "discipline": "Direito Administrativo", "legal_refs": ["Art. 13 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:17:37.058678+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=289", "doc_key": "be1c4977fa990a5f4185728f9cbe2556"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3b6ccaf181cfd023a71cc48d5926116a76a8b2817f4e03aeb79b8b9297934a7f'),
  ('cpiuris2025::66e5b03975316ba6b427112bcd350174', 'doutrina', 'cp_iuris', 'Direito Administrativo — Agente Público', '## Agente Público

Pessoa física vinculada ao exercício de uma função pública, com ou sem remuneração.

### Conceitos
- **Agente Público**: Pessoa física vinculada à função pública
- **Teoria do Mandato**: Erros: vontades independentes, não responsabilidade do mandante pelos atos do mandatário
- **Teoria da Representação**: Erros: atos ultrapassando a representação, não responsabilidade do Estado por danos causados
- **Teoria do Órgão**: Agente faz parte do Estado, apresenta o Estado onde estiver presente

### Referências legais
- Art. 37 da Constituição Federal
- Súmula 387/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: natureza jurídica do agente público

### Dicas de prova
- Diferenciar entre teorias do mandato, da representação e do órgão
- Entender a natureza jurídica do agente público como parte integrante do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.291", "page_number": 291, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal", "Súmula 387/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: natureza jurídica do agente público"], "confidence": 0.8, "extracted_at": "2026-05-25T09:18:22.167707+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=291", "doc_key": "66e5b03975316ba6b427112bcd350174"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '73fab97398a53be61e34505c28f49ac2ddfc97d8f0cb63bd8b57212260f46e6f'),
  ('cpiuris2025::01803251deba33dd07b7ed7a0ab1aa4d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Agentes Públicos e Classificação', '## Agentes Públicos e Classificação

A teoria dos agentes públicos afirma que a vontade do Estado é representada pelos órgãos que compõem o agente público, substituindo a ideia de representação pela de imputação. Os agentes políticos são os titulares dos cargos estruturais da organização política do País, com funções de formadores da vontade superior do Estado.

### Conceitos
- **Agentes Públicos**: Pessoas jurídicas que representam o Estado em suas atividades
- **Agentes Políticos**: Titulares dos cargos estruturais da organização política do País, com funções de formadores da vontade superior do Estado
- **Investidura no Cargo**: Caráter transitório na função pública exercida por agentes políticos
- **Decisões Políticas**: Alocação de recursos orçamentários e elaboração de políticas públicas

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- Súmula nº 13 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Agentes Públicos e Classificação

### Dicas de prova
- Entenda a teoria dos agentes públicos e sua classificação
- Conheça as características dos agentes políticos e suas funções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.292", "page_number": 292, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "Súmula nº 13 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Agentes Públicos e Classificação"], "confidence": 0.8, "extracted_at": "2026-05-25T09:19:28.616947+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=292", "doc_key": "01803251deba33dd07b7ed7a0ab1aa4d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1af3fdd655b6ef04fdd07f8ed90aa4396f4e2d4ffdc1b91d898116299bee6215'),
  ('cpiuris2025::d05048cdb73c395187fa09e1cc7b70f6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Nepotismo e Súmula Vinculante N.º 13', '## Nepotismo e Súmula Vinculante N.º 13

A vedação ao nepotismo decorre diretamente da Constituição pelos princípios do art. 37, caput. Não é necessário uma lei formal para o tratamento do nepotismo, mas leis estaduais não podem reduzir a abrangência do nepotismo.

### Conceitos
- **Nepotismo**: Tratamento favorável de parentes em cargos públicos
- **Súmula Vinculante N.º 13**: Decisão do STF que trata da vedação ao nepotismo em cargos públicos

### Referências legais
- Art. 37, caput, da Constituição; Súmula Vinculante N.º 13 do STF

### Jurisprudência
- RE 123456
- Súmula Vinculante N.º 13 do STF

### Dicas de prova
- Distinguir entre a vedação ao nepotismo e a existência de uma lei formal
- Entender que leis estaduais não podem reduzir a abrangência do nepotismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.293 (1)", "page_number": 293, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, caput, da Constituição; Súmula Vinculante N.º 13 do STF"], "jurisprudence": ["RE 123456", "Súmula Vinculante N.º 13 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T09:20:13.070955+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=293", "doc_key": "d05048cdb73c395187fa09e1cc7b70f6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '36635507c8356869231df2f7b5ce12c7cf072e326bb92f25e57c1e4ec8c7b4c2'),
  ('cpiuris2025::03e5512ea75bc285e6a81ac01ac504cd', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos normativos internos e influência da autoridade nomeante', '## Atos normativos internos e influência da autoridade nomeante

Regras para atos normativos internos de órgãos e poderes, influência da autoridade nomeante e parentesco.

### Conceitos
- **ato normativo interno**: ato que regula a matéria dentro de um órgão ou poder
- **influência da autoridade nomeante**: necessidade de influência do servidor nomeante sobre o servidor nomeado, além do parentesco
- **parentesco**: relação de sangue ou casamento entre servidor e servidor nomeante
- **nepotismo**: nomeação de parente para cargo público sem a necessária influência da autoridade nomeante
- **improbidade administrativa**: conduta que configura a responsabilidade do servidor público por atos ilegais ou antiéticos

### Referências legais
- Art. 11, XI c/c Art. 11, § 5º da Lei n.º 8.429/92

### Jurisprudência
- 156 STF. Rcl. 6702-AgR-MC/PR
- Tema Nepotismo

### Dicas de prova
- Diferenciar entre atos normativos internos e nepotismo
- Entender a necessidade de influência da autoridade nomeante além do parentesco', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.293 (2)", "page_number": 293, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11, XI c/c Art. 11, § 5º da Lei n.º 8.429/92"], "jurisprudence": ["156 STF. Rcl. 6702-AgR-MC/PR", "Tema Nepotismo"], "confidence": 0.8, "extracted_at": "2026-05-25T09:20:56.571038+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=293", "doc_key": "03e5512ea75bc285e6a81ac01ac504cd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '601ad1b67ec113c5324ea463ff6eb18da777302ad6a6623ca34b81fc72e90d38'),
  ('cpiuris2025::37ad58660d0f1a151d828dbef683cf70', 'doutrina', 'cp_iuris', 'Direito Administrativo — Agentes Públicos e Servidores Públicos', '## Agentes Públicos e Servidores Públicos

O texto discute a definição de agentes públicos e servidores públicos, destacando as diferenças entre eles e a importância do regime estatutário. Além disso, é abordada a necessidade do dolo específico para configurar improbidade.

### Conceitos
- **Agentes Públicos**: Pessoas físicas que prestam serviços ao Estado e às entidades da Administração Indireta, com vínculo empregatício e remuneração paga pelos cofres públicos.
- **Servidores Públicos**: Pessoas físicas que prestam serviços ao Estado e às entidades da Administração Indireta, em sentido amplo
- **Regime Estatutário**: Regra jurídica específica que disciplina a relação de trabalho entre o servidor público e o Estado.
- **Dolo Específico**: Vontade de produzir resultado ilícito, necessária para configurar improbidade.

### Referências legais
- Art. 11 da Lei nº 14.230/2021
- Art. 37, V da Constituição Federal

### Dicas de prova
- Entenda a distinção entre agentes públicos e servidores públicos.
- Conheça o regime estatutário e sua importância.
- Identifique a necessidade do dolo específico para configurar improbidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.294", "page_number": 294, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11 da Lei nº 14.230/2021", "Art. 37, V da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:22:03.327287+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=294", "doc_key": "37ad58660d0f1a151d828dbef683cf70"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ad9417bf254fe9c9c384cefb2e31b1ea338f2b6e5688a7afb206db25c6ca1b46'),
  ('cpiuris2025::3b18e67938ff6c88780a4957454bbf16', 'doutrina', 'cp_iuris', 'Direito Administrativo — Agentes Públicos', '## Agentes Públicos

Os agentes públicos são pessoas físicas que exercem função pública, sendo divididos em servidores estatutários, empregados públicos e servidores temporários. Os servidores estatutários têm regras disciplinadoras semelhantes às de iniciativa privada, enquanto os empregados públicos e servidores temporários têm regras específicas do direito administrativo.

### Conceitos
- **Servidor Estatutário**: Pessoa física que exercita função pública com regras disciplinadoras semelhantes às de iniciativa privada
- **Empregado Público**: Pessoa física ocupante de emprego público contratada sob o regime celetista
- **Servidor Temporário**: Pessoa física contratada por tempo determinado para atender à necessidade temporária de excepcional interesse público

### Referências legais
- Art. 37, II da CR/88
- Art. 37, IX da CR/88

### Jurisprudência
- RE 1066677
- Súmula do STJ sobre contratação temporária de servidor por excepcional interesse público

### Dicas de prova
- Distinção entre servidores estatutários, empregados públicos e servidores temporários
- Importância da previsão legal e/ou contratual para a contratação temporária de servidor
- Repercussão geral do STF sobre a contratação por tempo determinado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.295 (1)", "page_number": 295, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, II da CR/88", "Art. 37, IX da CR/88"], "jurisprudence": ["RE 1066677", "Súmula do STJ sobre contratação temporária de servidor por excepcional interesse público"], "confidence": 0.8, "extracted_at": "2026-05-25T09:22:59.598995+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=295", "doc_key": "3b18e67938ff6c88780a4957454bbf16"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '64e3d1ee6ca08eaf6cc7ab8298f32906ef52bc829c158e304618b45c1a87901d'),
  ('cpiuris2025::921b27daa77500dbfb365f81fef41cf8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Servidores Públicos e Regime Jurídico', '## Servidores Públicos e Regime Jurídico

Resumo objetivo: A questão discute a natureza jurídica dos servidores públicos contratados, distinguindo entre o regime jurídico estatutário da União e dos Estados versus o contrato de trabalho em municípios. Além disso, destaca-se a importância do termo ''poderão'' para determinar se um servidor público é empregado público ou não.

### Conceitos
- **Servidores Públicos**: Pessoas contratadas pelo Estado para exercerem funções públicas.
- **Regime Jurídico Estatutário**: O regime jurídico adotado pela União e pelos Estados, que regula a relação entre o Estado e seus servidores públicos.
- **Contrato de Trabalho**: O regime jurídico adotado por municípios, que caracteriza os servidores públicos como empregados públicos.
- **Poderão**: A expressão usada para determinar a natureza jurídica da relação entre o Estado e seus servidores públicos.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- ...

### Jurisprudência
- Súmula 634 do STF
- ...

### Dicas de prova
- Entenda a distinção entre o regime jurídico estatutário e o contrato de trabalho.
- Identifique a expressão ''poderão'' como um termo-chave para determinar a natureza jurídica dos servidores públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.295 (2)", "page_number": 295, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "..."], "jurisprudence": ["Súmula 634 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T09:23:49.350025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=295", "doc_key": "921b27daa77500dbfb365f81fef41cf8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0ff9ba97b22b1787ac18707123090a055d0c30264c5f41e4e45897dbc87f679c'),
  ('cpiuris2025::1e2a34bfe3a5368d218f09f258eadee5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Agentes Públicos e Contratação Temporária', '## Agentes Públicos e Contratação Temporária

Resumo do artigo 37, IX, da CF sobre contratação temporária e requisitos para sua validade.

### Conceitos
- **Contratação Temporária**: Contratação de serviços ou obras para um período determinado
- **Lei nº 8.036/1990**: Lei que regula o FGTS e outras questões trabalhistas
- **Art. 19-A**: Disposição específica da Lei nº 8.036/1990 sobre levantamento de depósitos no FGTS
- **Válida Contratação Temporária**: Contratação que atende aos requisitos estabelecidos na lei, incluindo a necessidade de interesse público excepcional e contratação para serviços ordinários permanentes do Estado

### Referências legais
- Art. 37, IX, da CF
- Art. 19-A da Lei nº 8.036/1990

### Dicas de prova
- Entenda a distinção entre contratação temporária e serviços ordinários permanentes do Estado
- Conheça os requisitos para validade de contratação temporária, incluindo interesse público excepcional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.296 (1)", "page_number": 296, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, IX, da CF", "Art. 19-A da Lei nº 8.036/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:24:50.501257+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=296", "doc_key": "1e2a34bfe3a5368d218f09f258eadee5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'edcd3ce309c44ed3e6b934fbece52761a330b419712df39d3c0bff5d118ee3b5'),
  ('cpiuris2025::979689c613799c75b57e848fcc93f188', 'doutrina', 'cp_iuris', 'Direito Administrativo — Proibição de concurso público para militares afastados', '## Proibição de concurso público para militares afastados

Lei estadual é inconstitucional se impede a realização de concurso público sem prazo para o término da proibição.

### Conceitos
- **Constituição**: Instrumento supremo do Estado
- **Proibição**: Restrição à liberdade
- **Cargo público**: Função exercida pelo Estado
- **Lei estadual**: Lei específica de um estado

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Jurisprudência
- ADI 2.893/PE
- RE 765.320 RG
- RE 658.026

### Dicas de prova
- Distinção entre proibição e restrição à liberdade
- Importância da Constituição Federal no Direito Administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.296 (2)", "page_number": 296, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": ["ADI 2.893/PE", "RE 765.320 RG", "RE 658.026"], "confidence": 0.8, "extracted_at": "2026-05-25T09:25:23.179653+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=296", "doc_key": "979689c613799c75b57e848fcc93f188"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7e5efe9d376e12725d010b64c72c6e30c9900f357dc330c5ab03db7dd0c0e81f'),
  ('cpiuris2025::683353567a7f7ea4677a0637a24fb4fa', 'doutrina', 'cp_iuris', 'Direito Administrativo — Agentes Públicos e Agentes de Fato', '## Agentes Públicos e Agentes de Fato

Descreve as diferentes categorias de agentes públicos e agentes de fato, incluindo agentes honoríficos, delegados, credenciados, necessários e putativos.

### Conceitos
- **Agente Honorífico**: Pessoa que exercita função pública relevante em caráter transitório
- **Agente Delegado**: Pessoa que realiza uma função específica em nome próprio
- **Gestor de Negócios Público**: Pessoa que assume função pública espontaneamente em momentos de calamidades públicas ou emergências
- **Agente Credenciado**: Pessoa que recebe a incumbência de representar a Administração em determinado evento ou atividade
- **Agente de Fato**: Pessoa que não possui vínculos válidos com o Estado, mas desempenha função pública com intenção de satisfazer interesse público
- **Usurpação de Função Pública**: Exercício da função pública com má-fé e sem investidura prévia e válida
- **Má-Fé**: Intenção de agir de forma contrária ao interesse público

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- RE 123456
- Tema repetitivo em processos administrativos

### Dicas de prova
- Entenda a distinção entre agentes honoríficos e delegados
- Conheça as diferentes categorias de agentes de fato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.297", "page_number": 297, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo em processos administrativos"], "confidence": 0.8, "extracted_at": "2026-05-25T09:26:21.750376+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=297", "doc_key": "683353567a7f7ea4677a0637a24fb4fa"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'df9b4865ad4db0130a2bde50487f713c4428112151b6e157be443e2e8805a490'),
  ('cpiuris2025::b8ef279edebe120687ce8e9d5c3416f5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regimes Jurídicos Funcionais', '## Regimes Jurídicos Funcionais

Os regimes jurídicos funcionais são estatutário e trabalhista, cada um com suas regras e características. O regime estatutário é institucional e não contratual, enquanto o regime trabalhista é contratual.

### Conceitos
- **Regime Estatutário**: Relação jurídica funcional entre servidor público estatutário e o Estado
- **Estatuto Funcional**: Lei que regulamenta a relação jurídica funcional entre servidor público estatutário e o Estado
- **Regime Trabalhista**: Relação jurídica funcional entre servidor público trabalhista e o Poder Público
- **Contrato de Trabalho**: Relação jurídica funcional entre servidor público trabalhista e o Poder Público

### Referências legais
- Art. 328 do Código Penal
- Lei nº 8.112/90

### Dicas de prova
- Diferenciar entre regime estatutário e trabalhista
- Entender a natureza da relação jurídica funcional entre servidor público e o Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.298", "page_number": 298, "discipline": "Direito Administrativo", "legal_refs": ["Art. 328 do Código Penal", "Lei nº 8.112/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:27:22.883750+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=298", "doc_key": "b8ef279edebe120687ce8e9d5c3416f5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '445715a082a7d2e91cbe16ca5a499d9eb89ea74daa027a9eaae3273f1a8040ef'),
  ('cpiuris2025::76cdf071f4209754a12e4b34bbd1224f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regime Jurídico Único (RJU) e contratação de servidores públicos', '## Regime Jurídico Único (RJU) e contratação de servidores públicos

O Regime Jurídico Único foi abolido pela EC n.º 19/98, permitindo a pluralidade de regimes jurídicos para os servidores públicos. Os entes federados podem ter servidores sob o vínculo estatutário e sob o vínculo de contrato de trabalho.

### Conceitos
- **Regime Jurídico Único (RJU)**: Regime jurídico único para os servidores da Administração Pública direta, suas autarquias e fundações
- **Contratação de servidores públicos**: Relação jurídica funcional entre o servidor público e o Poder Público
- **Vínculo de trabalho subordinado**: Condição da relação jurídica funcional entre o servidor público e o Poder Público
- **Regime estatutário**: Um dos regimes jurídicos que disciplina as relações com os servidores públicos
- **Contrato de trabalho**: Relação jurídica entre o servidor público e o Poder Público, diferente do regime estatutário

### Referências legais
- Art. 37, IX, da Constituição da República
- EC n.º 19/98

### Jurisprudência
- STF. RECURSO EXTRAORDINÁRIO 846854
- RECURSO EXTRAORDINÁRIO 846854 Relator(a): Min. ALEXANDRE DE MORAES

### Dicas de prova
- Entenda a diferença entre o regime estatutário e o contrato de trabalho para os servidores públicos
- Conheça as implicações da abolição do Regime Jurídico Único pela EC n.º 19/98', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.299", "page_number": 299, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, IX, da Constituição da República", "EC n.º 19/98"], "jurisprudence": ["STF. RECURSO EXTRAORDINÁRIO 846854", "RECURSO EXTRAORDINÁRIO 846854 Relator(a): Min. ALEXANDRE DE MORAES"], "confidence": 0.8, "extracted_at": "2026-05-25T09:28:32.467193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=299", "doc_key": "76cdf071f4209754a12e4b34bbd1224f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '374f4ce7fa52ee2adce350c81f97a94c8e4b7832fd4236c9f843eeab9cfc54e5'),
  ('cpiuris2025::b629b8b496f8f653f6fbcd09c65b4811', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regime Jurídico Único', '## Regime Jurídico Único

O regime jurídico único foi retomado após a suspensão da eficácia do artigo 39, caput, pela EC nº 19/98 devido a vício de inconstitucionalidade formal. O mérito da ADI 2135 foi julgado em 2020 e 2021, com o entendimento prevalecente que não houve violação ao processo legislativo.

### Conceitos
- **Regime Jurídico Único**: Sistema de direito administrativo que adota um único regime jurídico para todos os entes federados.
- **EC nº 19/98**: Emenda constitucional que alterou o artigo 39, caput, da Constituição Federal.
- **ADI 2135**: Ação direta de inconstitucionalidade que questionou a alteração do regime jurídico único.
- **Vício de inconstitucionalidade formal**: Erro no procedimento de tramitação da emenda constitucional.
- **Processo legislativo**: Procedimento pelo qual a Constituição Federal é alterada.

### Referências legais
- Art. 39, caput, da CF/88; EC nº 19/98

### Jurisprudência
- ADI 2135; Súmula N da STF

### Dicas de prova
- Entenda a diferença entre regime jurídico único e sistema de direito administrativo.
- Conheça o processo legislativo e os vicios de inconstitucionalidade formal.
- Análise do mérito da ADI 2135 e seu impacto na Constituição Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.300", "page_number": 300, "discipline": "Direito Administrativo", "legal_refs": ["Art. 39, caput, da CF/88; EC nº 19/98"], "jurisprudence": ["ADI 2135; Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-25T09:29:31.873338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=300", "doc_key": "b629b8b496f8f653f6fbcd09c65b4811"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8afcd9dff5b4e209f2243ec90382dc5aa3cff392c19f91526cd7afec0e23c091'),
  ('cpiuris2025::754fdf7bb58cb89b9dab961d0b78b55a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Agentes Públicos', '## Agentes Públicos

A Reforma Administrativa de 1998 (EC 19/98) suprimiu a obrigatoriedade de regimes jurídicos únicos e planos de carreira para servidores públicos, permitindo a contratação sob diferentes regimes.

### Conceitos
- **Regime Jurídico Único**: RJU
- **Plano de Carreira**: PC
- **Declaração de Constitucionalidade**: DC

### Referências legais
- Art. 37, I a VIII da CF

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância dos regimes jurídicos únicos e planos de carreira nos contratos públicos.
- Conheça as consequências da Reforma Administrativa de 1998 (EC 19/98) para os servidores públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.301", "page_number": 301, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, I a VIII da CF"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.9, "extracted_at": "2026-05-25T09:30:17.842749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=301", "doc_key": "754fdf7bb58cb89b9dab961d0b78b55a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd09ed757eee5aa713333d80665dc5792573c8ab4d764908571f2ac323223e1dd'),
  ('cpiuris2025::b630d9f2ea6eefe66af993ad6d5e70a8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Investidura em Cargo Público', '## Investidura em Cargo Público

A investidura em cargo público depende de aprovação prévia em concurso público, exceto para cargos em comissão declarados em lei de livre nomeação e exoneração. A equiparação de carreiras é inconstitucional se não for justificada pela natureza das atribuições do cargo.

### Conceitos
- **Concurso Público**: Aprovação prévia em concurso público para investidura em cargo público
- **Carreira Pública**: Carga que o servidor deve exercer, de acordo com a natureza do cargo
- **Cargo em Comissão**: Cargo cuja nomeação e exoneração são feitas por lei de livre nomeação e exoneração
- **Estabilidade Provisória**: Direito da servidora gestante à estabilidade provisória no cargo
- **Ascensão Funcional**: Aumento do servidor sem aprovação em concurso público

### Referências legais
- Art. 37, II, CF
- Súmula Vinculante nº 43 STF
- Súmula Vinculante nº 44 STF
- Súmula Nº 683 STF
- Súmula nº 14 STF
- Súmula nº 684 STF
- Súmula nº 266 STJ

### Jurisprudência
- Re 898450 - 17/08/2016
- Tema repetitivo: Investidura em Cargo Público

### Dicas de prova
- Diferenciar entre concurso público e equiparação de carreiras
- Entender a diferença entre cargo em comissão e carreira pública
- Conhecer o direito à estabilidade provisória da servidora gestante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.302", "page_number": 302, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, II, CF", "Súmula Vinculante nº 43 STF", "Súmula Vinculante nº 44 STF", "Súmula Nº 683 STF", "Súmula nº 14 STF", "Súmula nº 684 STF", "Súmula nº 266 STJ"], "jurisprudence": ["Re 898450 - 17/08/2016", "Tema repetitivo: Investidura em Cargo Público"], "confidence": 0.8, "extracted_at": "2026-05-25T09:32:59.483052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=302", "doc_key": "b630d9f2ea6eefe66af993ad6d5e70a8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e402030b72d54578de8ea34caf38ca9eb7db9d0937ba9cd5cf1c35da578546de'),
  ('cpiuris2025::f0a37cdf1f1942110469dddd58deee5c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Nomeação de candidatos aprovados em concurso público e direitos funcionais', '## Nomeação de candidatos aprovados em concurso público e direitos funcionais

A nomeação tardia de candidatos aprovados em concurso público não gera direito às promoções ou progressões funcionais. A investidura no cargo é necessária para gerar os direitos funcionais inerentes ao cargo público.

### Conceitos
- **Investidura**: O ato de assumir um cargo público
- **Prerrogativas funcionais**: Direitos e benefícios concedidos aos servidores públicos em virtude do cargo que ocupam
- **Efeitos funcionais**: Benefícios e direitos concedidos aos servidores públicos, como tempo de serviço, previdência, etc.
- **Enriquecimento ilícito**: O ato de obter vantagem indevida por meio de uma situação jurídica

### Referências legais
- Art. 5º, inciso VIII, da Constituição Federal

### Jurisprudência
- RE 611874
- Tema repetitivo: Nomeação de candidatos aprovados em concurso público

### Dicas de prova
- Entenda a diferença entre investidura e nomeação no contexto do direito administrativo.
- Conheça os requisitos para a realização de etapas de concurso público em datas e horários distintos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.303 (1)", "page_number": 303, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, inciso VIII, da Constituição Federal"], "jurisprudence": ["RE 611874", "Tema repetitivo: Nomeação de candidatos aprovados em concurso público"], "confidence": 0.8, "extracted_at": "2026-05-25T09:33:53.151575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=303", "doc_key": "f0a37cdf1f1942110469dddd58deee5c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a139b02b392d3963f118da5a095366d99b53690c7d6d2f101bcf1e83c97498e7'),
  ('cpiuris2025::d91bedd9e671d8eb1992d7ff972bb46b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade do Estado em concurso público', '## Responsabilidade do Estado em concurso público

O Estado responde subsidiariamente por danos materiais causados a candidatos em concurso público organizado por pessoa jurídica de direito privado, quando os exames são cancelados por indícios de fraude. Além disso, é inconstitucional norma que prevê isenção de taxa de inscrição para servidores públicos em concurso público.

### Conceitos
- **Responsabilidade do Estado**: O Estado responde por danos causados a terceiros
- **Concurso Público**: Processo de seleção de candidatos para cargo público
- **Isonomia**: A igualdade perante a lei
- **Justiça Social**: Objetivo fundamental da República

### Referências legais
- Art. 37, § 6º, da CRFB/88

### Jurisprudência
- RE 662405
- RE 629.392
- RE 655.265-AgR

### Dicas de prova
- Distinção entre responsabilidade do Estado e isonomia
- Importância da justiça social nos objetivos fundamentais da República', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.303 (2)", "page_number": 303, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 6º, da CRFB/88"], "jurisprudence": ["RE 662405", "RE 629.392", "RE 655.265-AgR"], "confidence": 0.8, "extracted_at": "2026-05-25T09:34:45.599210+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=303", "doc_key": "d91bedd9e671d8eb1992d7ff972bb46b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1895de0929f9383f1c9f54a527c7d33e5e2811a9f48021af52b08dfbd6e39b95'),
  ('cpiuris2025::06c3189ae736fb8d3b2029e07a1fe634', 'doutrina', 'cp_iuris', 'Direito Administrativo — Isenção da taxa de inscrição em concursos públicos', '## Isenção da taxa de inscrição em concursos públicos

A isenção da taxa de inscrição nos concursos públicos estaduais é questionada, com a questão se a medida não amplia a desigualdade entre os candidatos. O Estado de Santa Catarina entendeu que a isenção não viola o princípio da isonomia, considerando a renda declarada dos candidatos.

### Conceitos
- **Isenção**: Exceção ou dispensa de uma obrigação ou pagamento
- **Isonomia**: Princípio da igualdade perante a lei
- **Taxa de inscrição**: Preço pago pelos candidatos para participar do concurso público
- **Concurso público**: Processo em que os candidatos são selecionados para ocupar cargos públicos

### Referências legais
- Art. 37, III e IV da Constituição Brasileira

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda o conceito de isenção e isonomia para responder à questão.
- Avalie se a medida de isenção da taxa de inscrição é justificável ou não.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.304 (1)", "page_number": 304, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, III e IV da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T09:35:36.199357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=304", "doc_key": "06c3189ae736fb8d3b2029e07a1fe634"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7bd5048b7e5b92ba8786240adbdbf538e29a81eb206eb705c6116708e1d19563'),
  ('cpiuris2025::28d6dcedd6b504b3c678fb5084815207', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prazo improrrogável e cargos em comissão', '## Prazo improrrogável e cargos em comissão

A expressão ''prazo improrrogável'' deve ser interpretada extensivamente, abrangendo o prazo de validade do concurso público. Cargos em comissão podem ser criados apenas para funções de direção, chefia e assessoramento.

### Conceitos
- **Prazo improrrogável**: Prazo dentro do qual o concurso público tem validade
- **Cargos em comissão**: Funções exercidas por servidores de carreira, destinadas a direção, chefia e assessoramento

### Referências legais
- Art. 37, V da Constituição Brasileira

### Jurisprudência
- {''term'': ''RE nº 192.568 STF'', ''definition'': ''''}
- {''term'': ''RE 1041210'', ''definition'': ''Parâmetros para a criação de cargos em comissão''}

### Dicas de prova
- Entenda o conceito de prazo improrrogável e sua aplicação nas concursos públicos.
- Conheça as condições para a criação de cargos em comissão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.304 (2)", "page_number": 304, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, V da Constituição Brasileira"], "jurisprudence": ["{''term'': ''RE nº 192.568 STF'', ''definition'': ''''}", "{''term'': ''RE 1041210'', ''definition'': ''Parâmetros para a criação de cargos em comissão''}"], "confidence": 0.8, "extracted_at": "2026-05-25T09:36:18.318274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=304", "doc_key": "28d6dcedd6b504b3c678fb5084815207"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '67aa651d8fdb74c82c1fdf568cd47cc5045ffc65c37414c527eaaee9b637a354'),
  ('cpiuris2025::417e9bdb526273775167d597062681ab', 'doutrina', 'cp_iuris', 'Direito Administrativo — Direito de Greve e Servidores Públicos', '## Direito de Greve e Servidores Públicos

O Direito de Greve é garantido ao servidor público civil, mas precisa ser exercido nos termos e limites definidos em lei específica. A greve não caracteriza abandono de cargo e a administração pública deve proceder ao desconto dos dias não trabalhados em razão da greve.

### Conceitos
- **Direito de Greve**: direito garantido ao servidor público civil
- **Abandono de Cargo**: não configura falta injustificada
- **Desconto dos Dias Não Trabalhados**: deve ser feito pela administração pública em virtude da suspensão do vínculo funcional

### Referências legais
- Art. 37, VI e VII da Constituição Brasileira de 1988

### Jurisprudência
- RE 693456/2016
- Súmula 175 do STF

### Dicas de prova
- Entenda a teoria concretista geral sobre o Direito de Greve
- Conheça as regras para o desconto dos dias não trabalhados em razão da greve', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.305 (1)", "page_number": 305, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, VI e VII da Constituição Brasileira de 1988"], "jurisprudence": ["RE 693456/2016", "Súmula 175 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T09:37:16.224953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=305", "doc_key": "417e9bdb526273775167d597062681ab"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '27f3fe0b51159eeaedbbfe1510f704121f91cca7f088abd90acdf44edc04d720'),
  ('cpiuris2025::3765edaeb4d9a957036053c5bbab865c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Ato Discricionário e Compensação de Perda de Tempo', '## Ato Discricionário e Compensação de Perda de Tempo

O administrador tem discricionariedade para aceitar ou não a compensação dos dias e horas paradas, mas não há obrigatoriedade de aceitação. A decisão é ato discricionário.

### Conceitos
- **Ato Discricionário**: Atividade administrativa que depende da discricionariedade do administrador.
- **Compensação**: Pagamento ou benefício concedido ao funcionário por perda de tempo ou serviço.
- **Princípio da Indisponibilidade do Interesse Público**: Não pode ser alienado ou prejudicado o interesse público.
- **Princípio da Legalidade**: Todas as ações administrativas devem estar previstas em lei.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- ...

### Jurisprudência
- {''ref'': ''175 STF. ADI 3235/2010'', ''description'': ''Decisão que afirma a discricionariedade do administrador na aceitação de compensação.''}
- {''ref'': ''176 STF - [RE 846.854, rel. p/ o ac. min. Alexandre de Moraes, j. 1º-8-2017, P, DJE de 7-2-2018, Tema 544]'', ''description'': ''Decisão que destaca a discricionariedade do administrador na compensação.''}

### Dicas de prova
- Entenda a discricionariedade do administrador e como ela afeta a aceitação de compensação.
- Reconheça os princípios da indisponibilidade do interesse público e da legalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.305 (2)", "page_number": 305, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "..."], "jurisprudence": ["{''ref'': ''175 STF. ADI 3235/2010'', ''description'': ''Decisão que afirma a discricionariedade do administrador na aceitação de compensação.''}", "{''ref'': ''176 STF - [RE 846.854, rel. p/ o ac. min. Alexandre de Moraes, j. 1º-8-2017, P, DJE de 7-2-2018, Tema 544]'', ''description'': ''Decisão que destaca a discricionariedade do administrador na compensação.''}"], "confidence": 0.8, "extracted_at": "2026-05-25T09:38:10.399304+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=305", "doc_key": "3765edaeb4d9a957036053c5bbab865c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '638751312ae453111beed9db1676d209a495b1bcfefbcbb785fa2ef70ee86cf3'),
  ('cpiuris2025::0d8615457de451ee793404a6d397e6c2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desconto em parcela única sobre remuneração do servidor público', '## Desconto em parcela única sobre remuneração do servidor público

O STJ não permite desconto em parcela única sobre a remuneração do servidor público dos dias parados e não compensados provenientes do exercício do direito de greve, pois há necessidade de ponderações e verificação da razoabilidade e proporcionalidade do ato. No entanto, pode ser possível o desconto em parcela única desde que haja razoabilidade nesse ato.

### Conceitos
- **Razoabilidade**: necessidade de ponderações
- **Proporcionalidade**: verificação do ato
- **Desconto em parcela única**: remuneração do servidor público

### Referências legais
- Art. 165 do CPC
- Súmula nº 552 STJ

### Jurisprudência
- RE 123456
- RMS 49.339-SP
- ADC 41/DF

### Dicas de prova
- Ponderações e verificação da razoabilidade e proporcionalidade do ato
- Diferença entre desconto em parcela única e remuneração do servidor público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.306 (1)", "page_number": 306, "discipline": "Direito Administrativo", "legal_refs": ["Art. 165 do CPC", "Súmula nº 552 STJ"], "jurisprudence": ["RE 123456", "RMS 49.339-SP", "ADC 41/DF"], "confidence": 0.8, "extracted_at": "2026-05-25T09:38:54.603340+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=306", "doc_key": "0d8615457de451ee793404a6d397e6c2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '00dfb171c2e5c6c106067fb48954659e4cbb74358c8feed1950d00e3b8538283'),
  ('cpiuris2025::2b2a6e454645bffa88d93c22e268b095', 'doutrina', 'cp_iuris', 'Direito Administrativo — Heteroidentificação e controle de fraude em cotas', '## Heteroidentificação e controle de fraude em cotas

A heteroidentificação é legítima se viabilizar o controle de fraude, como a autodeclaração de cor para obter vantagens ou a restrição do alcance da política afirmativa.

### Conceitos
- **Heteroidentificação**: Procedimento que permite ao candidato se identificar de forma diferente à sua realidade racial
- **Controle de fraude**: Medidas para evitar a manipulação do sistema de cotas
- **Política afirmativa**: Medida implementada para promover a igualdade racial em concursos e processos seletivos

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- {''ref'': ''ARE 654.432'', ''term'': ''Tema repetitivo: Legítima a heteroidentificação se viabilizar o controle de fraude em cotas''}

### Dicas de prova
- Entenda a distinção entre autodeclaração e identidade racial do candidato
- Conheça as medidas para evitar a manipulação do sistema de cotas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.306 (2)", "page_number": 306, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["{''ref'': ''ARE 654.432'', ''term'': ''Tema repetitivo: Legítima a heteroidentificação se viabilizar o controle de fraude em cotas''}"], "confidence": 0.8, "extracted_at": "2026-05-25T09:39:47.601568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=306", "doc_key": "2b2a6e454645bffa88d93c22e268b095"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7bc2ba4fdcd5815dd77ddd856bfedf009031138bf5103f04944baf221264e36e'),
  ('cpiuris2025::3a9a99b9ecd7701b29c93a5d38989a74', 'doutrina', 'cp_iuris', 'Direito Administrativo — Agentes Públicos e Seleção para Vagas Reservadas', '## Agentes Públicos e Seleção para Vagas Reservadas

A seleção de candidatos para vagas reservadas deve ser controlada por meio de comissões preordenadas e meios clássicos de controle administrativo. A exclusão do candidato pela heteroidentificação exige o franqueamento do contraditório e da ampla defesa.

### Conceitos
- **Heteroidentificação**: Processo pelo qual a Administração Pública verifica se um candidato tem ou não deficiência
- **Contraditório e Ampla Defesa**: Direito do candidato de ser ouvido antes da exclusão de sua candidatura
- **Quadro Funcional**: Reunião de carreiras, cargos isolados e funções públicas remuneradas em um órgão ou pessoa jurídica
- **Carreira Funcional**: Reunião de classes funcionais que os servidores irão percorrer na progressão funcional

### Referências legais
- Art. 12 da Lei n. 8.666/1993
- Súmula 2.397/STJ
- ADI 7.654 MC-Ref/DF, Rel. Min. Flávio Dino

### Jurisprudência
- RE 123456
- Tema repetitivo: Seleção de Candidatos para Vagas Reservadas

### Dicas de prova
- Entenda a importância da heteroidentificação e do contraditório na seleção de candidatos.
- Conheça as diferenças entre quadro funcional e carreira funcional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.307 (1)", "page_number": 307, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12 da Lei n. 8.666/1993", "Súmula 2.397/STJ", "ADI 7.654 MC-Ref/DF, Rel. Min. Flávio Dino"], "jurisprudence": ["RE 123456", "Tema repetitivo: Seleção de Candidatos para Vagas Reservadas"], "confidence": 0.8, "extracted_at": "2026-05-25T09:40:47.343642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=307", "doc_key": "3a9a99b9ecd7701b29c93a5d38989a74"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6adf9f763a1f373e51fdd4b3b6da5190c39cbdbdd16df21bdb5c1ec1bbe3c807'),
  ('cpiuris2025::b1b1b732487ae7a77a1bb4e32e78dc42', 'doutrina', 'cp_iuris', 'Direito Administrativo — Cargos Públicos e Progressão Funcional', '## Cargos Públicos e Progressão Funcional

As classes funcionais são a reunião de cargos com atribuição igual, os cargos são as unidades mínimas do órgão. A progressão funcional é a passagem para um estágio mais elevado na carreira, seja por tempo de serviço ou merecimento, alterando o tratamento do servidor.

### Conceitos
- **Cargos Públicos**: Unidades mínimas do órgão
- **Classes Funcionais**: Reunião de cargos com atribuição igual
- **Progressão Funcional**: Passagem para um estágio mais elevado na carreira
- **Promoção**: Vacância do cargo e provimento em um novo
- **Merecimento**: Possibilidade de alteração do tratamento do servidor

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- 178 STJ. RMS 62.040-MG

### Dicas de prova
- Diferenciar progressão funcional e promoção
- Entender a importância do merecimento na progressão funcional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.307 (2)", "page_number": 307, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["178 STJ. RMS 62.040-MG"], "confidence": 0.8, "extracted_at": "2026-05-25T09:41:27.857154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=307", "doc_key": "b1b1b732487ae7a77a1bb4e32e78dc42"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2ca003d885b79908e47c2c8d46ee71d4ca57fffd46770e343ff38529e9b9c0e7'),
  ('cpiuris2025::19d9e65595179c982295f1d78bdf9022', 'doutrina', 'cp_iuris', 'Direito Administrativo — Cargo, Emprego e Função Pública', '## Cargo, Emprego e Função Pública

Descreve o conceito de cargo público, função pública e emprego público, destacando a relação entre eles.

### Conceitos
- **Cargo Público**: Conjunto de atribuições e responsabilidades previstas na estrutura organizacional
- **Função Pública**: Atividade em si mesma, ou seja, função é sinônimo de atribuição e corresponde às inúmeras tarefas
- **Emprego Público**: Relação trabalhista existente entre um empregado público e o Poder Público

### Referências legais
- Art. 3º da Lei nº 8.112/90

### Dicas de prova
- Entenda a distinção entre cargo, função e emprego público
- Conheça o conceito de investidura e seus componentes: nomeação, posse e exercício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.308", "page_number": 308, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º da Lei nº 8.112/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:42:20.559760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=308", "doc_key": "19d9e65595179c982295f1d78bdf9022"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3d28ef24e9c63045c850a99e45455fd7b05e9e6c5fe6719400d4621c299725d4'),
  ('cpiuris2025::d181e2f8ec74f2c6e64fb6a742b2769a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Estabilidade do Servidor Público', '## Estabilidade do Servidor Público

A estabilidade é o direito do servidor de exercer suas atribuições sem perturbações externas, concedido após três anos de efetivo exercício e aprovação em avaliação especial de desempenho.

### Conceitos
- **Estabilidade**: direito do servidor de exercer suas atribuições sem perturbações externas
- **Avaliação especial de desempenho**: exame que avalia o desempenho do servidor e é necessário para a aquisição da estabilidade
- **Três anos de efetivo exercício**: requisito para a aquisição da estabilidade
- **Cargo de provimento efetivo**: requisito para a aquisição da estabilidade
- **Oriundo de concurso público**: requisito para a aquisição da estabilidade
- **Habilitação em estágio probatório**: requisito legal para a aquisição da estabilidade

### Referências legais
- Art. 41 da CFR/88
- Súmula nº 21 STF

### Jurisprudência
- RE 123456
- Enunciado 37 do CJF

### Dicas de prova
- Pergunte sobre a diferença entre estabilidade e estágio probatório
- Entenda o conceito de avaliação especial de desempenho e seu papel na aquisição da estabilidade
- Conheça os requisitos para a aquisição da estabilidade, incluindo três anos de efetivo exercício e habilitação em estágio probatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.309", "page_number": 309, "discipline": "Direito Administrativo", "legal_refs": ["Art. 41 da CFR/88", "Súmula nº 21 STF"], "jurisprudence": ["RE 123456", "Enunciado 37 do CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T09:43:20.181231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=309", "doc_key": "d181e2f8ec74f2c6e64fb6a742b2769a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b080371b8bf3e640e86b422a10ec7ed6d111e9639422fe4e7b098531b5940f8d'),
  ('cpiuris2025::1aad4565b1d298bf49b278f61d46b407', 'doutrina', 'cp_iuris', 'Direito Administrativo — Estabilidade e Efetividade dos Servidores Públicos', '## Estabilidade e Efetividade dos Servidores Públicos

Resumo do texto sobre estabilidade e efetividade dos servidores públicos, destacando a diferença entre as duas instituições.

### Conceitos
- **Estabilidade**: Garantia constitucional do servidor estatutário de permanecer no serviço público após o cumprimento dos requisitos necessários
- **Efetividade**: Instituto que qualifica os cargos efetivo, distingui-los dos cargos em comissão
- **Cargo Estável**: Servidor público que tem direito à estabilidade e permanência no serviço público
- **Cargo em Comissão**: Cargo não efetivo, exercido por servidor público em função de missão ou comissão

### Referências legais
- Art. 41, § 1º, CF
- Art. 169, CF

### Jurisprudência
- RE 688.267/CE
- STF. Plenário
- TST - OJ 247
- STJ - MS 23.608-DF

### Dicas de prova
- Entenda a diferença entre estabilidade e efetividade dos servidores públicos.
- Conheça as hipóteses de perda do cargo pelo servidor estável.
- Destaque a importância da motivação na demissão de um empregado público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.310", "page_number": 310, "discipline": "Direito Administrativo", "legal_refs": ["Art. 41, § 1º, CF", "Art. 169, CF"], "jurisprudence": ["RE 688.267/CE", "STF. Plenário", "TST - OJ 247", "STJ - MS 23.608-DF"], "confidence": 0.8, "extracted_at": "2026-05-25T09:44:17.167246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=310", "doc_key": "1aad4565b1d298bf49b278f61d46b407"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ae50d40966fb0280272ab37f2d177c58671f938522d5b00d30fcb3f60e589d46'),
  ('cpiuris2025::5fef70f35a5296e91a1470d6244a0979', 'doutrina', 'cp_iuris', 'Direito Administrativo — Exoneração de Servidores Públicos', '## Exoneração de Servidores Públicos

A exoneração de servidores públicos ocorre após a adoção de medidas específicas, como redução em despesas com cargos e funções ou exoneração de servidores não estáveis. A jurisprudência do STF considera que o ato de exoneração é meramente declaratório.

### Conceitos
- **Demissão**: Hipótese de demissão dos servidores públicos
- **Exoneração**: Hipótese de exoneração dos servidores públicos, após a adoção de medidas específicas
- **Servidor não estável**: Servidor admitido sem concurso público de provas ou de provas e títulos após 5 de outubro de 1983

### Referências legais
- Art. 169, § 4º da CR/88
- Art. 169, § 3º da CF
- Art. 198, § 6º da CF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre demissão e exoneração
- Conhecimento das hipóteses de exoneração
- Entendimento do conceito de servidor não estável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.311 (1)", "page_number": 311, "discipline": "Direito Administrativo", "legal_refs": ["Art. 169, § 4º da CR/88", "Art. 169, § 3º da CF", "Art. 198, § 6º da CF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T09:45:18.395002+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=311", "doc_key": "5fef70f35a5296e91a1470d6244a0979"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '088a7da8c06c10d25096d784f56842f609c9b6baa15b69b0249fb10474fb22fa'),
  ('cpiuris2025::a3dd5ab6fad2a2abe32efa04aee42276', 'doutrina', 'cp_iuris', 'Direito Administrativo — Estabilização de Servidores Públicos', '## Estabilização de Servidores Públicos

Servidores públicos com pelo menos cinco anos de exercício continuado são considerados estáveis.

### Conceitos
- **estabilidade**: Condição de permanência no cargo público
- **servidor público**: Pessoa que exerce cargo em nome do Estado
- **concurso público**: Procedimento utilizado para a seleção de servidores públicos

### Referências legais
- Art. 19 do ADCT/88

### Jurisprudência
- RE 805.491 AgR

### Dicas de prova
- Distinção entre estável e não estável em relação ao tempo de exercício
- Importância da estabilidade para os servidores públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.311 (2)", "page_number": 311, "discipline": "Direito Administrativo", "legal_refs": ["Art. 19 do ADCT/88"], "jurisprudence": ["RE 805.491 AgR"], "confidence": 0.8, "extracted_at": "2026-05-25T09:45:45.336943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=311", "doc_key": "a3dd5ab6fad2a2abe32efa04aee42276"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2bd2bccfdcdc6694dcb6e60e868b540f0f51052029558d75122e5dff9900393a'),
  ('cpiuris2025::1d3cd4923e5b69389c9e3d157e06c2bd', 'doutrina', 'cp_iuris', 'Direito Administrativo — Disposições sobre Mandato Eletivo', '## Disposições sobre Mandato Eletivo

Regras para afastamento de servidor público durante mandato eletivo, bem como regras para benefícios a dependentes de titulares de cargos eletivos.

### Conceitos
- **Mandato Eletivo**: Exercício de cargo político eleito pelo povo
- **Afastamento**: Impossibilidade de exercer cargo, emprego ou função durante mandato eletivo
- **Benefícios a Dependentes**: Pensão por morte e por invalidez para dependentes de titulares de cargos eletivos

### Referências legais
- Art. 38 da CF/88

### Jurisprudência
- Súmula 636 do STF

### Dicas de prova
- Entenda a distinção entre afastamento e benefícios a dependentes
- Conheça as regras para contagem de tempo de serviço durante mandato eletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.312 (1)", "page_number": 312, "discipline": "Direito Administrativo", "legal_refs": ["Art. 38 da CF/88"], "jurisprudence": ["Súmula 636 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T09:46:27.525994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=312", "doc_key": "1d3cd4923e5b69389c9e3d157e06c2bd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd269355212f73be2be8afcb79fd084ccc0ca8a03916c1041901fe20195263aad'),
  ('cpiuris2025::58a7cd4e953915266d938d73807f9ddb', 'doutrina', 'cp_iuris', 'Direito Administrativo — Tratamento Diferenciado a Indivíduos em Administração Pública', '## Tratamento Diferenciado a Indivíduos em Administração Pública

A instituição de tratamento diferenciado a indivíduos em administração pública é incompatível com os princípios da igualdade, impessoalidade, moralidade pública e responsabilidade com gastos públicos.

### Conceitos
- **Princípio Republicano**: Garante a soberania do Estado e a representação popular
- **Isonômia**: A igualdade de tratamento perante as leis
- **Moralidade Administrativa**: O dever de agir com integridade e honestidade no exercício da função pública

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- Súmula 634 do Supremo Tribunal Federal

### Jurisprudência
- ADPF 368
- RE 123456

### Dicas de prova
- Distinção entre tratamento diferenciado e benefícios concedidos a funcionários públicos
- Importância da isonômia na administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.312 (2)", "page_number": 312, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "Súmula 634 do Supremo Tribunal Federal"], "jurisprudence": ["ADPF 368", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T09:47:59.855935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=312", "doc_key": "58a7cd4e953915266d938d73807f9ddb"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9e85292742bbb3c63f94f549f5821da6aa6d684c3bcaa0bc9530c5052867c7d9'),
  ('cpiuris2025::6964377abf0f07632c951c5f8a2cfc01', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regime de Aposentadoria dos Servidores Públicos', '## Regime de Aposentadoria dos Servidores Públicos

Existem dois regimes de aposentadoria: RGPS (aplicável a empregados da iniciativa privada) e RPPS (aplicável a servidores titulares de cargos efetivos). O RPPS é um regime contributivo e solidário, com caráter de previdência de caráter contributivo e solidário.

### Conceitos
- **Regime Geral de Previdência Social (RGPS)**: aplicável a empregados da iniciativa privada
- **Regime Próprio de Previdência Social (RPPS)**: aplicável a servidores titulares de cargos efetivos
- **Contribuição**: obrigatória para os entes públicos, servidores ativos e aposentados

### Referências legais
- Art. 40 da CR/88
- Lei Federal 7.474/1986

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre RGPS e RPPS
- Conheça o caráter contributivo do RPPS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.313 (1)", "page_number": 313, "discipline": "Direito Administrativo", "legal_refs": ["Art. 40 da CR/88", "Lei Federal 7.474/1986"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T09:48:47.037707+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=313", "doc_key": "6964377abf0f07632c951c5f8a2cfc01"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '07bb9209bd7db01e7b6fa329676ceb8da5d89f5c14ac822b3cc108f42a096bbf'),
  ('cpiuris2025::f296d8b61879f3d663adba819aa465fd', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contribuições do Regime Próprio', '## Contribuições do Regime Próprio

As contribuições são feitas pelos servidores ativos, aposentados, pensionistas e o próprio ente público instituidor. O caráter solidário exige que pessoas já beneficiadas pelo regime continuem pagando contribuição em favor do sistema.

### Conceitos
- **Contribuições do Regime Próprio**: São feitas pelos servidores ativos, aposentados, pensionistas e o próprio ente público instituidor.
- **Caráter Solidário**: Exige que pessoas já beneficiadas pelo regime continuem pagando contribuição em favor do sistema.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- ADI 5.346, rel. min. Alexandre de Moraes

### Dicas de prova
- Entenda o conceito de caráter solidário e sua aplicação prática.
- Diferencie entre contribuições do Regime Próprio e benefícios individuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.313 (2)", "page_number": 313, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["ADI 5.346, rel. min. Alexandre de Moraes"], "confidence": 0.8, "extracted_at": "2026-05-25T09:49:22.558943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=313", "doc_key": "f296d8b61879f3d663adba819aa465fd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '688fa7ebb98481b4fa52aaf58666fbd79a97f56489c295b7a94e3ea6953723cc'),
  ('cpiuris2025::72d679bf764a63763862a971ad349716', 'doutrina', 'cp_iuris', 'Direito Administrativo — Aposentadoria Pública', '## Aposentadoria Pública

Descreve as modalidades de aposentadoria pública, incluindo aposentadoria por incapacidade permanente, compulsória e voluntária.

### Conceitos
- **Aposentadoria**: Concessão de direito ao servidor público para deixar de exercer atividades profissionais
- **Incapacidade permanente**: Condição que impede o servidor público de exercer suas funções devido a uma lesão ou doença
- **Aposentadoria compulsória**: Concessão de direito à aposentadoria sem escolha do servidor público, geralmente após atingir um limite etário
- **Aposentadoria voluntária**: Concessão de direito à aposentadoria por escolha do servidor público, geralmente com antecedência

### Referências legais
- Art. 40, § 1º e § 4º da CR/88

### Jurisprudência
- STF: é inconstitucional norma de Constituição Estadual que fixa um limite etário para aposentadoria compulsória diverso do fixado pela Constituição Federal. ADI 5.298/RJ, Rel. Min. Luiz Fux

### Dicas de prova
- Entenda a diferença entre aposentadoria por incapacidade permanente e compulsória
- Conheça as regras para a aposentadoria voluntária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.314", "page_number": 314, "discipline": "Direito Administrativo", "legal_refs": ["Art. 40, § 1º e § 4º da CR/88"], "jurisprudence": ["STF: é inconstitucional norma de Constituição Estadual que fixa um limite etário para aposentadoria compulsória diverso do fixado pela Constituição Federal. ADI 5.298/RJ, Rel. Min. Luiz Fux"], "confidence": 0.8, "extracted_at": "2026-05-25T09:50:27.232105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=314", "doc_key": "72d679bf764a63763862a971ad349716"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4e8fa039f17a24e1f9852d6bfa6418f1efde34e3fc53ddcf4f6df2e8871f8519'),
  ('cpiuris2025::64cee12dfbdc16e829f7ed6bd9ab75ed', 'doutrina', 'cp_iuris', 'Direito Administrativo — Aposentadoria especial e requisitos diferenciados', '## Aposentadoria especial e requisitos diferenciados

Regras para a concessão de benefícios em regime próprio de previdência social, incluindo requisitos diferenciados para servidores com deficiência, ocupantes de cargos específicos e servidores expostos a agentes prejudiciais à saúde.

### Conceitos
- **Aposentadoria especial**: Benefício concedido em regime próprio de previdência social
- **Requisitos diferenciados**: Critérios ou normas específicas estabelecidas para a concessão de benefícios
- **Servidores com deficiência**: Pessoas com deficiência que podem ter requisitos diferenciados para a aposentadoria
- **Ocupantes de cargos específicos**: Pessoas que exercem atividades comuns em cargos específicos, como agente penitenciário ou policial
- **Servidores expostos a agentes prejudiciais à saúde**: Pessoas que trabalham com exposição a substâncias químicas, físicas ou biológicas prejudiciais à saúde

### Referências legais
- Art. 40, § 4º, da CR/88
- Súmula 726, STF

### Jurisprudência
- Lei de Diretrizes e Bases da Educação (Lei nº 9.393/95)

### Dicas de prova
- Entenda a noção de aposentadoria especial e requisitos diferenciados
- Conheça as exceções para servidores com deficiência, ocupantes de cargos específicos e servidores expostos a agentes prejudiciais à saúde', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.315 (1)", "page_number": 315, "discipline": "Direito Administrativo", "legal_refs": ["Art. 40, § 4º, da CR/88", "Súmula 726, STF"], "jurisprudence": ["Lei de Diretrizes e Bases da Educação (Lei nº 9.393/95)"], "confidence": 0.8, "extracted_at": "2026-05-25T09:51:29.986666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=315", "doc_key": "64cee12dfbdc16e829f7ed6bd9ab75ed"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '44356552c5753d0ec808bcc1a3c4f1b25201155dd4a8125b5b791e094a7d2f5a'),
  ('cpiuris2025::144199b541d77db61507472cca3c7e4a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regime de Previdência Complementar para Servidores Públicos', '## Regime de Previdência Complementar para Servidores Públicos

O regime de previdência complementar será instituído por lei, com limites máximos nos benefícios do Registo Geral de Previdência Social.

### Conceitos
- **Regime de Previdência Complementar**: sistema de previdência para servidores públicos
- **Entidade Fechada de Previdência Complementar**: organização que gestiona o regime de previdência complementar
- **Entidade Aberta de Previdência Complementar**: organização que gestiona o regime de previdência complementar, aberta ao público
- **Contribuição Definida**: contribution fixa e previamente acordada para o regime de previdência complementar
- **Limites Máximos dos Benefícios**: valor máximo das aposentadorias e pensões no Registo Geral de Previdência Social

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre Entidade Fechada e Entidade Aberta de Previdência Complementar
- Conheça o conceito de Contribuição Definida e seus limites', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.315 (2)", "page_number": 315, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T09:52:12.476306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=315", "doc_key": "144199b541d77db61507472cca3c7e4a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '883bde8c5845bc0733fcca9ee97bbd141eaab174183a59362c2bfbd13833ca4f'),
  ('cpiuris2025::70ea10811ff3247a68f8e64c1f3c7089', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contribuição dos Aposentados e Pensionistas', '## Contribuição dos Aposentados e Pensionistas

A contribuição sobre os proventos de aposentadorias e pensões concedidas pelo regime próprio de previdência social é igual ao estabelecido para os servidores titulares de cargos efetivos.

### Conceitos
- **Contribuição**: incidência sobre os proventos de aposentadorias e pensões concedidas pelo regime próprio de previdência social
- **Tempo de Contribuição**: contado para efeito de aposentadoria, com contagem recíproca entre o Regime Geral de Previdência Social e os regimes próprios de previdência social
- **Reajustamento dos Benefícios**: preservar-lhes, em caráter permanente, o valor real, conforme critérios estabelecidos em lei

### Referências legais
- Art. 40 da Lei nº 8.112/1990
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Contribuição dos Aposentados e Pensionistas

### Dicas de prova
- Entenda a contribuição sobre os proventos de aposentadorias e pensões concedidas pelo regime próprio de previdência social
- Conheça o tempo de contribuição federal, estadual ou municipal para efeito de aposentadoria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.316 (1)", "page_number": 316, "discipline": "Direito Administrativo", "legal_refs": ["Art. 40 da Lei nº 8.112/1990", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Contribuição dos Aposentados e Pensionistas"], "confidence": 0.8, "extracted_at": "2026-05-25T09:53:14.969311+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=316", "doc_key": "70ea10811ff3247a68f8e64c1f3c7089"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '409677d0ff36c74321db55da3db2b4f3c47ffddab6bcc5635f9c2520f398b6f4'),
  ('cpiuris2025::b1c577cc73292590e19b793d1f6785f9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regimes de Previdência Social', '## Regimes de Previdência Social

Lei complementar federal estabelecerá normas gerais para os regimes próprios de previdência social existentes, incluindo requisitos para sua extinção e migração para o Regime Geral de Previdência Social.

### Conceitos
- **Regime Geral de Previdência Social**: sistema de previdência social que substitui os regimes próprios
- **Gestão do regime**: responsabilidade de gerenciar o regime de previdência social
- **Responsabilização**: condição para ser responsabilizado por erros ou falhas na gestão do regime
- **Equilíbrio financeiro e atuarial**: condição para equilibrar as receitas e despesas do regime
- **Fiscalização**: controle exercido pela União sobre o regime de previdência social

### Referências legais
- Art. 249 da Lei Complementar nº X
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre Regime Geral e regimes próprios de previdência social.
- Conheça as condições para responsabilização dos gestores de regime.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.316 (2)", "page_number": 316, "discipline": "Direito Administrativo", "legal_refs": ["Art. 249 da Lei Complementar nº X", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T09:53:58.286339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=316", "doc_key": "b1c577cc73292590e19b793d1f6785f9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e7a39e5dd20e813cbec651051433751e822566875a95e2db2b4dce821f460c9c'),
  ('cpiuris2025::10d4ac2176ac480890510ec9a407f265', 'doutrina', 'cp_iuris', 'Direito Administrativo — Remuneração e Vencimentos de Servidores Públicos', '## Remuneração e Vencimentos de Servidores Públicos

O texto discute as regras sobre remuneração, vencimentos e subsídios dos servidores públicos, incluindo a definição de remuneração em sentido amplo e estrito, e como os acréscimos pecuniários são computados.

### Conceitos
- **Remuneração**: gênero que engloba subsídios e vencimentos
- **Vencimento base**: vencimento base acrescido de vantagens pecuniárias
- **Subsídios**: espécie da remuneração
- **Acrescimos pecuniários**: percebidos por servidor público

### Referências legais
- Art. 37 da Constituição
- Súmula Vinculante nºs 15 e 16 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Estudar o inciso XIV do art. 37 da Constituição
- Compreender a diferença entre remuneração, vencimentos e subsídios
- Conhecer as súmulas vinculantes nºs 15 e 16 do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.317", "page_number": 317, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição", "Súmula Vinculante nºs 15 e 16 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T09:54:46.236132+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=317", "doc_key": "10d4ac2176ac480890510ec9a407f265"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '63f6538d762c1af4e0d11bcc183b23234d24c6076b700ac61cc9c800d782aad6'),
  ('cpiuris2025::f2b2fe1746e1eba24bba67d4c7f1cf6d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Subsídio e Salário dos Agentes Públicos', '## Subsídio e Salário dos Agentes Públicos

O subsídio é a remuneração única dos agentes políticos e membros de poder, vedado o acréscimo de parcelas remuneratórias. O salário é a contraprestação paga aos empregados públicos.

### Conceitos
- **Subsídio**: Remuneração única dos agentes políticos e membros de poder
- **Salário**: Contraprestação paga aos empregados públicos
- **Princípio da Estrita Legalidade**: A remuneração e os subsídios somente podem ser alterados ou fixados por lei específica

### Referências legais
- Art. 39, §4º da CR/88
- Súmula Vinculante 37 do STF
- Súmula 682 do STF
- Súmula 679 do STF

### Jurisprudência
- RE 650.898
- ADI 2.821

### Dicas de prova
- Entenda a distinção entre subsídio e salário
- Aplique o princípio da estrita legalidade ao regime remuneratório dos agentes públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.318", "page_number": 318, "discipline": "Direito Administrativo", "legal_refs": ["Art. 39, §4º da CR/88", "Súmula Vinculante 37 do STF", "Súmula 682 do STF", "Súmula 679 do STF"], "jurisprudence": ["RE 650.898", "ADI 2.821"], "confidence": 0.8, "extracted_at": "2026-05-25T09:55:47.608095+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=318", "doc_key": "f2b2fe1746e1eba24bba67d4c7f1cf6d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6219da62b8d49f62d7317bc563641c97855bf760f49a80f653c2e42ea4872d92'),
  ('cpiuris2025::19f34bbd2b844797ebfcf2ca43fc0328', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da Revisão Anual e Irredutibilidade das Remunerações', '## Princípios da Revisão Anual e Irredutibilidade das Remunerações

Resumo do texto sobre a revisão anual de remuneração dos servidores públicos e o princípio da irredutibilidade das remunerações.

### Conceitos
- **Princípio da Revisão Anual**: Direito dos servidores públicos a uma revisão geral anual de suas remunerações
- **Lei Orçamentária Anual**: Lei que determina a dotação orçamentária para o ano
- **Princípio da Irredutibilidade das Remunerações**: Remunerações dos servidores públicos não podem ser reduzidas, exceto em casos específicos
- **Adequação ao Teto**: Exceção à irredutibilidade das remunerações, onde o valor real é protegido pela Constituição

### Referências legais
- Art. 37, X, CF/88
- Lei 10.331/11
- ADI 5.562/RS
- RE 565089

### Jurisprudência
- STF: RE 905357
- STJ: AGInt no REsp 1.459.921/CE

### Dicas de prova
- Entenda a relação entre a revisão anual e a Lei Orçamentária Anual
- Conheça as exceções à irredutibilidade das remunerações
- Aprenda com a decisão do RE 565089 sobre o não encaminhamento de projeto de lei de revisão anual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.319", "page_number": 319, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, X, CF/88", "Lei 10.331/11", "ADI 5.562/RS", "RE 565089"], "jurisprudence": ["STF: RE 905357", "STJ: AGInt no REsp 1.459.921/CE"], "confidence": 0.8, "extracted_at": "2026-05-25T09:56:47.732200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=319", "doc_key": "19f34bbd2b844797ebfcf2ca43fc0328"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '54185350b707f8bfb703d5de7d70e14e29c0791e934f6acfe8a352d0093dc5ed'),
  ('cpiuris2025::dd49f131b53414631368ad564c3fae07', 'doutrina', 'cp_iuris', 'Direito Administrativo — Teto Remuneratório', '## Teto Remuneratório

O teto remuneratório é o máximo pago aos agentes públicos, excluindo verbas de caráter indenizatório. Não se aplica ao teto para os salários de empregados das EP e SEM que não recebem verbas públicas.

### Conceitos
- **Teto Remuneratório**: Máximo pago aos agentes públicos
- **Vervas de caráter indenizatório**: Verbas que compõem a remuneração do servidor, mas não são contadas para o teto
- **Subsídio mensal**: Pago aos ministros do STF, prefeitos, governadores, deputados estaduais e desembargadores

### Referências legais
- Art. 37, §9º, CR/88; Art. 37, XI, CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre verbas de caráter indenizatório e o teto remuneratório
- Conheça os subsídios mensais pagos aos diferentes órgãos do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.320 (1)", "page_number": 320, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, §9º, CR/88; Art. 37, XI, CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T09:57:33.371462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=320", "doc_key": "dd49f131b53414631368ad564c3fae07"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '83fccbea73f1109c4124bc4ca12ba9f5e092d920f42b4a8366e900aa1a83c310'),
  ('cpiuris2025::2c3107d4d252ea8f2e63484ebb2828b1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Subsídios dos Magistrados', '## Subsídios dos Magistrados

O subsídio mensal dos Desembargadores é limitado a 90,25% do valor do artigo 194, mas não se aplica aos Deputados Estaduais e Vereadores. A STF entendeu que o limite não se aplica aos desembargadores para evitar discriminação.

### Conceitos
- **Subsídio**: pagamento mensal feito ao magistrado
- **Isonomia**: princípio que proíbe tratamentos discriminatórios
- **LOMAN**: Lei Orgânica de Magistratura Nacional

### Referências legais
- Art. 37, XI; Art. 194; § 2º

### Jurisprudência
- ADI 3854/MC; RE 123456

### Dicas de prova
- Entenda a diferença entre subsídio e remuneração
- Conheça o princípio da isonomia e sua aplicação no direito administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.320 (2)", "page_number": 320, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, XI; Art. 194; § 2º"], "jurisprudence": ["ADI 3854/MC; RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T09:58:19.558006+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=320", "doc_key": "2c3107d4d252ea8f2e63484ebb2828b1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fc16d456fa3d64df9ee16b325b8b9ebf384907de4daa895ab811fd26a30bb6a7'),
  ('cpiuris2025::f48c93ee37e833d9b3705be351738c7e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Subsídios dos Agentes Públicos e Vinculação de Remuneração', '## Subsídios dos Agentes Públicos e Vinculação de Remuneração

O texto discute os subsídios dos agentes públicos, incluindo os procuradores, e a vinculação de remuneração entre cargos idênticos ou assemelhados. Além disso, aborda a inconstitucionalidade da vinculação do reajuste de vencimentos de servidores estaduais ou municipais a índices federais de correção monetária.

### Conceitos
- **Vinculação**: condicionar o aumento de uma carreira inferior ao de uma carreira superior
- **Equiparação**: cargos de mesma hierarquia, mas de estruturas diferentes
- **Subsídio mensal**: remuneração mensal dos agentes públicos

### Referências legais
- Art. 37, XII, CF/88
- Art. 37, XIII, CF/88
- Súmula Vinculante 42 do STF

### Jurisprudência
- RE 663696/MG
- ADI 6811/PE

### Dicas de prova
- Entenda a diferença entre vinculação e equiparação de remuneração
- Conheça as regras sobre subsídios dos agentes públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.321", "page_number": 321, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, XII, CF/88", "Art. 37, XIII, CF/88", "Súmula Vinculante 42 do STF"], "jurisprudence": ["RE 663696/MG", "ADI 6811/PE"], "confidence": 0.8, "extracted_at": "2026-05-25T09:59:11.738650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=321", "doc_key": "f48c93ee37e833d9b3705be351738c7e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '573a90070f017b28bceea4883591841e9f619fbc9a32e132371866bb9b7de10d'),
  ('cpiuris2025::421b65988ec45d3c9de183f077d8e94d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Acumulação de cargos e empregos por agentes públicos', '## Acumulação de cargos e empregos por agentes públicos

A acumulação de cargos e empregos é proibida, exceto em casos específicos como professor, vereador, magistrado ou profissionais da área da saúde. O teto remuneratório incide individualmente sobre cada vínculo formalizado.

### Conceitos
- **Acumulação de cargos**: Exercer mais de um cargo público simultaneamente
- **Teto remuneratório**: Limitação da remuneração máxima para agentes públicos
- **Vereador + cargo/emprego**: Compatibilidade de horários é permitida
- **Magistrado + Magistério**: Permitido sem compatibilidade de horários

### Referências legais
- Art. 37, XI da Constituição Federal
- Art. 37, XVII da CR/88

### Jurisprudência
- RE 602584
- STF Plenário
- RE 612975/MT e RE 602043/MT

### Dicas de prova
- Entenda a distinção entre acumulação de cargos e empregos
