  ('cpiuris2025::872b0e04ca495ae8e65450d0773ffb4f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Cumulação de Aposentadorias e Proventos Públicos', '## Cumulação de Aposentadorias e Proventos Públicos

A percepção de mais de uma aposentadoria à conta do regime de previdência previsto no artigo 40 da Constituição Federal é vedada, exceto em casos específicos como cargos acumuláveis, cargos em comissão e cargos eletivos.

### Conceitos
- **Cargos Acumuláveis**: cargos que permitem a cumulação de remuneração e proventos
- **Cargo em Comissão**: cargo que não é vinculado a um cargo público específico
- **Cargos Eletivos**: cargos eleitos pelo voto popular
- **Remuneração Pública**: remuneração recebida por um cargo público
- **Proventos Públicos**: proventos recebidos por um servidor público

### Referências legais
- Art. 40, § 10º da CR/88
- Art. 37, § 10, CF/88
- EC nº 20/98

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre cargos acumuláveis e não acumuláveis
- Entender a diferença entre remuneração pública e proventos públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.323 (1)", "page_number": 323, "discipline": "Direito Administrativo", "legal_refs": ["Art. 40, § 10º da CR/88", "Art. 37, § 10, CF/88", "EC nº 20/98"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T10:01:01.746406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=323", "doc_key": "872b0e04ca495ae8e65450d0773ffb4f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '538a826bb5e769df600d3e2519f7f011561c971e13f8b6e471908a89eba64f7b'),
  ('cpiuris2025::decd22396be9b95c68b698e610242923', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle judicial sobre a correção de questões em Concurso Público', '## Controle judicial sobre a correção de questões em Concurso Público

O STF reafirma que não cabe controle judicial sobre a correção das questões em concurso público, pois isso seria controle de mérito, inadmissível para o Poder Judiciário.

### Conceitos
- **Controle de legalidade**: Verificação se a matéria cobrada na questão está ou não no programa do edital do concurso
- **Controle de mérito**: Avaliação da correção das questões em concurso público, que é inadmissível para o Poder Judiciário

### Referências legais
- Art. 102 do CC
- ...

### Jurisprudência
- RE N. 632.853-CE
- Súmula 332 STF

### Dicas de prova
- Distinção entre controle de legalidade e controle de mérito
- Importância da verificação se a matéria está no programa do edital', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.323 (2)", "page_number": 323, "discipline": "Direito Administrativo", "legal_refs": ["Art. 102 do CC", "..."], "jurisprudence": ["RE N. 632.853-CE", "Súmula 332 STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:01:36.400635+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=323", "doc_key": "decd22396be9b95c68b698e610242923"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9ee20560c96ed062aba524817592300ad875710df53237b9a828317034929435'),
  ('cpiuris2025::f670041ec5b173e78a1da25262858abd', 'doutrina', 'cp_iuris', 'Direito Administrativo — Direito subjetivo à nomeação do candidato aprovado dentro do número de vagas e o Cadastro de Reservas', '## Direito subjetivo à nomeação do candidato aprovado dentro do número de vagas e o Cadastro de Reservas

O candidato aprovado dentro do número de vagas tem direito subjetivo à nomeação, mas existem situações excepcionais que justificam soluções diferenciadas, desde que motivadas pelo interesse público.

### Conceitos
- **Vinculação ao edital**: A administração pública está vinculada ao número de vagas previstas no edital.
- **Princípio da segurança jurídica**: O princípio que exige a estabilidade e previsibilidade das normas e atos administrativos.
- **Confiança legítima**: Subprincípio do princípio da segurança jurídica, que se refere à confiança depositada pela parte com a administração pública.
- **Situações excepcionais**: Eventos extraordinários e imprevisíveis que justificam soluções diferenciadas devidamente motivadas pelo interesse público.
- **Superveniência**: A situação deve ser necessariamente posterior à publicação do edital do certame público.
- **Imprevisibilidade**: A situação deve ser determinada por circunstâncias extraordinárias à época da publicação do edital.
- **Gravidade**: Os acontecimentos extraordinários e imprevisíveis devem ser extremamente graves, implicando onerosidade excessiva, dificuldade ou mesmo impossibilidade de cumprimento efetivo das regras do edital.
- **Necessidade**: A administração somente pode adotar tal medida quando não existirem outros meios menos gravosos para lidar com a situação excepcional e imprevisível.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- Súmula 636 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 598099

### Dicas de prova
- Entenda o conceito de vinculação ao edital e como ele se relaciona com a segurança jurídica.
- Conheça as características das situações excepcionais e como elas justificam soluções diferenciadas.
- Aprenda a distinguir entre a superveniência, imprevisibilidade, gravidade e necessidade em situações excepcionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.324 (1)", "page_number": 324, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "Súmula 636 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 598099"], "confidence": 0.8, "extracted_at": "2026-05-25T10:03:02.171087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=324", "doc_key": "f670041ec5b173e78a1da25262858abd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd63e0ecd6d640ad434eb18e0b21ac83fab4f5f3784b86347f74fcad50c67ca04'),
  ('cpiuris2025::bcf1888243290bb52d556356210be135', 'doutrina', 'cp_iuris', 'Direito Administrativo — Direito subjetivo à nomeação e o surgimento de novas vagas durante o prazo de validade', '## Direito subjetivo à nomeação e o surgimento de novas vagas durante o prazo de validade

A existência de vagas no concurso deve garantir preferência aos candidatos com melhor classificação. A jurisprudência sobre o surgimento de novas vagas durante o prazo de validade é contraditória.

### Conceitos
- **Direito subjetivo à nomeação**: O direito do candidato aprovado a ser nomeado para uma vaga
- **Concurso público**: Processo em que a Administração Pública convoca candidatos para preencher vagas
- **Vagas do edital**: As vagas previstas no edital do concurso
- **Administração**: O ente público responsável por convocar candidatos para preencher vagas

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- Súmula 137 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 837311/PI
- RMS 71.656/RO

### Dicas de prova
- Entenda a distinção entre vagas do edital e novas vagas durante o prazo de validade.
- Conheça as decisões dos tribunais superiores sobre o direito subjetivo à nomeação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.324 (2)", "page_number": 324, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "Súmula 137 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 837311/PI", "RMS 71.656/RO"], "confidence": 0.8, "extracted_at": "2026-05-25T10:04:01.023136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=324", "doc_key": "bcf1888243290bb52d556356210be135"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '41597f1551296de3319ef57992d997ebe8813188b486711f8675ccaa6cf5c41c')
